  'Don\'t bin it yet! 🥬 Wilted spinach is perfect cooked: toss it into an omelette with your eggs and cheddar, or blend it into a smoothie with the banana that needs eating today 🍌': ['Не выбрасывай! 🥬 Вялый шпинат отлично подойдёт для готовки: добавь его в омлет с яйцами и чеддером или в смузи с бананом, который надо съесть сегодня 🍌', 'Тастама! 🥬 Солған шпинат пісіруге тамаша: жұмыртқа мен чеддер қосып омлетке сал немесе бүгін жеу керек бананмен смузи жаса 🍌'],
  'Don\'t waste food, nya!': ['Не выбрасывай еду, мяу!', 'Тағамды ысырап етпе, мияу!'],
