  'Eat': ['Съесть', 'Жеу'],
  'Eat and cook your food to build your score!': ['Ешь и готовь свои продукты, чтобы набрать баллы!', 'Ұпай жинау үшін өнімдеріңді же және пісір!'],
  'Eat or cook your first product': ['Съешь или приготовь первый продукт', 'Алғашқы өнімді же немесе пісір'],
  'Eat the {0} today, please! 🥺': ['Съешь сегодня: {0}, пожалуйста! 🥺', 'Бүгін жеп қойшы: {0}! 🥺'],
  'Eat today: {0}': ['Съешь сегодня: {0}', 'Бүгін же: {0}'],
  'Eat well · waste less · save the planet': ['Ешь вкусно · выбрасывай меньше · береги планету', 'Дұрыс жеп · аз таста · планетаны сақта'],
