  'Erase': ['Стереть', 'Өшіру'],
  'Erase all data': ['Стереть все данные', 'Барлық деректерді өшіру'],
  'Erase all data?': ['Стереть все данные?', 'Барлық деректерді өшіру керек пе?'],
  'Estimates: 0.3 kg per product, 2.5 kg CO₂ per kg of food.': ['Оценка: 0,3 кг на продукт, 2,5 кг CO₂ на кг еды.', 'Бағалау: бір өнімге 0,3 кг, 1 кг тағамға 2,5 кг CO₂.'],
  'Estimates: about 300 g per product, average prices, about 2.5 kg of CO₂ per kg of food. Sources: UNEP Food Waste Index, FAO.': ['Оценки: около 300 г на продукт, средние цены, около 2,5 кг CO₂ на 1 кг еды. Источники: UNEP Food Waste Index, FAO.', 'Бағалау: бір өнімге шамамен 300 г, орташа бағалар, 1 кг тағамға шамамен 2,5 кг CO₂. Дереккөздер: UNEP Food Waste Index, FAO.'],
  'Euro': ['Евро', 'Еуро'],
  'Everything is fresh! You\'re a zero-waste star ⭐': ['Всё свежее! Ты звезда zero-waste ⭐', 'Бәрі балғын! Сен — қалдықсыз өмір жұлдызысың ⭐'],
  'Everything is saved on this iPhone automatically. Reinstalling the app on top keeps your data.': ['Всё сохраняется на этом iPhone автоматически. Переустановка приложения поверх сохраняет данные.', 'Барлығы осы iPhone-да автоматты түрде сақталады. Қолданбаны үстінен қайта орнатсаң, деректер сақталады.'],
  'Everything you own, sorted by urgency. Swipe right to eat, left to throw away. Filter by fridge, freezer or pantry.': ['Всё, что у тебя есть, по срочности. Смахни вправо — съесть, влево — выбросить. Фильтр: холодильник, морозилка или шкаф.', 'Бар өнімдерің — шұғылдығы бойынша. Оңға сырғыт — жеу, солға — тастау. Сүзгі: тоңазытқыш, мұздатқыш немесе қойма.'],
  'Expired': ['Просрочено', 'Мерзімі өткен'],
  'Expired {0} ago': ['Просрочено {0} назад', 'Мерзімі {0} бұрын өтті'],
