  'Female': ['Женский', 'Әйел'],
  'Fill my fridge with demo products': ['Заполнить холодильник демо-продуктами', 'Тоңазытқышты демо-өнімдермен толтыру'],
  'Fill my fridge! 🧺': ['Заполни холодильник! 🧺', 'Тоңазытқышты толтыр! 🧺'],
