  'Five more minutes...': ['Ещё пять минуточек...', 'Тағы бес минут...'],
  'Food diary': ['Дневник питания', 'Тамақ күнделігі'],
  'Food log': ['Журнал', 'Журнал'],
  'Food rescued deliciously!': ['Еда спасена — и вкусно!', 'Тағам дәмді құтқарылды!'],
  'Food saved': ['Еды спасено', 'Сақталған тағам'],
  'Food saved! 🦸': ['Еда спасена! 🦸', 'Тағам құтқарылды! 🦸'],
  'Food waste causes 8–10% of global greenhouse gas emissions.': ['Пищевые отходы дают 8–10% мировых выбросов парниковых газов.', 'Тағам қалдығы әлемдік парниктік газ шығарындыларының 8–10%-ын құрайды.'],
  'For you': ['Для тебя', 'Саған'],
  'Forgot about it': ['Забыл о нём', 'Ұмытып кеттім'],
  'Found': ['Найдено', 'Табылды'],
  'Found {0}. Check the amounts and tap Add 👇': ['Нашёл {0}. Проверь количество и нажми «Добавить» 👇', '{0} таптым. Санын тексеріп, «Қосу» батырмасын бас 👇'],
  'Free AI answers in chat. AI answers can be wrong. Sends only your name, fridge, today\'s kcal and the last messages.': ['Бесплатные ответы ИИ в чате. ИИ может ошибаться. Отправляются только имя, холодильник, калории за сегодня и последние сообщения.', 'Чатта тегін ЖИ жауаптары. ЖИ қателесуі мүмкін. Тек атың, тоңазытқыш, бүгінгі калория және соңғы хабарламалар жіберіледі.'],
  'Freeze': ['Заморозить', 'Мұздату'],
  'Freeze 3 products before they spoil': ['Заморозь 3 продукта, пока они не испортились', 'Бұзылмай тұрып 3 өнімді мұздат'],
  'Freeze all': ['Заморозить всё', 'Бәрін мұздату'],
  'Freeze bread and milk before they expire. Future you says thanks!': ['Замораживай хлеб и молоко до конца срока. Ты из будущего скажет спасибо!', 'Нан мен сүтті мерзімі біткенше мұздат. Болашақтағы сен рахмет айтады!'],
  'Freeze leftovers in single portions — instant lunch later.': ['Замораживай остатки порциями — потом будет готовый обед.', 'Қалған тағамды порциялап мұздат — кейін дайын түскі ас.'],
  'Freezer': ['Морозилка', 'Мұздатқыш'],
  'Fresh': ['Свежее', 'Балғын'],
  'Fridge': ['Холодильник', 'Тоңазытқыш'],
