  'Fridge health': ['Здоровье холодильника', 'Тоңазытқыш күйі'],
  'Fridge is empty': ['Холодильник пуст', 'Тоңазытқыш бос'],
  'Fridge, diary, weight, shopping list and medals will be deleted. This cannot be undone.': ['Холодильник, дневник, вес, список покупок и медали будут удалены. Это нельзя отменить.', 'Тоңазытқыш, күнделік, салмақ, сатып алу тізімі және медальдар өшіріледі. Мұны қайтару мүмкін емес.'],
