  'Goal: {0} kcal/day': ['Цель: {0} ккал/день', 'Мақсат: {0} ккал/күн'],
  'Good Neighbor': ['Добрый сосед', 'Жақсы көрші'],
  'Good afternoon': ['Добрый день', 'Қайырлы күн'],
  'Good evening': ['Добрый вечер', 'Қайырлы кеш'],
  'Good morning': ['Доброе утро', 'Қайырлы таң'],
  'Good nap!': ['Хорошо поспал!', 'Жақсы ұйықтадым!'],
  'Good night': ['Доброй ночи', 'Қайырлы түн'],
  'Good week! A little better every week is the Nutrik way 🐾': ['Хорошая неделя! Каждую неделю чуть лучше — это путь Нутрика 🐾', 'Жақсы апта! Әр апта сайын сәл жақсырақ — Нутриктің жолы осы 🐾'],
  'Got it, {0}! I\'ll skip recipes with "{1}" from now on. 👍': ['Понял, {0}! Больше не буду предлагать рецепты с «{1}». 👍', 'Түсіндім, {0}! Енді «{1}» бар рецепттерді ұсынбаймын. 👍'],
  'Got it, {0}! I\'ll skip recipes with "{1}" from now on. 👍\nChanged your mind? Say "I like {1} again".': ['Понял, {0}! Больше не предлагаю рецепты с «{1}». 👍\nПередумаешь — напиши «снова люблю {1}».', 'Түсіндім, {0}! Енді «{1}» бар рецепттерді ұсынбаймын. 👍\nОйың өзгерсе, «{1} қайта ұнайды» деп жаз.'],
  'Grains': ['Крупы', 'Жармалар'],
  'Great plan! Add an extra snack: nuts, kurt, yogurt, peanut butter toast 🥜 Small steps every day.': ['Отличный план! Добавь лишний перекус: орехи, курт, йогурт, тост с арахисовой пастой 🥜 Маленькие шаги каждый день.', 'Тамаша жоспар! Қосымша тағам қос: жаңғақ, құрт, йогурт, жержаңғақ майы жағылған тост 🥜 Күн сайын кішкене қадам.'],
  'Guest account': ['Гостевой аккаунт', 'Қонақ аккаунты'],
  'Have 10 products in your fridge': ['Держи 10 продуктов в холодильнике', 'Тоңазытқышта 10 өнім болсын'],
  'Healthy': ['Норма', 'Қалыпты'],
  'Healthy weight': ['Здоровый вес', 'Қалыпты салмақ'],
  'Healthy weight for {0} cm: {1}–{2} kg': ['Здоровый вес при росте {0} см: {1}–{2} кг', '{0} см бойға сау салмақ: {1}–{2} кг'],
  'Height': ['Рост', 'Бойы'],
  'Height: {0} cm': ['Рост: {0} см', 'Бойы: {0} см'],
  'Hello, human!': ['Здравствуй, человек!', 'Сәлем, адам!'],
  'Hello, night owl': ['Привет, сова', 'Сәлем, түнгі құс'],
  'Hero move! ❄️': ['Геройский поступок! ❄️', 'Батырлық қадам! ❄️'],
  'Hey! I was sleeping 😾': ['Эй! Я спал 😾', 'Әй! Мен ұйықтап жатыр едім 😾'],
  'Hey! Put me down! 🙀': ['Эй! Поставь меня! 🙀', 'Әй! Мені түсір! 🙀'],
  'Hi again! This is Home. I show what to eat first, your calories today and the money at risk. Tap "Ask Nutrik" to chat with me!': ['Снова привет! Это Главная. Здесь я показываю, что съесть в первую очередь, калории за сегодня и деньги под угрозой. Нажми «Спроси Нутрика», чтобы поболтать со мной!', 'Тағы сәлем! Бұл — Басты бет. Мұнда алдымен не жеу керегін, бүгінгі калорияны және жоғалуы мүмкін ақшаны көрсетемін. Менімен сөйлесу үшін «Нутриктен сұра» түймесін бас!'],
  'Hi there! 👋': ['Привет! 👋', 'Сәлем! 👋'],
  'Hi! I\'m Nutrik 🐾 I help people stop wasting food. Nice to meet you!': ['Привет! Я Нутрик 🐾 Помогаю людям не выбрасывать еду. Рад знакомству!', 'Сәлем! Мен Нутрикпін 🐾 Адамдарға тағамды текке шашпауға көмектесемін. Танысқаныма қуаныштымын!'],
  'Hi! I\'m Nutrik 🐾 your zero-waste kitchen buddy. About a third of the world\'s food ends up in the bin. Let\'s make sure yours doesn\'t! Want a quick tour?': ['Привет! Я Нутрик 🐾 твой помощник на кухне без отходов. Около трети всей еды в мире оказывается в мусорке. Давай сделаем так, чтобы твоя туда не попала! Показать, что здесь где?', 'Сәлем! Мен Нутрикпін 🐾 қалдықсыз ас үйдегі көмекшің. Әлемдегі тағамның шамамен үштен бірі қоқысқа кетеді. Сенікі кетпейтіндей етейік! Қысқаша таныстырайын ба?'],
  'Hi! I\'m your AI Chef 👩‍🍳 Ask me what to cook, what expires soon, how to store food — or tell me what you don\'t like.': ['Привет! Я твой ИИ-шеф 👩‍🍳 Спроси, что приготовить, что скоро испортится, как хранить продукты, — или скажи, что ты не любишь.', 'Сәлем! Мен сенің ЖИ-аспазыңмын 👩‍🍳 Не пісіруді, ненің мерзімі жақында бітетінін, өнімді қалай сақтауды сұра — немесе не ұнамайтынын айт.'],
  'Hi, {0}! I\'m Nutrik 🐾 Ask me what to cook, what expires soon, how to store food — or tell me what you don\'t like.': ['Привет, {0}! Я Нутрик 🐾 Спроси, что приготовить, что скоро испортится, как хранить продукты — или скажи, что ты не любишь.', 'Сәлем, {0}! Мен Нутрикпін 🐾 Не пісіруге болатынын, не тез бұзылатынын, тағамды қалай сақтау керегін сұра — немесе не ұнамайтынын айт.'],
  'Hi, {0}! 👋 You have {1} at home{2}. Ask me what to cook!': ['Привет, {0}! 👋 У тебя дома {1}{2}. Спроси, что приготовить!', 'Сәлем, {0}! 👋 Үйде {1} бар{2}. Не пісіруді сұра!'],
  'Hmm, I didn\'t quite get "{0}" 🙈 Try: "what can I cook?", "what expires soon?", "how to store tomatoes", "can I freeze bread?", "do I have milk?" or "help".': ['Хм, не совсем понял «{0}» 🙈 Попробуй: «что приготовить?», «что скоро испортится?», «как хранить помидоры», «можно ли заморозить хлеб?», «есть ли молоко?» или «помощь».', 'Хм, «{0}» дегенді толық түсінбедім 🙈 Былай жазып көр: «не пісіруге болады?», «не жақында бұзылады?», «қызанақты қалай сақтау керек», «нанды мұздатуға бола ма?», «сүт бар ма?» немесе «көмек».'],
  'Hmm, I didn\'t recognize these. Pick a suggestion or write it differently.': ['Хм, этого я не узнал. Выбери подсказку или напиши по-другому.', 'Хм, мұны танымадым. Ұсыныстың бірін таңда немесе басқаша жаз.'],
  'Hmm, please check the fields in red!': ['Хм, проверь поля, отмеченные красным!', 'Хм, қызылмен белгіленген өрістерді тексер!'],
  'Home': ['Главная', 'Басты'],
  'Home Chef': ['Домашний шеф', 'Үй аспазы'],
  'How active are you, and what\'s your goal? 🎯': ['Насколько ты активен и какая у тебя цель? 🎯', 'Қаншалықты белсендісің және мақсатың қандай? 🎯'],
  'How active are you? A gentle "Lose" goal works best — no strict diets! 🥗': ['Насколько ты активен? Лучше всего мягкая цель «Похудеть» — без жёстких диет! 🥗', 'Қаншалықты белсендісің? Жұмсақ «Арықтау» мақсаты ең жақсы — қатаң диетасыз! 🥗'],
  'How active are you? You\'re a bit light — I\'d suggest "Gain" 🍝': ['Насколько ты активен? Вес немного маловат — я бы выбрал «Набрать» 🍝', 'Қаншалықты белсендісің? Салмағың сәл аз — «Қосу» дегенді ұсынамын 🍝'],
  'How much did you eat?': ['Сколько ты съел?', 'Қанша жедің?'],
  'How to store tomatoes?': ['Как хранить помидоры?', 'Қызанақты қалай сақтау керек?'],
  'Hungry? Tap Recipes 👇': ['Проголодался? Нажми «Рецепты» 👇', 'Қарның ашты ма? «Рецепттер» батырмасын бас 👇'],
  'I ate some': ['Я съел часть', 'Біразын жедім'],
  'I can\'t fly! 🙀': ['Я не умею летать! 🙀', 'Мен ұша алмаймын! 🙀'],
  'I can:\n• suggest recipes from your fridge ("what can I cook?", "another")\n• tell what expires soon\n• explain how to store or freeze food\n• count calories ("calories in banana")\n• check your fridge ("do I have milk?")\n• really add, eat, bin or freeze food: "add 2 eggs to fridge", "I ate a banana"\n• add to the shopping list\n• show your eco impact and weight\n• remember what you don\'t like': ['Я умею:\n• предлагать рецепты из холодильника («что приготовить?», «ещё»)\n• говорить, что скоро испортится\n• объяснять, как хранить и замораживать еду\n• считать калории («калории в банане»)\n• проверять холодильник («есть ли молоко?»)\n• по-настоящему добавлять, отмечать съеденное, выброшенное и замороженное: «добавь 2 яйца в холодильник», «съел банан»\n• добавлять в список покупок\n• показывать твой эко-вклад и вес\n• запоминать, что ты не любишь', 'Мен:\n• тоңазытқыштағы өнімдерден рецепт ұсынамын («не пісіруге болады?», «тағы»)\n• не жақында бұзылатынын айтамын\n• тағамды қалай сақтау және мұздату керегін түсіндіремін\n• калория санаймын («банандағы калория»)\n• тоңазытқышты тексеремін («сүт бар ма?»)\n• шынымен қосамын, жегенді, тастағанды, мұздатқанды белгілеймін: «тоңазытқышқа 2 жұмыртқа қос», «банан жедім»\n• сатып алу тізіміне қосамын\n• эко-үлесің мен салмағыңды көрсетемін\n• не ұнамайтынын есте сақтаймын'],
  'I cooked it · log {0} kcal': ['Я приготовил · записать {0} ккал', 'Пісірдім · {0} ккал жазу'],
  'I cooked it! 👩‍🍳': ['Я приготовил(а)! 👩‍🍳', 'Мен пісірдім! 👩‍🍳'],
  'I couldn\'t find a recipe with that. Try another product! 🤔': ['Не нашёл рецепт с этим. Попробуй другой продукт! 🤔', 'Мұнымен рецепт таппадым. Басқа өнімді байқап көр! 🤔'],
  'I couldn\'t read any text — try a sharper photo with more light 📸': ['Не смог прочитать текст — попробуй фото почётче и при хорошем свете 📸', 'Мәтінді оқи алмадым — анығырақ әрі жарығы жақсы фото түсіріп көр 📸'],
  'I don\'t like onion': ['Я не люблю лук', 'Маған пияз ұнамайды'],
  'I help people stop wasting food. Nice to meet you!': ['Я помогаю людям не выбрасывать еду. Рад знакомству!', 'Мен адамдарға тағамды ысырап етпеуге көмектесемін. Танысқаныма қуаныштымын!'],
  'I love a clean fridge ✨': ['Обожаю чистый холодильник ✨', 'Таза тоңазытқышты жақсы көремін ✨'],
  'I opened it': ['Я открыл(а)', 'Аштым'],
  'I opened one': ['Я открыл(а) одну', 'Біреуін аштым'],
  'I tried to run to the fridge, but my legs are only 2 cm long. I\'m still on my way. 🐾': ['Я побежал к холодильнику, но мои ножки всего 2 см. Я всё ещё в пути. 🐾', 'Тоңазытқышқа жүгірдім, бірақ аяқтарым небәрі 2 см. Әлі жолдамын. 🐾'],
  'I\'m Nutrik! A small, slightly messy food buddy with very short legs 🐾 I watch your fridge, cook ideas from leftovers and cheer every time you save food from the bin.': ['Я Нутрик! Маленький, немного неряшливый друг еды на очень коротких ножках 🐾 Слежу за холодильником, придумываю блюда из остатков и радуюсь каждый раз, когда ты спасаешь еду от мусорки.', 'Мен Нутрикпін! Аяқтары өте қысқа, сәл ұқыпсыз тағам досымын 🐾 Тоңазытқышыңды бақылаймын, қалдықтардан тағам ойлап табамын және тағамды қоқыстан құтқарған сайын қуанамын.'],
  'I\'m not a toy! 😾': ['Я не игрушка! 😾', 'Мен ойыншық емеспін! 😾'],
  'Ice Saver': ['Ледяной спасатель', 'Мұз құтқарушы'],
  'Idea: {0} {1} rescues some of them!': ['Идея: {0} {1} спасёт часть из них!', 'Идея: {0} {1} олардың бірқатарын құтқарады!'],
  'Impact': ['Вклад', 'Әсер'],
  'Ingredients': ['Ингредиенты', 'Ингредиенттер'],
  'Ingredients from your fridge are used up — the ones expiring first.': ['Продукты спишутся из холодильника — сначала те, у которых срок кончается раньше.', 'Өнімдер тоңазытқыштан шегеріледі — алдымен мерзімі тез бітетіндері.'],
  'Instructions': ['Приготовление', 'Дайындау'],
  'Into the bin? Sniff...': ['В мусорку? Хнык...', 'Қоқысқа ма? Өкінішті...'],
  'Into the fridge!': ['В холодильник!', 'Тоңазытқышқа!'],
  'Is it snack time yet?': ['Уже время перекуса?', 'Жеңіл тамақ уақыты болды ма?'],
  'Is it still good?': ['Это ещё можно есть?', 'Бұл әлі жарамды ма?'],
  'It expired': ['Истёк срок', 'Мерзімі өтті'],
  'It got away... 😿': ['Улетела... 😿', 'Ұшып кетті... 😿'],
  'Keep': ['Держать', 'Сақтау'],
  'Keep fresh herbs in a glass of water, like flowers.': ['Держи свежую зелень в стакане воды, как цветы.', 'Балғын көкті гүл сияқты бір стақан суда ұста.'],
  'Keep it empty': ['Оставить пустым', 'Бос қалдыру'],
  'Keep older products at the front of the shelf, new ones at the back (FIFO).': ['Старые продукты ставь вперёд, новые — назад (FIFO).', 'Ескі өнімдерді сөренің алдына, жаңаларын артына қой (FIFO).'],
  'Keeping your weight needs about {0} kcal a day. The rest-only number ({1}) is what your body burns lying in bed.': ['Чтобы держать вес, нужно около {0} ккал в день. Число в покое ({1}) — это сколько организм тратит, просто лёжа в кровати.', 'Салмақты сақтау үшін күніне шамамен {0} ккал керек. Тыныштықтағы сан ({1}) — ағзаның төсекте жатқанда жұмсайтыны.'],
  'Keeps for {0}': ['Хранится {0}', 'Сақталады: {0}'],
  'Kurt is my favourite snack: it lasts for months, just like my naps. 😴': ['Курт — мой любимый перекус: хранится месяцами, как и мой сон. 😴', 'Құрт — менің сүйікті тағамым: айлап сақталады, менің ұйқым сияқты. 😴'],
  'Kurt keeps for months — a perfect zero-waste snack 🧀': ['Курт хранится месяцами — идеальный перекус без отходов 🧀', 'Құрт айлап сақталады — қалдықсыз тамаша тіскебасар 🧀'],
  'La-la-la~ ♪': ['Ля-ля-ля~ ♪', 'Ля-ля-ля~ ♪'],
  'Language': ['Язык', 'Тіл'],
  'Language & currency': ['Язык и валюта', 'Тіл және валюта'],
  'Language changed': ['Язык изменён', 'Тіл өзгертілді'],
  'Last 7 days': ['Последние 7 дней', 'Соңғы 7 күн'],
  'Last tab: tap AI Chef 👇': ['Последняя вкладка: нажми «ИИ-шеф» 👇', 'Соңғы бет: «ЖИ-аспазды» бас 👇'],
  'Leftover Hero': ['Герой остатков', 'Қалған тағам батыры'],
  'Leftover rice + egg + veggies = fried rice in 10 minutes 🍳': ['Остатки риса + яйцо + овощи = жареный рис за 10 минут 🍳', 'Қалған күріш + жұмыртқа + көкөніс = 10 минутта қуырылған күріш 🍳'],
  'Leftovers = free lunch 😋': ['Остатки = бесплатный обед 😋', 'Қалған тамақ = тегін түскі ас 😋'],
  'Leftovers? Put them in the fridge — Nutrik will remind you 🥡': ['Осталось? Убери в холодильник — Нутрик напомнит 🥡', 'Артып қалды ма? Тоңазытқышқа сал — Нутрик еске салады 🥡'],
  'Legend': ['Легенда', 'Аңыз'],
  'Let\'s cook together! Something is missing — maybe swap it or skip it 🐾': ['Готовим вместе! Чего-то не хватает — можно заменить или пропустить 🐾', 'Бірге пісірейік! Бір нәрсе жетпейді — басқасымен алмастыруға не өткізіп жіберуге болады 🐾'],
  'Let\'s cook ▶︎': ['Готовим ▶︎', 'Пісірейік ▶︎'],
  'Let\'s create your account! What\'s your name? (It\'s just a test account — I won\'t tell anyone 🤫)': ['Давай создадим аккаунт! Как тебя зовут? (Это просто тестовый аккаунт — я никому не скажу 🤫)', 'Аккаунт ашайық! Атың кім? (Бұл жай сынақ аккаунты — ешкімге айтпаймын 🤫)'],
  'Let\'s fix your account info!': ['Давай поправим данные аккаунта!', 'Аккаунт деректерін түзетейік!'],
  'Let\'s go! 🌱': ['Поехали! 🌱', 'Кеттік! 🌱'],
  'Let\'s go! 🚀': ['Поехали! 🚀', 'Кеттік! 🚀'],
  'Let\'s start a zero-waste streak today! 🌱': ['Давай начнём серию без отходов сегодня! 🌱', 'Қалдықсыз сериясын бүгін бастайық! 🌱'],
  'Let\'s take care of you step by step 🤝 A gentle "Lose" goal and a chat with a doctor are a great start.': ['Давай позаботимся о тебе шаг за шагом 🤝 Мягкая цель «Похудеть» и разговор с врачом — отличное начало.', 'Өзіңе қадам-қадаммен қамқор болайық 🤝 Жұмсақ «Арықтау» мақсаты мен дәрігермен сөйлесу — тамаша бастама.'],
  'Light': ['Лёгкая', 'Жеңіл'],
  'Load demo fridge': ['Загрузить демо-холодильник', 'Демо-тоңазытқышты жүктеу'],
  'Log': ['Записать', 'Жазу'],
  'Log as eaten': ['Записать как съеденное', 'Жеген деп жазу'],
  'Log as eaten…': ['Записать как съеденное…', 'Жеген деп жазу…'],
  'Log out': ['Выйти', 'Шығу'],
  'Log weight': ['Записать вес', 'Салмақты жазу'],
  'Log your weight': ['Запиши свой вес', 'Салмағыңды жаз'],
  'Log your weight 3 times': ['Запиши вес 3 раза', 'Салмағыңды 3 рет жаз'],
  'Log your weight a few times to see the trend 📈': ['Запиши вес несколько раз, чтобы увидеть динамику 📈', 'Өзгерісті көру үшін салмағыңды бірнеше рет жаз 📈'],
  'Log your weight once a week — Nutrik keeps the history and the trend.': ['Записывай вес раз в неделю — Нутрик сохранит историю и покажет тренд.', 'Салмағыңды аптасына бір рет жаз — Нутрик тарихын сақтап, үрдісін көрсетеді.'],
  'Lose': ['Похудеть', 'Арықтау'],
  'Lv {0} · {1}': ['Ур. {0} · {1}', '{0}-дең. · {1}'],
  'MTWTFSS': ['ПВСЧПСВ', 'ДСССЖСЖ'],
  'MY WEEK WITH NUTRIMATE': ['МОЯ НЕДЕЛЯ С NUTRIMATE', 'NUTRIMATE-ПЕН МЕНІҢ АПТАМ'],
  'Male': ['Мужской', 'Ер'],
  'Man': ['Мужчина', 'Ер'],
  'Maybe:': ['Может:', 'Мүмкін:'],
  'Meat': ['Мясо', 'Ет'],
  'Medals': ['Медали', 'Медальдар'],
  'Moderate': ['Средняя', 'Орташа'],
  'Money saved': ['Денег сэкономлено', 'Үнемделген ақша'],
  'Money saved and at risk — approximate': ['Сэкономлено и под угрозой — примерно', 'Үнемделген және қауіптегі ақша — шамамен'],
  'More food went to the bin than we saved 😿 Let\'s turn it around this week!': ['Выброшено больше, чем спасено 😿 Давай исправим это на этой неделе!', 'Құтқарғаннан гөрі көбі тасталды 😿 Осы аптада жағдайды түзетейік!'],
  'Most eaten': ['Чаще всего ел(а)', 'Ең көп жегенің'],
  'Most of the waste happens at home — not in shops or restaurants.': ['Больше всего еды выбрасывают дома — не в магазинах и ресторанах.', 'Қалдықтың көбі үйде пайда болады — дүкен не мейрамханада емес.'],
  'Mrrr... who woke me?': ['Мррр... кто меня разбудил?', 'Мррр... мені кім оятты?'],
  'My Fridge': ['Мой холодильник', 'Менің тоңазытқышым'],
  'My eco impact': ['Мой эко-вклад', 'Менің эко-үлесім'],
  'My spinach looks sad. Ideas?': ['Мой шпинат совсем поник. Идеи?', 'Шпинатым солып қалды. Не істеуге болады?'],
  'My week with NutriMate': ['Моя неделя с NutriMate', 'NutriMate-пен менің аптам'],
  'Name': ['Имя', 'Аты'],
  'Need: {0}': ['Нужно: {0}', 'Керек: {0}'],
  'New groceries! 🛒': ['Новые продукты! 🛒', 'Жаңа өнімдер! 🛒'],
  'New medal!': ['Новая медаль!', 'Жаңа медаль!'],
  'New weight, kg': ['Новый вес, кг', 'Жаңа салмақ, кг'],
  'Next': ['Далее', 'Әрі қарай'],
  'Next time we save it!': ['В следующий раз спасём!', 'Келесі жолы құтқарамыз!'],
  'Nice! Fill half the plate with veggies, drink water, and keep moving 🥗 No crash diets.': ['Здорово! Половина тарелки — овощи, пей воду и больше двигайся 🥗 Без жёстких диет.', 'Керемет! Табақтың жартысы — көкөніс, су іш және көп қозғал 🥗 Қатаң диетасыз.'],
  'Night': ['Ночная', 'Түнгі'],
  'No recipe for these right now — the freezer keeps them for months.': ['Для них сейчас нет рецепта — в морозилке они пролежат месяцы.', 'Бұларға қазір рецепт жоқ — мұздатқышта айлап сақталады.'],
  'No recipes found.': ['Рецептов не нашлось.', 'Рецепт табылмады.'],
  'No recipes here yet. Add more products to your fridge!': ['Здесь пока нет рецептов. Добавь побольше продуктов в холодильник!', 'Мұнда әзірге рецепт жоқ. Тоңазытқышқа көбірек өнім қос!'],
  'No weigh-ins yet. Add one in Profile → Edit profile → Weight ⚖️': ['Взвешиваний пока нет. Добавь в Профиль → Редактировать профиль → Вес ⚖️', 'Әзірге өлшеу жоқ. Профиль → Профильді өзгерту → Салмақ бөлімінде қос ⚖️'],
  'Nom nom nom...': ['Ням-ням-ням...', 'Ням-ням-ням...'],
  'Noo... that food deserved better 😿': ['Не-ет... эта еда заслуживала лучшего 😿', 'Жо-оқ... бұл тағам жақсырақ тағдырға лайық еді 😿'],
  'Normal': ['Норма', 'Қалыпты'],
  'Not bad! Use the expiring products first.': ['Неплохо! Используй сначала то, что скоро испортится.', 'Жаман емес! Алдымен мерзімі бітетіндерді пайдалан.'],
  'Not in my food base — it won\'t be added.': ['Такого нет в моей базе — не добавлю.', 'Менің базамда жоқ — қоспаймын.'],
  'Not this? Maybe:': ['Не то? Может быть:', 'Бұл емес пе? Мүмкін:'],
  'Nothing can be cooked only from your fridge yet. Try "For you" — I\'ll show what\'s missing.': ['Пока ничего не приготовить только из холодильника. Загляни в «Для тебя» — покажу, чего не хватает.', 'Әзірге тек тоңазытқыштағы өніммен ештеңе пісіре алмайсың. «Саған» бөлімін қара — неден жетпейтінін көрсетемін.'],
  'Nothing eaten yet. Tap a product, then Eat.': ['Пока ничего не съедено. Нажми на продукт, затем «Съесть».', 'Әзірге ештеңе жеген жоқсың. Өнімді басып, «Жеу» таңда.'],
  'Nothing found for "{0}"': ['По запросу «{0}» ничего не найдено', '«{0}» бойынша ештеңе табылмады'],
  'Nothing found 🤔 Try another word.': ['Ничего не нашлось 🤔 Попробуй другое слово.', 'Ештеңе табылмады 🤔 Басқа сөзбен көр.'],
  'Nothing here': ['Здесь пусто', 'Мұнда ештеңе жоқ'],
  'Nothing here. Tell Nutrik "I don\'t like onion" in chat and recipes with it go to the end of the list.': ['Здесь пусто. Напиши Нутрику в чате «не люблю лук» — и рецепты с ним уйдут в конец списка.', 'Мұнда бос. Чатта Нутрикке «пиязды ұнатпаймын» деп жаз — онымен жасалатын рецепттер тізімнің соңына кетеді.'],
  'Nothing is about to expire. 🎉': ['Ничего не портится. 🎉', 'Ештеңе бұзылғалы тұрған жоқ. 🎉'],
  'Nothing is about to spoil — nothing to rescue right now! 🎉': ['Ничего не портится — спасать пока нечего! 🎉', 'Ештеңе бұзылып жатқан жоқ — әзірге құтқаратын ештеңе жоқ! 🎉'],
  'Nothing is expiring soon. Great job! 🎉': ['Ничего скоро не испортится. Отлично! 🎉', 'Жақында ештеңе бұзылмайды. Жарайсың! 🎉'],
