  'Now open your fridge: tap the glowing Fridge button 👇': ['Теперь открой холодильник: нажми на светящуюся кнопку «Холодильник» 👇', 'Енді тоңазытқышты аш: жарқыраған «Тоңазытқыш» батырмасын бас 👇'],
  'Now your body stats! I\'ll use them to work out your daily calorie goal. 🔢': ['Теперь параметры тела! По ним я посчитаю твою дневную цель калорий. 🔢', 'Енді дене өлшемдері! Солар бойынша күнделікті калория мақсатыңды есептеймін. 🔢'],
