  'Once open it keeps ~{0} — I\'ll shorten the date': ['Открытым хранится ~{0} — я сокращу срок', 'Ашылған соң ~{0} сақталады — мерзімін қысқартамын'],
  'One less': ['На один меньше', 'Біреуі кем'],
  'One more': ['Ещё один', 'Тағы біреу'],
  'One more secret: I live at the bottom of your screen! Grab me and drag me around. Go on, try it now! 👆': ['Ещё один секрет: я живу внизу экрана! Схвати меня и потаскай. Давай, попробуй прямо сейчас! 👆', 'Тағы бір құпия: мен экранның төменгі жағында тұрамын! Мені ұстап, сүйреп көр. Қане, қазір байқап көр! 👆'],
  'One wasted apple = ~125 liters of water used for nothing.': ['Одно выброшенное яблоко = ~125 литров воды впустую.', 'Бір тасталған алма = ~125 литр су бекер кетті.'],
  'Oops! Tiny legs... 😵': ['Ой! Коротенькие лапки... 😵', 'Ой! Аяқтарым қысқа... 😵'],
  'Oops, more food in the bin than rescued 😿 Check "Use these first" every morning — I\'ll help!': ['Ой, выброшено больше, чем спасено 😿 Каждое утро смотри «Съешь в первую очередь» — я помогу!', 'Ой, құтқарғаннан гөрі көбірек тасталды 😿 Әр таң сайын «Алдымен осыларды же» бөлімін қара — көмектесемін!'],
  'Oops… {0} went to the bin 😿 Next time we\'ll save it!': ['Ой… {0} отправился в мусорку 😿 В следующий раз спасём!', 'Ой… {0} қоқысқа кетті 😿 Келесі жолы құтқарамыз!'],
