  'Paste': ['Вставить', 'Қою'],
  'Photos are read right on your phone — nothing is uploaded.': ['Фото читается прямо на телефоне — никуда не отправляется.', 'Фото телефонның өзінде оқылады — ешқайда жіберілмейді.'],
  'Plan 3 dinners before shopping — you\'ll buy 30% less 🛒': ['Спланируй 3 ужина перед походом в магазин — купишь на 30% меньше 🛒', 'Дүкенге барар алдында 3 кешкі асты жоспарла — 30% аз сатып аласың 🛒'],
  'Plan 3 meals before shopping and buy only what the shopping list says.': ['Перед покупками спланируй 3 блюда и бери только то, что в списке.', 'Сауда алдында 3 тағамды жоспарла және тек тізімдегіні ал.'],
  'Plan 3 meals before shopping — it cuts waste a lot.': ['Спланируй 3 блюда до покупок — отходов станет намного меньше.', 'Сауда алдында 3 тағамды жоспарла — қалдық әлдеқайда азаяды.'],
  'Plan it for dinner or freeze it tonight ❄️ — Nutrik': ['Приготовь на ужин или заморозь сегодня вечером ❄️ — Нутрик', 'Кешкі асқа пісір не бүгін кешке мұздат ❄️ — Нутрик'],
