  'Purr-fect! 🎉 Tap me to pet me, double-tap to make me jump, or throw me if you dare 😼 Now let\'s go save some food!': ['Мур-р-рекрасно! 🎉 Нажми, чтобы погладить, нажми дважды — я подпрыгну, или подбрось, если не боишься 😼 А теперь пошли спасать еду!', 'Керемет! 🎉 Сипау үшін бас, секірту үшін екі рет бас, батылың жетсе — лақтыр 😼 Ал енді тағамды құтқаруға кеттік!'],
  'Put the oldest products at the front of the fridge.': ['Ставь самые старые продукты вперёд.', 'Ең ескі өнімдерді тоңазытқыштың алдына қой.'],
