  'Recipes': ['Рецепты', 'Рецепттер'],
  'Recipes made from what you already have — food that expires soonest goes on top. Missing items go to the shopping list.': ['Рецепты из того, что у тебя уже есть, — сверху те, что спасают скоропортящееся. Недостающее уходит в список покупок.', 'Қолыңда бар өнімдерден рецепттер — тез бұзылатын тағамы барлары жоғарыда. Жетпейтіні сатып алу тізіміне түседі.'],
  'Recipes that use up your spoiling food come first. Try the ♻️ Rescue food and 🌱 Zero-waste filters!': ['Сначала рецепты, которые спасают портящиеся продукты. Попробуй фильтры ♻️ Спасти еду и 🌱 Без отходов!', 'Алдымен бұзылып жатқан өнімдерді пайдаланатын рецепттер. ♻️ Тағамды құтқару және 🌱 Қалдықсыз сүзгілерін байқап көр!'],
