  'Runs in when you eat, cook, freeze or bin food': ['Выбегает, когда ты ешь, готовишь, замораживаешь или выбрасываешь еду', 'Тамақ жегенде, пісіргенде, мұздатқанда не тастағанда жүгіріп шығады'],
  'Same products stack into one row (×2). Swipe right — ate one · swipe left — freeze or bin. Tap for details.': ['Одинаковые продукты складываются в одну строку (×2). Свайп вправо — съел один · влево — заморозить или выбросить. Нажми, чтобы открыть.', 'Бірдей өнімдер бір жолға жиналады (×2). Оңға сырғыт — біреуін жедім · солға — мұздату не тастау. Толығырақ — бас.'],
  'Save': ['Сохранить', 'Сақтау'],
  'Save 3 leftover portions for later instead of binning them': ['Убери 3 порции остатков на потом, а не в мусор', 'Қалған 3 порцияны қоқысқа емес, кейінге сақта'],
  'Save 3 products that were about to expire': ['Спаси 3 продукта, которые вот-вот испортятся', 'Бұзылғалы тұрған 3 өнімді құтқар'],
  'Save food. Save money. Save the planet.': ['Спасай еду. Береги деньги. Береги планету.', 'Тағамды құтқар. Ақшаны үнемде. Планетаны сақта.'],
