  'Share food with someone instead of binning it': ['Поделись едой вместо того, чтобы выбросить', 'Тағамды тастаудың орнына біреумен бөліс'],
  'Share my week': ['Поделиться неделей', 'Аптаммен бөлісу'],
  'Shared': ['Отдано', 'Бөлісілді'],
  'Shared: {0}': ['Отдано: {0}', 'Бөлісілді: {0}'],
  'Shop with a list and never shop hungry — you buy 20–30% less.': ['Ходи в магазин со списком и не голодным — купишь на 20–30% меньше.', 'Дүкенге тізіммен бар, аш барма — 20–30% аз сатып аласың.'],
