  'Smart Nutrik (online AI)': ['Умный Нутрик (онлайн-ИИ)', 'Ақылды Нутрик (онлайн ЖИ)'],
  'Smart Shopper': ['Умный покупатель', 'Ақылды сатып алушы'],
  'Smells amazing!': ['Пахнет потрясающе!', 'Иісі керемет!'],
  'Smells good already! 😋': ['Уже вкусно пахнет! 😋', 'Иісі қазірдің өзінде керемет! 😋'],
  'Snacks': ['Снеки', 'Тіскебасарлар'],
  'Some days were a bit over the goal. Smaller portions, same tasty food 🍽️': ['В некоторые дни было чуть больше цели. Порции поменьше — еда такая же вкусная 🍽️', 'Кейбір күндері мақсаттан сәл асты. Порцияны кішірейт — тағам сол дәмді күйінде 🍽️'],
  'Some food has expired 😿 Check your fridge.': ['Некоторые продукты испортились 😿 Проверь холодильник.', 'Кейбір өнімдердің мерзімі өтті 😿 Тоңазытқышты тексер.'],
  'Sorry, I didn\'t quite get "{0}". Try: "what can I cook?", "what expires soon?", "how to store tomatoes", "can I freeze bread?", "do I have milk?" or "I don\'t like onion".': ['Прости, я не совсем понял «{0}». Попробуй: «что приготовить?», «что скоро испортится?», «как хранить помидоры», «можно ли заморозить хлеб?», «есть ли молоко?» или «не люблю лук».', 'Кешір, «{0}» дегенді толық түсінбедім. Былай жазып көр: «не пісірейін?», «не тез бұзылады?», «қызанақты қалай сақтау керек», «нанды мұздатуға бола ма?», «сүт бар ма?» немесе «пияз ұнамайды».'],
  'Sorry, something went wrong. Try again.': ['Извини, что-то пошло не так. Попробуй ещё раз.', 'Кешір, бірдеңе дұрыс болмады. Қайталап көр.'],
  'Sorted so the food that spoils first gets used first.': ['Отсортировано так, чтобы первым уходило то, что испортится раньше.', 'Ертерек бұзылатын тағам бірінші пайдаланылатындай сұрыпталған.'],
  'Spices': ['Специи', 'Дәмдеуіштер'],
  'Sprout': ['Росток', 'Өскін'],
  'Stable — no change': ['Стабильно — без изменений', 'Тұрақты — өзгеріс жоқ'],
  'Stale baursaks? Bake them into a sweet bread pudding 🍮': ['Баурсаки зачерствели? Испеки из них сладкий хлебный пудинг 🍮', 'Бауырсақ қатып қалды ма? Одан тәтті нан пудингін пісір 🍮'],
  'Stale bread → croutons, toast or bread pudding. Never the bin!': ['Чёрствый хлеб → сухарики, тосты или хлебный пудинг. Только не в мусор!', 'Қатқан нан → кептірілген нан, тост не нан пудингі. Қоқысқа емес!'],
  'Start saving food 🌱': ['Начать спасать еду 🌱', 'Тағамды құтқаруды бастау 🌱'],
  'Start the timer — I will ring right here ⏰': ['Запусти таймер — я позвоню прямо здесь ⏰', 'Таймерді қос — осы жерде хабарлаймын ⏰'],
  'Start the timer — I\'ll call you, even if the screen is off ⏰': ['Запусти таймер — я позову, даже если экран погаснет ⏰', 'Таймерді қос — экран сөніп тұрса да шақырамын ⏰'],
  'Start timer · {0}': ['Запустить таймер · {0}', 'Таймерді қосу · {0}'],
  'Step {0}': ['Шаг {0}', '{0}-қадам'],
  'Step {0} of {1}': ['Шаг {0} из {1}', '{1} қадамның {0}-қадамы'],
  'Steps': ['Шаги', 'Қадамдар'],
  'Stock your fridge': ['Заполни холодильник', 'Тоңазытқышты толтыр'],
  'Stop poking me! 😾': ['Хватит в меня тыкать! 😾', 'Мені түрткілеме! 😾'],
  'Storage: {0}': ['Хранение: {0}', 'Сақтау: {0}'],
  'Store tomatoes at room temperature — the fridge kills their flavor.': ['Храни помидоры при комнатной температуре — в холодильнике они теряют вкус.', 'Қызанақты бөлме температурасында сақта — тоңазытқышта дәмі кетеді.'],
  'Stored in': ['Где хранится', 'Сақтау орны'],
  'Sweets': ['Сладости', 'Тәттілер'],
  'Swipe left to like a product again.': ['Смахни влево, чтобы вернуть продукт.', 'Өнімді қайтару үшін солға сырғыт.'],
  'Take your time — cooking is not a race 🐾': ['Не спеши — готовка не гонка 🐾', 'Асықпа — тамақ пісіру жарыс емес 🐾'],
  'Tank almost empty ⛽ — time to eat': ['Бак почти пуст ⛽ — пора поесть', 'Бак бос дерлік ⛽ — тамақтану уақыты'],
  'Tank full — goal reached 🎯': ['Бак полон — цель достигнута 🎯', 'Бак толы — мақсатқа жеттің 🎯'],
  'Tap "+1 day" to watch freshness bars drop and products expire.': ['Нажимай «+1 день», чтобы увидеть, как падает свежесть и истекают сроки.', 'Балғындықтың азайып, мерзімдердің өтуін көру үшін «+1 күн» бас.'],
  'Tap me again for another tip! (careful, I trip sometimes 😅)': ['Нажми ещё раз — будет новый совет! (осторожно, я иногда падаю 😅)', 'Тағы бір кеңес үшін қайта бас! (абайла, кейде құлап қаламын 😅)'],
  'Tap the circle when you bought it — it goes straight into your fridge.': ['Нажми на кружок, когда купишь, — продукт сразу попадёт в холодильник.', 'Сатып алғанда шеңберді бас — өнім бірден тоңазытқышқа түседі.'],
  'Tap the place icon to switch fridge / freezer / pantry. Hold a row if I picked the wrong product.': ['Нажми на значок места, чтобы выбрать холодильник / морозилку / шкаф. Удерживай строку, если я ошибся с продуктом.', 'Орынды ауыстыру үшін белгішені бас: тоңазытқыш / мұздатқыш / шкаф. Өнімді қате таңдасам, жолды басып тұр.'],
  'Tap ✓ when you buy it — it goes straight to your fridge': ['Нажми ✓, когда купишь, — продукт сразу попадёт в холодильник', 'Сатып алғанда ✓ бас — өнім бірден тоңазытқышқа түседі'],
  'Taste it — a pinch of salt fixes a lot 🧂': ['Попробуй на вкус — щепотка соли многое исправит 🧂', 'Дәмін тат — бір шымшым тұз көп нәрсені түзейді 🧂'],
  'Tell AI Chef what you dislike — it will stop suggesting it.': ['Скажи ИИ-шефу, что ты не любишь, — он перестанет это предлагать.', 'ЖИ-аспазға не ұнамайтынын айт — ол оны ұсынбайтын болады.'],
  'Tell me a joke': ['Расскажи шутку', 'Әзіл айтшы'],
  'Tenge': ['Тенге', 'Теңге'],
  'Text from the photo is in the box above — you can fix it.': ['Текст с фото — в поле выше, его можно поправить.', 'Фотодағы мәтін жоғарыдағы өрісте — оны түзетуге болады.'],
  'That\'s all! Let\'s eat well and waste nothing together 🌱': ['Вот и всё! Давай вместе есть вкусно и ничего не выбрасывать 🌱', 'Болды! Бірге дұрыс тамақтанып, ештеңені тастамайық 🌱'],
  'The floor is hard...': ['Пол твёрдый...', 'Еден қатты екен...'],
  'The fridge door is the warmest spot: keep sauces there, not milk.': ['Дверца — самое тёплое место холодильника: там соусы, а не молоко.', 'Есік — тоңазытқыштың ең жылы жері: онда сүт емес, тұздық сақта.'],
  'The full plan is in Recipes → 🗓️ Use-it-up plan.': ['Весь план — в Рецептах → 🗓️ План «доедаем всё».', 'Толық жоспар — Рецепттер → 🗓️ «Бәрін жейміз» жоспары.'],
  'The list is empty. Add missing ingredients from any recipe 🍲': ['Список пуст. Добавь недостающие ингредиенты из любого рецепта 🍲', 'Тізім бос. Кез келген рецепттен жетіспейтін ингредиенттерді қос 🍲'],
  'The plan updates by itself when your fridge changes.': ['План сам обновляется, когда меняется холодильник.', 'Тоңазытқыш өзгергенде жоспар өздігінен жаңарады.'],
  'Theme': ['Тема', 'Режим'],
  'These need you first! Tap a card to eat it, freeze it, share it or fix the date.': ['Эти ждут тебя в первую очередь! Нажми на карточку, чтобы съесть, заморозить, поделиться или исправить дату.', 'Бұлар саған бірінші керек! Жеу, мұздату, бөлісу немесе күнді түзету үшін карточканы бас.'],
  'This is your Rescue Mission: products that spoil within 2 days and the money at risk. The eco score shows how much of your food you actually use.': ['Это твоя Спасательная миссия: продукты, которые испортятся в ближайшие 2 дня, и деньги под угрозой. Эко-балл показывает, какую часть еды ты действительно используешь.', 'Бұл — сенің Құтқару миссияң: 2 күн ішінде бұзылатын өнімдер мен қауіптегі ақша. Эко-ұпай тағамыңның қаншасын шынымен пайдаланатыныңды көрсетеді.'],
  'This product is gone 🍽️': ['Этого продукта больше нет 🍽️', 'Бұл өнім енді жоқ 🍽️'],
  'This week': ['На этой неделе', 'Осы аптада'],
  'Those numbers look a bit odd... try again?': ['Эти числа какие-то странные... попробуешь ещё раз?', 'Бұл сандар біртүрлі... тағы көресің бе?'],
  'Throw away': ['Выбросить', 'Тастау'],
  'Thrown away: {0}': ['Выброшено: {0}', 'Тасталды: {0}'],
  'Time\'s up!': ['Время вышло!', 'Уақыт бітті!'],
  'Timer · {0}': ['Таймер · {0}', 'Таймер · {0}'],
  'Tip: clean as you go — less mess at the end 🧽': ['Совет: убирай по ходу — в конце будет меньше беспорядка 🧽', 'Кеңес: жұмыс барысында жинап отыр — соңында шашылған аз болады 🧽'],
  'Tip: put older food in front of the fridge, new food at the back 🧊': ['Совет: старые продукты ставь вперёд, новые — назад 🧊', 'Кеңес: ескі өнімдерді алдыға, жаңаларын артқа қой 🧊'],
  'To buy: {0}': ['Докупить: {0}', 'Сатып алу керек: {0}'],
  'To fridge': ['В холодильник', 'Тоңазытқышқа'],
  'To pantry': ['В шкаф', 'Қоймаға'],
  'Today': ['Сегодня', 'Бүгін'],
  'Today\'s weight, kg': ['Вес сегодня, кг', 'Бүгінгі салмақ, кг'],
  'Today: {0} of {1} kcal. {2}': ['Сегодня: {0} из {1} ккал. {2}', 'Бүгін: {1} ккал-дан {0}. {2}'],
  'Tomorrow': ['Завтра', 'Ертең'],
  'Tomorrow: {0}. {1} 🍲': ['Завтра: {0}. {1} 🍲', 'Ертең: {0}. {1} 🍲'],
  'Too much food? Share it with neighbors or a community fridge.': ['Слишком много еды? Поделись с соседями или отнеси в общий холодильник.', 'Тағам тым көп пе? Көршілермен не қоғамдық тоңазытқышпен бөліс.'],
  'Trust your senses for "best before" products: look, smell, taste a little. ⚠️ But never risk it with meat, fish or dairy past the "use by" date. When in doubt — throw it out (and tell me, I\'ll learn the reason).': ['Для продуктов с пометкой «лучше употребить до» доверяй чувствам: посмотри, понюхай, попробуй чуть-чуть. ⚠️ Но никогда не рискуй с мясом, рыбой и молочкой после срока «употребить до». Сомневаешься — выброси (и скажи мне, я запомню причину).', '«Жақсысы … дейін» деп жазылған өнімдерде сезіміңе сен: қара, иіске, аздап татып көр. ⚠️ Бірақ «… дейін пайдалану» мерзімі өткен ет, балық және сүт өнімдерімен ешқашан тәуекел етпе. Күмәнің болса — таста (және маған айт, себебін есте сақтаймын).'],
  'Trust your senses for "best before" products: look, smell, taste a little. ⚠️ But never risk it with meat, fish or dairy past the "use by" date. When in doubt — throw it out.': ['Для продуктов с пометкой «лучше употребить до» доверяй чувствам: посмотри, понюхай, попробуй чуть-чуть. ⚠️ Но не рискуй с мясом, рыбой и молочным после даты «годен до». Сомневаешься — выбрасывай.', '«Дейін қолданған жөн» деген өнімдерде сезіміңе сен: қара, иіскеп көр, сәл татып көр. ⚠️ Бірақ «жарамдылық мерзімі» өткен ет, балық пен сүт өнімдерімен тәуекел етпе. Күмәнің болса — таста.'],
  'Try "cheese", "potato", "kefir"...': ['Например, «сыр», «картофель», «кефир»...', 'Мысалы, «ірімшік», «картоп», «айран»...'],
  'Try {0} {1}': ['Попробуй {0} {1}', '{0} {1} пісіріп көр'],
  'Type "2 eggs, milk, bread" or snap the receipt — everything goes in at once': ['Напиши «2 яйца, молоко, хлеб» или сфотографируй чек — всё добавится сразу', '«2 жұмыртқа, сүт, нан» деп жаз немесе чекті суретке түсір — бәрі бірден қосылады'],
  'Type or paste your shopping list — one product per line or separated by commas. I\'ll find every product!': ['Напиши или вставь список покупок — по продукту в строке или через запятую. Я найду каждый продукт!', 'Сатып алу тізімін жаз немесе қой — әр жолға бір өнім немесе үтір арқылы. Әр өнімді табамын!'],
  'Type or paste your shopping list — or snap the receipt. I\'ll find every product!': ['Напиши или вставь список покупок — или сфотографируй чек. Я найду каждый продукт!', 'Сатып алу тізімін жаз немесе қой — не чекті суретке түсір. Әр өнімді табамын!'],
  'US dollar': ['Доллар США', 'АҚШ доллары'],
  'Uncheck all': ['Снять все', 'Барлығын алу'],
  'Under': ['Недовес', 'Аз'],
  'Underweight': ['Недовес', 'Салмақ жетіспейді'],
  'Undo': ['Отменить', 'Қайтару'],
  'Unlocked': ['Получена', 'Алынды'],
  'Use these first': ['Съешь в первую очередь', 'Алдымен осыларды жеу'],
  'Use these first ⚠️': ['Съешь в первую очередь ⚠️', 'Алдымен жеу керек ⚠️'],
  'Use these first: {0}.': ['Сначала съешь это: {0}.', 'Алдымен мыналарды же: {0}.'],
  'Use today or tomorrow': ['Съешь сегодня или завтра', 'Бүгін не ертең же'],
  'Use today!': ['Съешь сегодня!', 'Бүгін же!'],
  'Use-it-up plan': ['План «доедаем всё»', '«Бәрін жейміз» жоспары'],
  'Uses {0} before it spoils': ['Спасает: {0}, пока не испортилось', 'Бұзылмай тұрып қолданады: {0}'],
  'Vegetable peels and stems make a great free broth.': ['Из очисток и стеблей овощей выходит отличный бесплатный бульон.', 'Көкөніс қабығы мен сабағынан тегін керемет сорпа шығады.'],
  'Vegetables': ['Овощи', 'Көкөністер'],
  'Very active': ['Очень высокая', 'Өте белсенді'],
  'WEEKLY REPORT': ['ОТЧЁТ ЗА НЕДЕЛЮ', 'АПТАЛЫҚ ЕСЕП'],
  'Wait! Freeze it instead (+90 days)': ['Стоп! Лучше заморозь (+90 дней)', 'Тоқта! Одан да мұздат (+90 күн)'],
  'Wasted': ['Выброшено', 'Тасталды'],
  'Wasted: {0} · about {1}': ['Выброшено: {0} · примерно {1}', 'Тасталды: {0} · шамамен {1}'],
  'Week': ['Неделя', 'Апта'],
  'Weekly report': ['Недельный отчёт', 'Апталық есеп'],
  'Weigh-in': ['Взвешивание', 'Өлшену'],
  'Weight': ['Вес', 'Салмақ'],
  'Weight this week': ['Вес за неделю', 'Осы аптадағы салмақ'],
  'Weight tracker': ['Трекер веса', 'Салмақ трекері'],
  'Weight: {0} kg': ['Вес: {0} кг', 'Салмақ: {0} кг'],
  'Went bad early': ['Испортился раньше срока', 'Мерзімінен бұрын бұзылды'],
  'What a week! Calories on track and food rescued. Keep it up 💪': ['Вот это неделя! Калории в норме, еда спасена. Так держать 💪', 'Керемет апта! Калория мөлшерінде, тағам құтқарылды. Осылай жалғастыр 💪'],
  'What can I cook?': ['Что приготовить?', 'Не пісіруге болады?'],
  'What can I cook? What expires soon? How to store…': ['Что приготовить? Что скоро испортится? Как хранить…', 'Не пісіруге болады? Не тез бұзылады? Қалай сақтау…'],
  'What do you call cheese that isn\'t yours? Nacho cheese! 🧀': ['Как называется чужой сыр? «Не-твой-сыр» — почти начос! 🧀', 'Бөтеннің ірімшігін не деп атайды? «Сенікі емес» ірімшік! 🧀'],
  'What expires soon?': ['Что скоро испортится?', 'Не тез бұзылады?'],
  'What gets wasted most': ['Что выбрасывается чаще всего', 'Ең жиі не тасталады'],
  'What should I call you?': ['Как тебя зовут?', 'Сенің атың кім?'],
  'What to cook in the next 3 days so {0} don\'t go to waste': ['Что приготовить за 3 дня, чтобы {0} не пропали', '{0} босқа кетпеуі үшін 3 күнде не пісіру керек'],
  'What\'s in my fridge?': ['Что в холодильнике?', 'Тоңазытқышта не бар?'],
  'Wheee! You got it! 😸 I don\'t always enjoy it though...': ['Уи-и-и! Получилось! 😸 Хотя мне это не всегда нравится...', 'Уи-и-и! Шықты! 😸 Бірақ маған бұл әрдайым ұнай бермейді...'],
  'Wheee! 🎉': ['Уи-и-и! 🎉', 'Уи-и-и! 🎉'],
  'Wheee... I mean, NO!': ['Уи-и-и... то есть НЕТ!', 'Уи-и-и... яғни ЖОҚ!'],
  'When something is about to expire, I\'ll plan what to cook with it here.': ['Когда что-то начнёт портиться, я распланирую здесь, что из этого приготовить.', 'Бірдеңенің мерзімі бітуге жақындағанда, одан не пісіруге болатынын осында жоспарлаймын.'],
  'Where and how long': ['Где и сколько хранить', 'Қайда және қанша сақтау'],
  'Where are we going?': ['Куда мы идём?', 'Қайда барамыз?'],
  'Which product don\'t you like? Try: "I don\'t like onion".': ['Какой продукт ты не любишь? Напиши, например: «я не люблю лук».', 'Қай өнім ұнамайды? Мысалы: «маған пияз ұнамайды».'],
  'Which product? Try: "I like onion again".': ['Какой продукт? Напиши, например: «снова люблю лук».', 'Қай өнім? Мысалы: «пияз қайта ұнайды».'],
  'Who put that there?!': ['Кто это тут поставил?!', 'Мұны кім қойған?!'],
  'Why did the tomato blush? It saw the salad dressing! 🍅': ['Почему помидор покраснел? Увидел, как салат заправляют! 🍅', 'Қызанақ неге қызарды? Салатқа тұздық құйып жатқанын көрді! 🍅'],
  'Why does {0} go to the bin?': ['Почему {0} отправляется в мусор?', '{0} неге қоқысқа кетеді?'],
  'Why don\'t eggs tell jokes? They\'d crack each other up! 🥚': ['Почему яйца не шутят? Боятся расколоться от смеха! 🥚', 'Жұмыртқалар неге әзіл айтпайды? Күлкіден жарылып кетуден қорқады! 🥚'],
  'Why food ends up in your bin': ['Почему еда попадает в мусорку', 'Тағам неге қоқысқа кетеді'],
  'Why food was thrown away': ['Почему еду выбросили', 'Тағам неге тасталды'],
  'Why is it going in the bin?': ['Почему выбрасываешь?', 'Неге тастайсың?'],
  'Why it matters in Almaty': ['Почему это важно в Алматы', 'Алматы үшін неге маңызды'],
  'Wilted greens? 10 minutes in ice water brings them back 🥬': ['Зелень завяла? 10 минут в ледяной воде — и она снова свежая 🥬', 'Көк солып қалды ма? Мұзды суда 10 минут — қайта балғын болады 🥬'],
  'Wilted veggies still make a great soup or stock.': ['Из подвявших овощей выйдет отличный суп или бульон.', 'Солған көкөністен керемет көже не сорпа шығады.'],
  'With NutriMate for {0} 🌱': ['С NutriMate уже {0} 🌱', 'NutriMate-пен {0} бірге 🌱'],
  'With NutriMate since today 🌱': ['С NutriMate с сегодняшнего дня 🌱', 'NutriMate-пен бүгіннен бері 🌱'],
  'Woman': ['Женщина', 'Әйел'],
  'World Foods': ['Кухни мира', 'Әлем тағамдары'],
  'Yay! Preparing your fridge...': ['Ура! Готовлю твой холодильник...', 'Жасасын! Тоңазытқышыңды дайындап жатырмын...'],
  'Yay! {0} is back on the menu 🎉': ['Ура! {0} снова в меню 🎉', 'Жасасын! {0} қайтадан мәзірде 🎉'],
  'Yay! 🎉': ['Ура! 🎉', 'Жасасын! 🎉'],
  'You have everything!': ['У тебя всё есть!', 'Бәрі бар!'],
  'You have everything! Let\'s cook together — swipe or tap Next 🐾': ['Всё есть! Готовим вместе — листай или жми «Далее» 🐾', 'Бәрі бар! Бірге пісірейік — сырғыт немесе «Әрі қарай» бас 🐾'],
  'You have {0} of {1}': ['Есть {0} из {1}', 'Бар: {0}/{1}'],
  'You have {0}: {1}. Freshest go last, soonest first!': ['У тебя {0}: {1}. Сначала то, что скоро испортится, свежее — в конце!', 'Сенде {0} бар: {1}. Алдымен тез бұзылатындар, ең жаңалары — соңында!'],
  'You may also like': ['Тебе может понравиться', 'Саған ұнауы мүмкін'],
  'You often ate less than your goal. Add a snack — your body needs fuel ⛽': ['Ты часто ел(а) меньше цели. Добавь перекус — телу нужно топливо ⛽', 'Сен жиі мақсаттан аз жедің. Тамақ арасында бірдеңе же — денеге отын керек ⛽'],
  'You often eat — not in your fridge': ['Часто ешь — а в холодильнике нет', 'Жиі жейсің — бірақ тоңазытқышта жоқ'],
  'You saved {0} kg of food — that\'s {1} of a tree\'s yearly CO₂ work! 🌳': ['Ты спас(ла) {0} кг еды — это {1} годовой работы дерева по CO₂! 🌳', 'Сен {0} кг тағам құтқардың — бұл бір ағаштың жылдық CO₂ жұмысының {1}! 🌳'],
  'You still need: {0}.': ['Ещё нужно: {0}.', 'Тағы керек: {0}.'],
  'You waste {0} most often ({1}×).': ['Чаще всего ты выбрасываешь: {0} ({1}×).', 'Сен жиі тастайтын санат: {0} ({1}×).'],
  'You\'re a bit light. Try the "Gain" goal — I\'ll add ~300 kcal a day with tasty, filling food 🍲': ['Ты немного лёгкий. Попробуй цель «Набрать» — добавлю ~300 ккал в день вкусной и сытной едой 🍲', 'Сен сәл жеңілсің. «Салмақ қосу» мақсатын таңда — күніне ~300 ккал дәмді әрі тойымды тамақ қосамын 🍲'],
  'You\'re a food-saving superstar! Keep it up! ⭐': ['Ты суперзвезда спасения еды! Так держать! ⭐', 'Сен тағам құтқарудың жұлдызысың! Осылай жалғастыр! ⭐'],
  'You\'re doing great! ✨': ['У тебя отлично получается! ✨', 'Сен керемет істеп жатырсың! ✨'],
  'You\'re doing great, chef! 👩‍🍳': ['Отлично получается, шеф! 👩‍🍳', 'Тамаша шығып жатыр, аспаз! 👩‍🍳'],
  'You\'re inside the healthy range 🎉': ['Ты в пределах здоровой нормы 🎉', 'Сен сау қалыптың ішіндесің 🎉'],
  'You\'re {0} kg above the healthy range.': ['Ты на {0} кг выше здоровой нормы.', 'Сау қалыптан {0} кг артықсың.'],
  'You\'re {0} kg below the healthy range.': ['До здоровой нормы не хватает {0} кг.', 'Сау қалыптан {0} кг кемсің.'],
  'Your daily goal': ['Твоя цель на день', 'Күндік мақсатың'],
  'Your daily plan': ['Твой план на день', 'Күндік жоспарың'],
  'Your data stays on this iPhone.': ['Твои данные остаются на этом iPhone.', 'Деректерің осы iPhone-да қалады.'],
  'Your fridge': ['Твой холодильник', 'Сенің тоңазытқышың'],
  'Your fridge is empty': ['Холодильник пуст', 'Тоңазытқыш бос'],
  'Your fridge is empty — add products to see what you can cook.': ['Холодильник пуст — добавь продукты, чтобы увидеть, что можно приготовить.', 'Тоңазытқыш бос — не пісіруге болатынын көру үшін өнім қос.'],
  'Your fridge is empty 😿 Add products in the Search tab!': ['Холодильник пуст 😿 Добавь продукты во вкладке «Поиск»!', 'Тоңазытқыш бос 😿 Өнімдерді «Іздеу» бөлімінде қос!'],
  'Your fridge is empty 😿 Add some products in the Search tab first — then I\'ll find you a recipe!': ['Холодильник пуст 😿 Сначала добавь продукты во вкладке «Поиск» — и я найду рецепт!', 'Тоңазытқыш бос 😿 Алдымен «Іздеу» бөлімінде өнім қос — сосын рецепт табамын!'],
  'Your fridge is empty! Add what you bought — or load a demo fridge to see how food rescue works.': ['Холодильник пуст! Добавь, что купил, — или загрузи демо-холодильник, чтобы посмотреть, как спасать еду.', 'Тоңазытқыш бос! Сатып алғаныңды қос — немесе тағам құтқару қалай жұмыс істейтінін көру үшін демо-тоңазытқышты жүкте.'],
  'Your fridge is empty! Let\'s add what you have 🧺': ['Холодильник пуст! Давай добавим, что у тебя есть 🧺', 'Тоңазытқыш бос! Барыңды қосайық 🧺'],
  'Your fridge is empty. Shall I fill it with demo groceries? Some of them are about to spoil, so you can see how rescuing food works.': ['Холодильник пуст. Заполнить его демо-продуктами? Некоторые скоро испортятся — так ты увидишь, как работает спасение еды.', 'Тоңазытқыш бос. Оны демо-өнімдермен толтырайын ба? Кейбірі жақында бұзылады — тағамды құтқару қалай жұмыс істейтінін көресің.'],
  'Your fridge! Every product has a freshness bar. Swipe right if you ate it, left to freeze, share or bin it.': ['Твой холодильник! У каждого продукта есть полоска свежести. Свайп вправо — съел(а), влево — заморозить, отдать или выбросить.', 'Сенің тоңазытқышың! Әр өнімнің балғындық жолағы бар. Оңға сырғыт — жедім, солға — мұздату, бөлісу немесе тастау.'],
  'Your list is empty! Add items here, or open a recipe and tap "Add missing to shopping list".': ['Список пуст! Добавь продукты здесь или открой рецепт и нажми «Недостающее — в список покупок».', 'Тізім бос! Өнімдерді осында қос немесе рецептті ашып, «Жетпейтінін сатып алу тізіміне қосу» батырмасын бас.'],
  'Your name': ['Твоё имя', 'Атың'],
  'Your shopping list is empty. Try: "add eggs to shopping list" 📝': ['Список покупок пуст. Попробуй: «добавь яйца в список покупок» 📝', 'Сатып алу тізімі бос. Былай жазып көр: «жұмыртқаны сатып алу тізіміне қос» 📝'],
  'Your week': ['Твоя неделя', 'Сенің аптаң'],
  'Your weight is already below the healthy range, so I\'ll plan for keeping it instead 💛': ['Твой вес уже ниже здоровой нормы, поэтому я рассчитаю план на сохранение веса 💛', 'Салмағың қазірдің өзінде дені сау нормадан төмен, сондықтан салмақты сақтау жоспарын құрамын 💛'],
  'Your weight is in the healthy zone! Keep eating well and wasting nothing 💚': ['Твой вес в здоровой зоне! Продолжай хорошо питаться и ничего не выбрасывать 💚', 'Салмағың сау аймақта! Дұрыс тамақтанып, ештеңе тастамай жүре бер 💚'],
  'Your weight, daily goal, Eco Impact and medals live here. I can also remind you at 9:00 what to eat first!': ['Здесь живут твой вес, дневная цель, эко-вклад и медали. А ещё я могу в 9:00 напоминать, что съесть первым!', 'Мұнда салмағың, күндік мақсатың, эко-үлесің және медальдарың тұрады. Сондай-ақ сағат 9:00-де алдымен не жеу керегін еске сала аламын!'],
  'Your zero-waste buddy · works offline': ['Твой друг без отходов · работает офлайн', 'Қалдықсыз досың · офлайн жұмыс істейді'],
  'Yum! Tell me how many portions you ate — I\'ll log them 🍽️': ['Вкуснятина! Скажи, сколько порций съел(а) — я запишу 🍽️', 'Дәмді! Неше порция жегеніңді айт — жазып қоямын 🍽️'],
  'Yum! {0} logged': ['Ням! {0} записано', 'Мм, дәмді! {0} жазылды'],
  'Yum! 😋': ['Вкусно! 😋', 'Дәмді! 😋'],
  'ZERO-WASTE KITCHEN': ['КУХНЯ БЕЗ ОТХОДОВ', 'ҚАЛДЫҚСЫЗ АС ҮЙ'],
  'Zero Waste Week': ['Неделя без отходов', 'Қалдықсыз апта'],
  'Zero food in the bin this week! You saved {0} — I\'m so proud 🥹': ['За неделю ничего не выброшено! Ты спас(ла) {0} — я так горжусь 🥹', 'Осы аптада ештеңе тасталмады! Сен {0} құтқардың — мақтанамын 🥹'],
  'Zero waste, nya! ✨': ['Ноль отходов, мяу! ✨', 'Қалдықсыз, мияу! ✨'],
  'Zero-Waste Pro': ['Профи без отходов', 'Қалдықсыз шебер'],
  'Zoomies! 💨': ['Бегу-у-у! 💨', 'Жүгірдім! 💨'],
  'a light snack fits 🍎': ['можно лёгкий перекус 🍎', 'жеңіл тағам жеуге болады 🍎'],
  'airtight jar in a dry cupboard': ['в герметичной банке в сухом шкафу', 'құрғақ шкафтағы тығыз жабылатын банкада'],
  'all products are fresh': ['все продукты свежие', 'барлық өнім балғын'],
  'at −18 °C, never refreeze after thawing': ['при −18 °C, после разморозки повторно не замораживай', '−18 °C-та, ерігеннен кейін қайта мұздатпа'],
  'avg kcal / day': ['ккал в день (сред.)', 'күніне орташа ккал'],
  'avg {0} kcal': ['в среднем {0} ккал', 'орташа {0} ккал'],
