  'chill': ['охлаждения', 'суыту'],
  'cm': ['см', 'см'],
  'cut off the green tops, store in the crisper drawer': ['срежь ботву, храни в ящике для овощей', 'жасыл сабағын кесіп, көкөніс жәшігінде сақта'],
  'dark, cool and dry place, never next to onions': ['в тёмном, прохладном и сухом месте, только не рядом с луком', 'қараңғы, салқын әрі құрғақ жерде, пиязбен қатар емес'],
  'days on target': ['дней в цели', 'мақсаттағы күн'],
  'days without\nwaste': ['дней без\nотходов', 'қалдықсыз\nкүн'],
  'days without waste': ['дней без отходов', 'қалдықсыз күн'],
  'day|days': ['день|дня|дней', 'күн'],
  'dry pearls in a closed jar; cooked pearls get hard in a few hours, so cook only what you drink today': ['сухие шарики — в закрытой банке; сваренные твердеют за несколько часов, так что вари столько, сколько выпьешь сегодня', 'құрғақ түйіршіктерді жабық банкада сақта; пісірілгені бірнеше сағатта қатаяды, сондықтан бүгін ішетініңді ғана пісір'],
  'dry, airy and dark place, away from potatoes': ['в сухом, проветриваемом и тёмном месте, подальше от картошки', 'құрғақ, желдетілетін, қараңғы жерде, картоптан алыс'],
  'e.g. 2 eggs, milk, 3 bananas, bread': ['например: 2 яйца, молоко, 3 банана, хлеб', 'мысалы: 2 жұмыртқа, сүт, 3 банан, нан'],
  'eco score': ['эко-балл', 'эко-ұпай'],
  'eco score {0}': ['эко-балл {0}', 'эко-ұпай {0}'],
  'g': ['г', 'г'],
  'goal {0}': ['цель {0}', 'мақсат {0}'],
  'h': ['ч', 'сағ'],
  'in a box lined with a paper towel to soak up moisture': ['в контейнере с бумажным полотенцем, чтобы впитывало влагу', 'ылғалды сіңіру үшін қағаз сүлгі төселген контейнерде'],
  'in a bread box or paper bag; freeze the slices you won\'t eat within 2 days': ['в хлебнице или бумажном пакете; ломтики, которые не съешь за 2 дня, заморозь', 'нан салғышта немесе қағаз пакетте; 2 күнде жемейтін тілімдерін мұздат'],
  'in a bread box; freeze what you can\'t eat soon': ['в хлебнице; что не успеешь съесть — заморозь', 'нан салғышта; жақында жей алмайтыныңды мұздат'],
  'in a closed container in the fridge, eat within 2–3 days': ['в закрытом контейнере в холодильнике, съешь за 2–3 дня', 'тоңазытқышта жабық контейнерде, 2–3 күнде же'],
  'in fridge': ['в холод.', 'тоңазыт.'],
  'in the crisper drawer of the fridge': ['в ящике для овощей в холодильнике', 'тоңазытқыштың көкөніс жәшігінде'],
  'in the fridge crisper drawer, separately from vegetables': ['в ящике для фруктов в холодильнике, отдельно от овощей', 'тоңазытқыштың жеміс жәшігінде, көкөністерден бөлек'],
  'in the fridge or a cool place, away from bananas': ['в холодильнике или прохладном месте, подальше от бананов', 'тоңазытқышта не салқын жерде, банандардан алыс'],
  'in their box on a fridge shelf, not in the door': ['в своей коробке на полке холодильника, не в дверце', 'өз қорабында тоңазытқыш сөресінде, есігінде емес'],
  'in {0}': ['через {0}', '{0} қалды'],
  'item|items': ['позиция|позиции|позиций', 'зат'],
  'kcal': ['ккал', 'ккал'],
  'kcal eaten': ['ккал съедено', 'ккал жеді'],
  'kcal goal': ['цель ккал', 'ккал мақсаты'],
  'kcal/100 g': ['ккал/100 г', 'ккал/100 г'],
  'keep apart from other fruit (bananas make them ripen faster); wrap the stems in foil': ['отдельно от других фруктов (бананы ускоряют их созревание); оберни хвостики фольгой', 'басқа жемістерден бөлек сақта (банан олардың пісуін тездетеді); сабақтарын фольгаға орап қой'],
  'keep at room temperature, stem down, away from sunlight — the fridge kills the flavor': ['при комнатной температуре, плодоножкой вниз, подальше от солнца — в холодильнике пропадает вкус', 'бөлме температурасында, сабағын төмен қаратып, күннен алыс сақта — тоңазытқышта дәмі кетеді'],
  'keep it cool and dry': ['в прохладном сухом месте', 'салқын әрі құрғақ жерде сақта'],
  'keep the pack sealed in the fridge; freeze what you don\'t use — it thaws in 2 hours': ['держи пачку закрытой в холодильнике; лишнее заморозь — оттаивает за 2 часа', 'қаптамасын жабық күйде тоңазытқышта сақта; артығын мұздат — 2 сағатта ериді'],
  'keeps {0} d': ['хранится {0} дн.', '{0} күн сақталады'],
  'keeps ~{0} once open': ['открытым хранится ~{0}', 'ашылған соң ~{0} сақталады'],
