  'like flowers: stems in a glass of water': ['как цветы: стеблями в стакан с водой', 'гүл сияқты: сабағын бір стақан суға сал'],
  'min': ['мин', 'мин'],
  'money\nsaved': ['денег\nсэкономлено', 'үнемделген\nақша'],
  'money kept': ['сэкономлено', 'үнемделді'],
  'money saved': ['денег сэкономлено', 'үнемделген ақша'],
  'night': ['ночь', 'түн'],
  'no data yet': ['пока нет данных', 'әзірге дерек жоқ'],
  'none': ['нет', 'жоқ'],
  'not in your fridge — add it in Search': ['нет в холодильнике — добавь через «Поиск»', 'тоңазытқышта жоқ — «Іздеу» арқылы қос'],
  'on a fridge shelf, not in the door — the door is the warmest spot': ['на полке холодильника, не в дверце — дверца самое тёплое место', 'тоңазытқыштың сөресінде, есігінде емес — есігі ең жылы жер'],
  'on a middle fridge shelf, not in the door': ['на средней полке холодильника, не в дверце', 'тоңазытқыштың ортаңғы сөресінде, есігінде емес'],
  'on ice on the bottom shelf, eat within 1–2 days or freeze': ['на льду на нижней полке, съешь за 1–2 дня или заморозь', 'төменгі сөреде мұздың үстінде, 1–2 күнде же немесе мұздат'],
  'on the bottom shelf of the fridge (coldest), or freeze within 2 days': ['на нижней полке холодильника (там холоднее всего) или заморозь в течение 2 дней', 'тоңазытқыштың төменгі сөресінде (ең суық жері) немесе 2 күн ішінде мұздат'],
  'pc|pcs': ['шт.|шт.|шт.', 'дана'],
  'perfect!': ['идеально!', 'керемет!'],
