const Map<String, List<List<String>>> stepsTr = {
  '2-Ingredient Banana Pancakes': [['Разомните очень спелые бананы — чем больше пятен, тем лучше.', 'Смешайте с яйцами и овсяными хлопьями.', 'Жарьте небольшие оладьи на слабом огне по 2 минуты с каждой стороны.'], ['Өте піскен бананды езіңіз — дақтары көп болған сайын жақсы.', 'Жұмыртқа және сұлы жармасымен араластырыңыз.', 'Шағын оладьяларды баяу отта әр жағынан 2 минуттан қуырыңыз.']],
  'Apple Charlotte': [['Сморщенные яблоки подойдут. Нарежьте их в форму для выпечки, застеленную бумагой.', 'Взбейте яйца с сахаром до пышности, аккуратно вмешайте муку.', 'Залейте яблоки тестом.', 'Выпекайте при 180 °C 40 минут.'], ['Әжім түскен алмалар да жарайды. Оларды қағазбен төселген пісіру пішініне тілімдеп салыңыз.', 'Жұмыртқа мен қантты көбік болғанша шайқап, ұнды ақырын араластырыңыз.', 'Қамырды алмалардың үстіне құйыңыз.', '180 °C температурада 40 минут пісіріңіз.']],
  'Apple Crumble': [['Сморщенные яблоки подойдут! Удалите сердцевину, нарежьте ломтиками и выложите в форму для запекания.', 'Разотрите сливочное масло, овсяные хлопья и сахар в крошку.', 'Покройте яблоки крошкой.', 'Выпекайте при 180 °C 30–35 минут до золотистого цвета и пузырьков.'], ['Әжім түскен алмалар да жарайды! Өзегін алып, тілімдеп, пісіру қалыбына салыңыз.', 'Сары май, сұлы жармасы және қантты уатып, үгіндіге айналдырыңыз.', 'Алмаларды үгіндімен жабыңыз.', '180 °C-та 30–35 минут алтын түсті болып, көпіршігенше пісіріңіз.']],
  'Arancini (Leftover Rice Balls)': [['Используйте холодный варёный рис или остатки ризотто.', 'Сформируйте шарики, положив внутрь кубик моцареллы.', 'Обмакните во взбитое яйцо, затем в панировочные сухари.', 'Обжарьте до золотистого цвета или запеките при 200 °C 20 минут.'], ['Суық піскен күріш немесе ризотто қалдығын пайдаланыңыз.', 'Ішіне моцарелла кубигін салып, шарик жасаңыз.', 'Көпіртілген жұмыртқаға, содан кейін нан үгіндісіне малыңыз.', 'Алтын түс болғанша қуырыңыз немесе 200 °C температурада 20 минут пісіріңіз.']],
  'Avocado Toast with Egg': [['Очень спелый авокадо? Время тостов! Поджарьте хлеб.', 'Разомните авокадо с лимонным соком и солью, намажьте на тост.', 'Сверху выложите жареное или пашот яйцо и хлопья чили.'], ['Авокадо өте пісіп кетті ме? Тост жасайтын уақыт! Нанды қуырыңыз.', 'Авокадоны лимон шырыны және тұзбен езіп, тостқа жағыңыз.', 'Үстіне қуырылған немесе пашот жұмыртқа салып, чили ұлпаларын себіңіз.']],
  'Baked Potatoes with Cheese': [['Вымойте картофель, проколите вилкой и запекайте при 200 °C 50 минут.', 'Сделайте сверху крестообразный надрез, слегка сожмите, чтобы раскрылся, добавьте масло.', 'Посыпьте тёртым сыром и добавьте сметану.'], ['Картопты жуып, шанышқымен тесіп, 200 °C-та 50 минут пісіріңіз.', 'Үстінен айқыш тәрізді тілік жасап, ашыңыз, сары май салыңыз.', 'Үстіне үккіштен өткізілген ірімшік себіп, қаймақ қосыңыз.']],
  'Baked Salmon with Potatoes': [['Разогрейте духовку до 200 °C. Нарежьте картофель тонкими ломтиками.', 'Перемешайте картофель с половиной масла и солью, запекайте 15 минут.', 'Выложите сверху лосось, сбрызните оставшимся маслом и лимонным соком.', 'Запекайте ещё 15–18 минут, пока рыба легко не начнёт разделяться на слои.'], ['Пешті 200 °C-қа дейін қыздырыңыз. Картопты жұқа тілімдеп кесіңіз.', 'Картопты майдың жартысымен және тұзбен араластырып, 15 минут пісіріңіз.', 'Үстіне лосось балығын салып, қалған май мен лимон шырынын себіңіз.', 'Балық оңай қабатталып ажыратылғанша тағы 15–18 минут пісіріңіз.']],
  'Banana Oat Cookies': [['Разомните очень спелые бананы вилкой до однородности.', 'Добавьте овсяные хлопья и изюм, оставьте на 5 минут, чтобы хлопья размякли.', 'Выложите ложкой небольшие горки на противень с бумагой и слегка придавите.', 'Выпекайте при 180 °C 15 минут до золотистых краёв. Перед подачей остудите.'], ['Өте піскен бананды шанышқымен біртекті болғанша езіңіз.', 'Сұлы жармасы мен мейізді қосып, жарма жұмсарсын деп 5 минут қалдырыңыз.', 'Қағаз төселген пісіру науасына қасықпен шағын үйінділер салып, сәл бастырыңыз.', '180 °C температурада 15 минут жиектері алтын түске боялғанша пісіріңіз. Жеудің алдында суытыңыз.']],
  'Beef Plov': [['Разогрейте масло в казане с толстым дном и обжарьте нарезанный лук до золотистого цвета.', 'Добавьте кубики говядины и обжаривайте 10 минут, затем добавьте морковь соломкой и готовьте ещё 10 минут.', 'Приправьте, влейте 100 мл воды и тушите под крышкой 40 минут.', 'Выложите сверху промытый рис, добавьте воды на 1,5 см выше риса и воткните в рис чеснок.', 'Готовьте на слабом огне под крышкой 20 минут, не помешивая, затем перемешайте и подавайте.'], ['Қалың түпті қазанда майды қыздырып, туралған пиязды алтын түсті болғанша қуырыңыз.', 'Сиыр етінің кесектерін қосып, 10 минут қызартып, содан кейін сәбізді сіріңке тәрізді турап қосып, тағы 10 минут пісіріңіз.', 'Дәмдеуіш қосып, 100 мл су құйып, қақпақ жауып 40 минут бұқтырыңыз.', 'Үстіне жуылған күрішті жайып, күріштен 1,5 см биік су құйып, сарымсақты батырыңыз.', 'Баяу отта қақпақ жауып, араластырмай 20 минут пісіріңіз, содан кейін араластырып беріңіз.']],
  'Beef Stroganoff': [['Нарежьте говядину тонкими полосками и обваляйте в муке.', 'Быстро обжарьте говядину на сливочном масле и выньте.', 'Обжарьте лук и грибы 8 минут.', 'Верните говядину, вмешайте сметану и тушите 5 минут. Отлично сочетается с картофельным пюре.'], ['Сиыр етін жұқа жолақтап кесіп, ұнға аунатыңыз.', 'Сиыр етін сары майда тез қызартып, алыңыз.', 'Пияз бен саңырауқұлақты 8 минут қуырыңыз.', 'Етті қайтарып салып, қаймақ қосып, 5 минут бұқтырыңыз. Картоп езбесімен өте жақсы.']],
  'Beet Salad with Prunes': [['Отварите или запеките свёклу, затем натрите на тёрке.', 'Порубите грецкие орехи и чернослив, раздавите чеснок.', 'Смешайте всё с майонезом и приправьте.'], ['Қызылшаны қайнатыңыз немесе пісіріңіз, содан кейін үйкеңіз.', 'Грек жаңғағы мен қара өрікті ұсақтап, сарымсақты ұсақтаңыз.', 'Бәрін майонезбен араластырып, дәмдеңіз.']],
  'Berry Smoothie Bowl': [['Взбейте блендером ягоды, банан и йогурт в густой смузи.', 'Разлейте по мискам.', 'Украсьте гранолой и любыми имеющимися фруктами.'], ['Жидектер, банан және йогуртты қою смузи болғанша блендермен араластырыңыз.', 'Тостағандарға құйыңыз.', 'Үстіне гранола және қолыңызда бар кез келген жеміс салыңыз.']],
  'Black Garlic Butter Ramen': [['Сварите яйцо всмятку 6,5 мин, охладите в холодной воде и очистите.', 'Разомните чёрный чеснок вилкой. Растопите сливочное масло, обжарьте свежий чеснок 30 с, добавьте чёрный чеснок и соевый соус.', 'Сварите лапшу, оставьте 4 ст. л. воды от варки, перемешайте всё с маслом с чёрным чесноком до глянцевого вида.', 'Сверху положите яйцо, разрезанное пополам, нарезанный зелёный лук и кунжут. Совет: поставьте оставшиеся корни зелёного лука в стакан с водой — они отрастают заново!'], ['Жұмыртқаны 6,5 мин жұмсақ етіп пісіріңіз, суық суда суытып, аршыңыз.', 'Қара сарымсақты шанышқымен езіңіз. Сары майды ерітіп, жаңа сарымсақты 30 с қуырыңыз, қара сарымсақ пен соя тұздығын қосыңыз.', 'Кеспені пісіріп, пісірген судан 4 ас қасық қалдырыңыз, бәрін қара сарымсақты маймен жылтыр болғанша араластырыңыз.', 'Үстіне екіге кесілген жұмыртқа, туралған жасыл пияз және күнжіт салыңыз. Кеңес: жасыл пияздың қалған тамырларын су құйылған стақанға салып қойыңыз — олар қайта өседі!']],
  'Blistered Shishito Peppers': [['Хорошо вымойте и высушите перцы — мокрые перцы парятся, а не покрываются волдырями.', 'Разогрейте масло в толстой сковороде до очень горячего состояния, выложите перцы в один слой.', 'Жарьте 4–6 минут, переворачивая, пока не появятся волдыри и местами подгорелые пятна.', 'Сбрызните лимоном, посыпьте хлопьями морской соли и ешьте руками. Примерно один из десяти острый!'], ['Бұрыштарды жақсылап жуып, кептіріңіз — дымқыл бұрыштар көпіршімей, буда пісіп кетеді.', 'Майды қалың түпті табада өте қызғанша қыздырып, бұрыштарды бір қабатпен салыңыз.', '4–6 минут аударып отырып, көпіршіп, жерлерінде күйіп қарайғанша қуырыңыз.', 'Үстіне лимон сығып, теңіз тұзының ұлпаларын себіңіз де, қолмен жеңіз. Он бұрыштың бірі шамамен ащы болады!']],
  'Bread Pudding': [['Соберите чёрствый хлеб и нарежьте кубиками.', 'Взбейте молоко, яйца и сахар, залейте хлеб с изюмом.', 'Дайте пропитаться 15 минут, затем выпекайте при 180 °C 35 минут.'], ['Ескі нанды жинап, текшелеп тураңыз.', 'Сүт, жұмыртқа және қантты шайқап, мейізбен бірге нанның үстіне құйыңыз.', '15 минут сіңуге қалдырып, содан кейін 180 °C температурада 35 минут пісіріңіз.']],
  'Broccoli Stem Fritters': [['Срежьте жёсткую кожицу с кочерыжек брокколи и натрите кочерыжки и соцветия на крупной тёрке.', 'Смешайте с яйцами, мукой, тёртым пармезаном, нарезанным зелёным луком, солью и перцем.', 'Жарьте смесь ложкой на масле по 3 минуты с каждой стороны до золотистого цвета.', 'Подавайте с греческим йогуртом в качестве соуса.'], ['Брокколи сабақтарының қатты қабығын кесіп алып, сабақтары мен гүлшоғырларын ірі үккіштен өткізіңіз.', 'Жұмыртқа, ұн, үгітілген пармезан, туралған жасыл пияз, тұз бен бұрышпен араластырыңыз.', 'Қоспаны қасықпен майға салып, әр жағын 3 минуттан алтын түске дейін қуырыңыз.', 'Грек йогуртымен тұздық ретінде ұсыныңыз.']],
  'Broccoli Stem Soup': [['Используйте брокколи целиком — очистите стебли и нарежьте.', 'Припустите лук в сливочном масле, добавьте картофель, брокколи и 800 мл воды.', 'Варите 15 минут, добавьте молоко и взбейте блендером до кремовой консистенции.'], ['Брокколиді түгел пайдаланыңыз — сабақтарын аршып, тураңыз.', 'Пиязды сары майда жұмсарғанша қуырыңыз, картоп, брокколи және 800 мл су қосыңыз.', '15 минут қайнатыңыз, сүт қосып, кремдей болғанша блендермен езіңіз.']],
  'Brown Sugar Boba Milk Tea': [['Заварите крепкий чай: 6 г чёрного чая на 200 мл горячей воды на 5 минут, процедите и остудите.', 'Варите жемчуг тапиоки в большом количестве воды согласно инструкции на упаковке (обычно 5–8 мин), затем оставьте под крышкой на 5 мин.', 'Растопите коричневый сахар с 2 ст. л. воды на слабом огне 2 минуты, добавьте откинутый жемчуг и перемешивайте до блеска.', 'Размажьте липкий сироп по стенкам двух высоких стаканов, добавьте жемчуг, лёд, чай и холодное молоко. Используйте широкую трубочку!', 'Приготовленный жемчуг твердеет через несколько часов — готовьте только то, что выпьете сегодня.'], ['Шайды қою етіп қайнатыңыз: 200 мл ыстық суға 6 г қара шайды 5 минут демдеңіз, сүзіп, суытыңыз.', 'Тапиока меруертін мол суда қаптамада көрсетілгендей (әдетте 5–8 мин) пісіріп, содан кейін жауып 5 мин қалдырыңыз.', 'Қоңыр қантты 2 ас қасық сумен баяу отта 2 минут ерітіңіз, сүзілген меруерт қосып, жылтыраған болғанша араластырыңыз.', 'Жабысқақ сиропты екі биік стақанның қабырғасына жағыңыз, меруерт, мұз, шай және суық сүт қосыңыз. Кең түтікті пайдаланыңыз!', 'Піскен меруерт бірнеше сағатта қатады — тек бүгін ішетініңізді ғана жасаңыз.']],
  'Bruised Aport Apple Pastila': [['Отрежьте только ушибленные места у старых или сморщенных яблок, удалите сердцевину и нарежьте (кожуру можно оставить).', 'Запеките или варите до очень мягкого состояния, около 20 минут, затем взбейте блендером с сахаром в гладкое пюре.', 'Намажьте слоем 5 мм на противень, застеленный бумагой.', 'Сушите в духовке при 80–90 °C с приоткрытой дверцей 5–6 часов, пока не перестанет липнуть. Нарежьте полосками и сверните.'], ['Ескі немесе әжімделген алмалардың тек соғылған жерлерін кесіп тастаңыз, өзегін алып, тураңыз (қабығын қалдыруға болады).', 'Өте жұмсарғанша, шамамен 20 минут пісіріңіз немесе қайнатыңыз, содан кейін қантпен блендермен біртекті езбе жасаңыз.', 'Қағаз төселген пісіру науасына 5 мм қалыңдықта жағыңыз.', 'Духовкада 80–90 °C температурада есігін сәл ашып, жабыспайтын болғанша 5–6 сағат кептіріңіз. Жолақтап кесіп, орап қойыңыз.']],
  'Buckwheat with Chicken': [['Промойте гречку. Варите её в 400 мл подсоленной воды под крышкой 15 минут.', 'Нарежьте лук кубиками и натрите морковь, обжаривайте на масле 5 минут.', 'Добавьте нарезанную кубиками курицу и готовьте 8–10 минут до готовности.', 'Смешайте с гречкой и оставьте под крышкой на 5 минут.'], ['Қарақұманы жуыңыз. Оны 400 мл тұздалған суда қақпақ жауып 15 минут пісіріңіз.', 'Пиязды кубиктеп турап, сәбізді үйкеп, майда 5 минут қуырыңыз.', 'Кубиктеп туралған тауық етін қосып, дайын болғанша 8–10 минут пісіріңіз.', 'Қарақұмаға араластырып, қақпақ астында 5 минут демдеңіз.']],
  'Buckwheat with Mushrooms': [['Варите гречку в 400 мл подсоленной воды 15 минут.', 'Обжарьте лук и грибы на сливочном масле до золотистого цвета.', 'Смешайте с гречкой и оставьте под крышкой на 5 минут.'], ['Қарақұманы 400 мл тұздалған суда 15 минут пісіріңіз.', 'Пияз бен саңырауқұлақты сары майда алтын түсті болғанша қуырыңыз.', 'Қарақұмамен араластырып, қақпақ астында 5 минут демдеңіз.']],
  'Buffalo Cauliflower Bites': [['Разогрейте духовку до 220 °C. Разберите капусту на небольшие соцветия — кочерыжку нарежьте кружками, она запекается не хуже.', 'Взбейте муку со 120 мл воды и щепоткой соли, обмакните соцветия и запекайте на противне с бумагой 20 минут.', 'Растопите сливочное масло в соусе баффало, перемешайте с запечёнными соцветиями и запекайте ещё 8–10 минут, пока не станут липкими.', 'Подавайте с греческим йогуртом как прохладным соусом и палочками сельдерея.'], ['Пешті 220 °C-қа дейін қыздырыңыз. Түсті қырыққабатты кішкентай гүлшоғырларға бөліңіз — сабағын да дөңгелектеп тураңыз, ол да жақсы піседі.', 'Ұнды 120 мл сумен және бір шымшым тұзбен шайқап, гүлшоғырларды малып, қағаз төселген табада 20 минут пісіріңіз.', 'Сары майды баффало тұздығында ерітіп, піскен гүлшоғырларды араластырыңыз да, жабысқақ болғанша тағы 8–10 минут пісіріңіз.', 'Салқын тұздық ретінде грек йогуртымен және балдыркөк таяқшаларымен ұсыныңыз.']],
  'Cabbage Okonomiyaki': [['Мелко нашинкуйте капусту — подойдут и жёсткие верхние листья, и кочерыжка — и нарежьте зелёный лук.', 'Взбейте яйца с мукой и 60 мл воды, затем вмешайте капусту и лук.', 'Вылейте на смазанную сковороду, сверху выложите бекон и жарьте 6 минут на среднем огне.', 'Переверните, жарьте ещё 5 минут и полейте майонезом и соевым соусом.'], ['Қырыққабатты ұсақтап тураңыз — қатты сыртқы жапырақтары мен өзегі де жарайды — және көк пиязды тураңыз.', 'Жұмыртқаны ұнмен және 60 мл сумен шайқап, қырыққабат пен пиязды қосып араластырыңыз.', 'Майланған табаға құйып, үстіне бекон салып, орташа отта 6 минут қуырыңыз.', 'Аударып, тағы 5 минут қуырыңыз да, үстіне майонез бен соя тұздығын құйыңыз.']],
  'Carrot-Top Pesto Pasta': [['Отварите пасту в подсоленной воде до аль денте, оставьте немного воды от пасты.', 'Хорошо промойте морковную ботву и удалите жёсткие стебли — нужны пушистые листья.', 'Измельчите листья в блендере с грецкими орехами, пармезаном, чесноком, оливковым маслом и соком лимона до грубого песто.', 'Перемешайте пасту с песто и небольшим количеством воды от пасты; посолите и поперчите.'], ['Макаронды тұзды суда аль денте күйіне дейін қайнатып, аздап судын қалдырыңыз.', 'Сәбіз жапырағын жақсылап жуып, қатты сабақтарын алып тастаңыз — бізге үлпілдек жапырақтары керек.', 'Жапырақтарды грек жаңғағы, пармезан, сарымсақ, зәйтүн майы және лимон шырынымен блендерде ірі песто болғанша ұсақтаңыз.', 'Макаронды песто мен аздап макарон суымен араластырып, тұз бен бұрыш қосыңыз.']],
  'Chana Dal Tadka': [['Промойте чана дал и замочите в воде на 30 минут (или на ночь), затем слейте воду.', 'Варите дал в 750 мл воды с куркумой и щепоткой соли 30–35 минут, пока он не станет мягким, но сохранит форму. Тем временем сварите рис.', 'Для тадки разогрейте гхи в маленькой сковороде, обжарьте зиру 20 секунд, затем добавьте нарезанный лук и жарьте до золотистого цвета.', 'Добавьте тёртый имбирь, чеснок и нарезанный помидор и готовьте 5 минут до густоты.', 'Влейте тадку в дал, протомите 2 минуты, посыпьте рубленой кинзой и подавайте с рисом.'], ['Чана далды жуып, 30 минутқа (немесе түні бойы) суға салып қойыңыз, сосын суын төгіңіз.', 'Далды 750 мл суда куркума мен бір шымшым тұз қосып, жұмсарғанша, бірақ пішінін сақтайтындай 30–35 минут қайнатыңыз. Осы уақытта күрішті пісіріңіз.', 'Тадка үшін кішкене табада гхиді қыздырып, зиреді 20 секунд қуырыңыз, сосын туралған пиязды қосып, алтын түстенгенше қуырыңыз.', 'Үгітілген зімбір, сарымсақ пен туралған қызанақты қосып, қоюланғанша 5 минут пісіріңіз.', 'Тадканы далға құйып, 2 минут бұқтырыңыз, туралған кинза себіп, күрішпен ұсыныңыз.']],
  'Char Siu Leftover Fried Rice': [['Лучше всего со вчерашним холодным рисом — если его нет, сварите заранее и охладите.', 'Нарежьте оставшуюся свинину чар сиу кубиками. Пожарьте яичницу-болтунью в горячем воке с маслом и отложите.', 'Обжарьте свинину и горошек 2 минуты, добавьте рис и жарьте на сильном огне, помешивая, пока он не начнёт потрескивать.', 'Верните яйца, приправьте соевым соусом, в конце добавьте зелёный лук.'], ['Кешегі суық күрішпен ең дәмді — болмаса, алдын ала пісіріп, суытып қойыңыз.', 'Қалған чар сиу етін текшелеп тураңыз. Жұмыртқаны майлы ыстық вокта араластыра қуырып, бөлек қойыңыз.', 'Ет пен бұршақты 2 минут қуырыңыз, күрішті қосып, шытырлағанша қатты отта араластырыңыз.', 'Жұмыртқаны қайта салып, соя соусымен дәмдеңіз, соңында көк пияз қосыңыз.']],
  'Chicken Caesar Salad': [['Нарежьте хлеб кубиками и подсушите на сухой сковороде до золотистого цвета.', 'Приправьте курицу и жарьте по 6–7 минут с каждой стороны, затем нарежьте.', 'Порвите салат, перемешайте с заправкой.', 'Сверху выложите курицу, сухарики и стружку пармезана.'], ['Нанды кубиктерге тураңыз да, құрғақ табада алтын түсті болғанша қуырыңыз.', 'Тауық етіне дәмдеуіш салып, әр жағынан 6–7 минуттан қуырыңыз, содан кейін тілімдеңіз.', 'Салат жапырақтарын жыртып, тұздықпен араластырыңыз.', 'Үстіне тауық еті, нан кесектері және қырылған пармезан салыңыз.']],
  'Chicken Caesar Wrap': [['Обжарьте курицу и нарежьте.', 'Намажьте тортильи заправкой.', 'Добавьте салат, курицу и пармезан, плотно сверните и разрежьте пополам.'], ['Тауық етін қуырып, тілімдеңіз.', 'Тортильяларға тұздық жағыңыз.', 'Салат, тауық еті және пармезан қосып, тығыз орап, екіге кесіңіз.']],
  'Chicken Curry': [['Обжарьте лук до мягкости, добавьте чеснок, имбирь и порошок карри на 1 минуту.', 'Добавьте кусочки курицы и обжарьте.', 'Влейте помидоры и кокосовое молоко, тушите 25 минут.', 'Подавайте с рисом.'], ['Пиязды жұмсарғанша қуырып, сарымсақ, зімбір және карри ұнтағын қосып, 1 минут қуырыңыз.', 'Тауық етінің кесектерін қосып, қызартыңыз.', 'Қызанақ пен кокос сүтін құйып, 25 минут бұқтырыңыз.', 'Күрішпен беріңіз.']],
  'Chicken Noodle Soup': [['Залейте курицу 2 литрами воды, доведите до кипения и снимите пену.', 'Добавьте целую луковицу и варите 25 минут, затем выньте курицу и разберите на волокна.', 'Добавьте нарезанные морковь и сельдерей, варите 8 минут.', 'Добавьте лапшу и курицу, варите ещё 5 минут и приправьте.'], ['Тауық етіне 2 литр су құйып, қайнатып, көбігін алыңыз.', 'Бүтін пиязды салып, 25 минут пісіріңіз, содан кейін тауықты алып, талшықтап жыртыңыз.', 'Тілімделген сәбіз бен балдыркөк қосып, 8 минут пісіріңіз.', 'Кеспе мен тауық етін қосып, тағы 5 минут пісіріп, дәмдеңіз.']],
  'Chicken Stir-Fry': [['Сварите рис.', 'Обжарьте тонкие полоски курицы на горячем масле 5 минут и выньте.', 'Обжарьте овощи с чесноком и имбирём 4 минуты.', 'Верните курицу, добавьте соевый соус, перемешайте 1 минуту и подавайте с рисом.'], ['Күріш пісіріңіз.', 'Тауық етінің жұқа жолақтарын қызған майда 5 минут қуырып, алыңыз.', 'Көкөністерді сарымсақ және зімбірмен 4 минут қуырыңыз.', 'Тауық етін қайтарып салып, соя тұздығын қосып, 1 минут араластырып, күрішпен беріңіз.']],
  'Chili Con Carne': [['Обжарьте лук и перец, добавьте говядину и обжарьте.', 'Добавьте нарезанный перец чили, помидоры и специи.', 'Тушите 30 минут, затем добавьте фасоль и готовьте ещё 10 минут.', 'Подавайте с рисом, хлебом или кукурузными чипсами.'], ['Пияз бен бұрышты қуырып, сиыр етін қосып, қызартыңыз.', 'Туралған чили бұрышы, қызанақ және дәмдеуіштер қосыңыз.', '30 минут бұқтырып, содан кейін үрмебұршақ қосып, тағы 10 минут пісіріңіз.', 'Күріш, нан немесе жүгері чипстерімен беріңіз.']],
  'Chili Crisp Fried Eggs on Rice': [['Сварите рис — или лучше разогрейте вчерашний рис на сковороде с небольшим количеством воды.', 'Выложите ложкой чили-крисп на холодную антипригарную сковороду и нагрейте до шипения.', 'Разбейте яйца и жарьте 2–3 минуты, пока края не станут хрустящими, а желтки останутся жидкими.', 'Переложите яйца на рис, полейте соевым соусом и острым маслом со сковороды.'], ['Күріш пісіріңіз — немесе кешегі күрішті табада аздап сумен жылытқан дұрыс.', 'Чили криспті қасықпен суық жабыспайтын табаға салып, сыртылдағанша қыздырыңыз.', 'Жұмыртқаларды жарып салып, жиектері қытырлақ болып, сарысы әлі сұйық күйінде қалғанша 2–3 минут қуырыңыз.', 'Жұмыртқаларды күрішке сырғытып салып, соя тұздығымен және табадағы ащы маймен құйыңыз.']],
  'Classic Borscht': [['Залейте говядину 2,5 литрами холодной воды, доведите до кипения и варите на слабом огне 1 час 15 минут.', 'Натрите свёклу и морковь, нарежьте лук кубиками, обжаривайте 10 минут.', 'Добавьте в бульон нарезанный кубиками картофель, варите 10 минут.', 'Добавьте нашинкованную капусту и обжаренные овощи, варите ещё 15 минут.', 'Приправьте, дайте настояться 10 минут и подавайте со сметаной.'], ['Сиыр етіне 2,5 литр салқын су құйып, қайнатып, баяу отта 1 сағат 15 минут пісіріңіз.', 'Қызылша мен сәбізді үйкеп, пиязды кубиктеп турап, 10 минут қуырыңыз.', 'Сорпаға кубиктеп туралған картопты қосып, 10 минут пісіріңіз.', 'Туралған қырыққабат пен қуырылған көкөністерді қосып, тағы 15 минут пісіріңіз.', 'Дәмдеуіш қосып, 10 минут демдеп, қаймақпен беріңіз.']],
  'Classic Guacamole': [['Разомните авокадо с соком лайма и солью.', 'Вмешайте нарезанные кубиками помидор, лук и рубленую кинзу.', 'Сразу подавайте с чипсами или на тосте.'], ['Авокадоны лайм шырыны және тұзбен езіңіз.', 'Кубиктеп туралған қызанақ, пияз және туралған кинза қосып араластырыңыз.', 'Чипстермен немесе тостпен бірден беріңіз.']],
  'Classic Omelette': [['Разбейте яйца в миску, добавьте молоко и щепотку соли, взбейте до однородности.', 'Растопите сливочное масло на антипригарной сковороде на среднем огне.', 'Влейте смесь и готовьте 2–3 минуты, пока края не схватятся.', 'Сложите пополам, готовьте ещё 1 минуту и подавайте горячим.'], ['Жұмыртқаларды тостағанға шартылдатып, сүт пен бір шымшым тұз қосып, біркелкі болғанша шайқаңыз.', 'Жабыспайтын табада сары майды орташа отта ерітіңіз.', 'Қоспаны құйып, жиектері қатқанша 2–3 минут пісіріңіз.', 'Екі бүктеп, тағы 1 минут пісіріп, ыстықтай беріңіз.']],
  'Clean-Out Egg Muffins': [['Разогрейте духовку до 190 °C и смажьте форму для маффинов.', 'Нарежьте любые овощи, которые нужно использовать — увядший шпинат, половинку перца, зелёный лук.', 'Взбейте яйца с солью, добавьте овощи и тёртый сыр.', 'Наполните 6 формочек для маффинов и выпекайте 18–20 минут до готовности.', 'Храните в холодильнике до 4 дней — завтрак на ходу на всю неделю.'], ['Духовканы 190 °C-қа дейін қыздырып, маффин қалыбын майлаңыз.', 'Пайдалану керек кез келген көкөністерді тураңыз — солған шпинат, жарты бұрыш, жасыл пияз.', 'Жұмыртқаны тұзбен шайқап, көкөністер мен үгілген ірімшікті қосыңыз.', '6 маффин қалыбын толтырып, піскенше 18–20 минут пісіріңіз.', 'Тоңазытқышта 4 күнге дейін сақтаңыз — бүкіл аптаға арналған жолға алып кетуге болатын таңғы ас.']],
  'Clean-the-Fridge Quesadilla': [['Используйте любые остатки: половинку перца, немного кукурузы, фасоль или курицу.', 'Выложите сыр и начинку на половину каждой тортильи, сложите пополам.', 'Обжаривайте на сухой сковороде по 2–3 минуты с каждой стороны, пока сыр не расплавится.'], ['Кез келген қалдықтарды пайдаланыңыз: жарты бұрыш, аздап жүгері, үрмебұршақ немесе тауық еті.', 'Әр тортильяның жартысына ірімшік пен салмасын жайып, бүктеңіз.', 'Құрғақ табада әр жағынан 2–3 минуттан ірімшік еріп кеткенше қуырыңыз.']],
  'Cottage Cheese Ice Cream': [['Взбейте творог с мёдом в блендере до полной гладкости.', 'Разомните или нарежьте клубнику — мягкие, помятые ягоды здесь идеальны — и вмешайте.', 'Переложите в контейнер и заморозьте на 3 часа, перемешав один раз через час.', 'Оставьте на столе на 10 минут, чтобы смягчилось, и раскладывайте шариками.'], ['Сүзбені балмен бірге блендерде толық біркелкі болғанша шайқаңыз.', 'Құлпынайды езіп немесе туралап, араластырыңыз — жұмсақ, мыжылған жидектер бұған өте қолайлы.', 'Контейнерге салып, 3 сағатқа мұздатыңыз, бір сағаттан кейін бір рет араластырыңыз.', 'Жұмсаруы үшін 10 минут үстелде қалдырып, шар етіп салыңыз.']],
  'Creamy Cheese Pasta': [['Вскипятите 2 литра подсоленной воды и варите пасту 9–10 минут. Слейте воду.', 'Растопите сливочное масло на сковороде на слабом огне, влейте молоко.', 'Добавьте тёртый сыр и помешивайте 2–3 минуты, пока соус не станет однородным.', 'Перемешайте пасту с соусом и сразу подавайте.'], ['2 литр тұздалған суды қайнатып, макарон бұйымын 9–10 минут пісіріңіз. Суын сүзіп алыңыз.', 'Табада сары майды баяу отта ерітіп, сүтті құйыңыз.', 'Үккіштен өткізілген ірімшік қосып, тұздық біркелкі болғанша 2–3 минут араластырыңыз.', 'Макаронды тұздыққа араластырып, бірден беріңіз.']],
  'Creamy Mushroom Soup': [['Обжарьте лук, морковь и нарезанные грибы 10 минут.', 'Добавьте нарезанный кубиками картофель и 1,5 литра воды, варите 20 минут.', 'Взбейте блендером половину супа для кремовости, вмешайте сметану.'], ['Пияз, сәбіз және тілімделген саңырауқұлақты 10 минут қуырыңыз.', 'Кубиктеп туралған картоп пен 1,5 литр су қосып, 20 минут пісіріңіз.', 'Кремдей болуы үшін сорпаның жартысын блендермен ұсақтап, қаймақ қосыңыз.']],
  'Crispy Pork Katsu Bowl': [['Промойте рис и сварите: 150 г риса на 200 мл воды, 12 минут под крышкой, затем 10 минут дайте постоять.', 'Отбейте свиные отбивные до 1 см, посолите и поперчите. Обваляйте в муке, затем во взбитом яйце, затем в панко — хорошо прижмите.', 'Жарьте в горячем масле по 3–4 минуты с каждой стороны до глубокого золотистого цвета и готовности. Дайте отдохнуть 2 минуты на решётке и нарежьте полосками.', 'Нашинкуйте капусту как можно тоньше. Разложите по мискам рис и капусту, сверху — кацу, полейте соусом тонкацу.'], ['Күрішті жуып пісіріңіз: 150 г күрішке 200 мл су, қақпақ астында 12 минут, содан кейін 10 минут тұрсын.', 'Шошқа етін 1 см-ге дейін соғып, тұз бен бұрыш себіңіз. Алдымен ұнға, сосын шайқалған жұмыртқаға, кейін панкоға аунатып, жақсылап басыңыз.', 'Ыстық майда әр жағын 3–4 минуттан қою алтын түске енгенше және піскенше қуырыңыз. Торда 2 минут тұрғызып, жолақтап тураңыз.', 'Қырыққабатты барынша жұқа тураңыз. Ыдыстарға күріш пен қырыққабат салып, үстіне кацуды қойыңыз да, тонкацу соусын құйыңыз.']],
  'Crispy Rice Paper Dumplings': [['Мелко нашинкуйте капусту и натрите морковь — подойдут и верхние листья, и остатки любых овощей из холодильника. Раскрошите тофу и порежьте зелёный лук.', 'Обжарьте начинку на половине кунжутного масла 4 минуты, заправьте половиной соевого соуса и дайте немного остыть.', 'Окуните сразу два листа рисовой бумаги в тёплую воду на 5 секунд, выложите в центр 2 ложки начинки и сверните квадратным конвертом.', 'Обжарьте конверты швом вниз на оставшемся масле по 3–4 минуты с каждой стороны до золотистой корочки. Подавайте с остатком соевого соуса.'], ['Қырыққабатты ұсақтап турап, сәбізді үккіштен өткізіңіз — сыртқы жапырақтар мен тоңазытқыштағы кез келген көкөніс қалдықтары да жарайды. Тофуды ұнтақтап, жасыл пиязды тураңыз.', 'Салманы күнжіт майының жартысында 4 минут қуырып, соя тұздығының жартысын қосыңыз да, сәл суытыңыз.', 'Күріш қағазының екі парағын бірге жылы суға 5 секундқа батырып, ортасына 2 қасық салма салып, шаршы конверт етіп ораңыз.', 'Конверттерді тігісін төмен қаратып, қалған майда әр жағын 3–4 минуттан қызарғанша қуырыңыз. Қалған соя тұздығымен ұсыныңыз.']],
  'Crispy Rice Salad': [['Распределите холодный оставшийся рис тонким слоем на смазанном противне и запекайте при 220 °C 20 минут до хруста, затем разломайте.', 'Нарежьте огурец и морковь тонкой соломкой, а зелёный лук — колечками.', 'Смешайте соевый соус, сок лайма и кунжутное масло — это заправка.', 'Перемешайте овощи с заправкой, сверху выложите хрустящий рис и рубленый арахис и сразу подавайте.'], ['Қалған суық күрішті майланған табаққа жұқа етіп жайып, 220 °C-та 20 минут қытырлақ болғанша пісіріп, бөліктерге сындырыңыз.', 'Қиярды және сәбізді жіңішке етіп, көк пиязды сақина етіп тураңыз.', 'Соя тұздығын, лайм шырынын және күнжіт майын араластырып, тұздық жасаңыз.', 'Көкөністерді тұздықпен араластырып, үстіне қытырлақ күріш пен туралған жержаңғақ салып, бірден ұсыныңыз.']],
  'Crispy Smashed Sunchokes': [['Хорошо отмойте топинамбур щёткой — кожуру не снимайте, она станет хрустящей и ореховой.', 'Отварите его в подсоленной воде 15 минут, пока нож не будет входить легко.', 'Слейте воду, раздавите каждый клубень стаканом и смажьте оливковым маслом с рубленым чесноком и розмарином.', 'Запекайте при 220 °C 25 минут, пока края не станут хрустящими.', 'Сбрызните лимоном, посыпьте хлопьями морской соли и подавайте горячим.'], ['Топинамбурды щеткамен жақсылап жуыңыз — қабығын аршымаңыз, ол қытырлақ әрі жаңғақ дәмді болады.', 'Пышақ оңай кіргенше тұзды суда 15 минут қайнатыңыз.', 'Суын төгіп, әрқайсысын стақанмен басып жалпайтыңыз да, туралған сарымсақ пен розмарин қосылған зәйтүн майымен жағыңыз.', 'Шеттері қытырлақ болғанша 220 °C-та 25 минут пісіріңіз.', 'Үстіне лимон сығып, теңіз тұзының үлпектерін себіңіз де, ыстықтай ұсыныңыз.']],
  'Dense Bean Salad': [['Слейте жидкость с нута и фасоли и промойте их.', 'Нарежьте кубиками огурец, красный лук и вяленые томаты; порубите петрушку вместе со стеблями.', 'Взбейте лимонный сок с оливковым маслом, солью и перцем.', 'Перемешайте всё с раскрошенной фетой. Салат хранится в холодильнике 3 дня — добавьте любые оставшиеся овощи.'], ['Ноқат пен бұршақтың суын төгіп, жуыңыз.', 'Қиярды, қызыл пиязды және кептірілген қызанақты текшелеп тураңыз; ақжелкенді сабағымен бірге туралаңыз.', 'Лимон шырынын зәйтүн майымен, тұзбен және бұрышпен шайқаңыз.', 'Барлығын үгітілген фетамен араластырыңыз. Салат тоңазытқышта 3 күн сақталады — қалған кез келген көкөністі қосыңыз.']],
  'Dorm Grilled Cheese with Tomato': [['Слегка чёрствый хлеб подходит лучше всего — он становится хрустящим.', 'Намажьте маслом внешние стороны двух ломтиков. Положите между ними сыр и нарезанный помидор.', 'Жарьте на сухой сковороде на среднем огне по 3 минуты с каждой стороны, прижимая лопаткой, до золотистого цвета и расплавленного сыра.'], ['Сәл ескі нан ең жақсы жарайды — ол қытырлақ болады.', 'Екі тілімнің сыртқы жағын майлаңыз. Араларына ірімшік пен тілімделген қызанақты салыңыз.', 'Құрғақ табада орташа отта әр жағынан 3 минуттан, күрекшемен басып, алтын түске боялып, ірімшік еріп кеткенше қуырыңыз.']],
  'Dorm Lobio with Walnuts': [['Используйте варёную или консервированную фасоль; оставьте немного жидкости.', 'Обжарьте нарезанный лук в масле до мягкости и золотистого цвета, около 6 минут.', 'Добавьте фасоль с 3–4 ложками жидкости, разомните примерно половину вилкой и прогрейте.', 'Измельчите грецкие орехи и чеснок, добавьте их с рубленой кинзой, солью и перцем. Вкусно и горячим, и холодным.'], ['Піскен немесе консервіленген үрмебұршақты пайдаланыңыз; пісірген сұйықтығынан аздап қалдырыңыз.', 'Туралған пиязды майда жұмсарып, алтын түске боялғанша, шамамен 6 минут қуырыңыз.', 'Үрмебұршақты 3–4 қасық сұйықпен қосып, жартысын шанышқымен езіңіз де, қыздырыңыз.', 'Грек жаңғағы мен сарымсақты ұсақтап, туралған кинзамен, тұз және бұрышпен бірге қосыңыз. Ыстық та, суық та дәмді.']],
  'Draniki (Potato Pancakes)': [['Натрите картофель и лук, отожмите жидкость.', 'Смешайте с яйцом, мукой и солью.', 'Выкладывайте ложкой в горячее масло и жарьте по 3–4 минуты с каждой стороны до хруста.', 'Подавайте горячими со сметаной.'], ['Картоп пен пиязды үйкеп, суын сығыңыз.', 'Жұмыртқа, ұн және тұзбен араластырыңыз.', 'Қасықпен қызған майға салып, әр жағынан 3–4 минуттан қытырлақ болғанша қуырыңыз.', 'Қаймақпен ыстықтай беріңіз.']],
  'Dubai Chocolate Bar': [['Нарежьте катаифи короткими кусочками и обжарьте на сливочном масле на среднем огне, помешивая, до золотистого цвета и хруста (5–7 мин). Остудите.', 'Смешайте хрустящий катаифи с фисташковым кремом и тахини — это знаменитая зелёная начинка.', 'Растопите шоколад (в микроволновке по 20 секунд). Нанесите тонкий слой кисточкой в форму или небольшую посуду, застеленную бумагой, и охладите 10 мин.', 'Выложите сверху начинку, накройте остатками шоколада и охладите 1 час.', 'Режьте горячим ножом и наслаждайтесь хрустом. Хранится 5 дней в холодильнике.'], ['Кататифиді қысқа бөліктеп турап, сары майда орташа отта араластыра отырып, алтын түске боялып, қытырлақ болғанша қуырыңыз (5–7 мин). Суытыңыз.', 'Қытырлақ кататифиді пісте кремі және тахинимен араластырыңыз — бұл әйгілі жасыл салма.', 'Шоколадты ерітіңіз (микротолқынды пеште 20 секундтан). Жұқа қабатын қалыпқа немесе қағаз төселген шағын пішінге щеткамен жағып, 10 мин салқындатыңыз.', 'Үстіне салманы жайып, қалған шоколадпен жауып, 1 сағат салқындатыңыз.', 'Ыстық пышақпен кесіп, қытырлақтан ләззат алыңыз. Тоңазытқышта 5 күн сақталады.']],
  'Egg Fried Noodles': [['Отварите лапшу и слейте воду.', 'Приготовьте яйца-болтунью на горячем масле, отодвиньте в сторону.', 'Добавьте бок-чой и обжаривайте 2 минуты, затем добавьте лапшу и соевый соус.', 'Перемешайте всё вместе, посыпьте зелёным луком.'], ['Кеспені пісіріп, суын сүзіңіз.', 'Жұмыртқаны қызған майда бұзып қуырып, шетке ысырыңыз.', 'Бок-чой қосып, 2 минут қуырыңыз, содан кейін кеспе мен соя тұздығын қосыңыз.', 'Бәрін араластырып, үстіне жас пияз себіңіз.']],
  'Everything Veggie Soup': [['Мягкие или сморщенные овощи здесь как раз подойдут — просто отрежьте испорченные места.', 'Обжарьте лук и морковь в кастрюле 5 минут.', 'Добавьте нарезанный кубиками картофель, капусту и цукини, залейте 1,5 литра воды.', 'Варите 25 минут, приправьте. Если любите кремовую текстуру, взбейте блендером.'], ['Жұмсарған немесе әжім түскен көкөністер мұнда өте жақсы — тек бүлінген жерлерін кесіп тастаңыз.', 'Кастрюльде пияз бен сәбізді 5 минут қуырыңыз.', 'Кубиктеп туралған картоп, қырыққабат және кабачок қосып, 1,5 литр су құйыңыз.', '25 минут пісіріп, дәмдеңіз. Кремдей болғанын қаласаңыз, блендермен ұсақтаңыз.']],
  'Feta Fried Eggs': [['Раскрошите фету на сухую антипригарную сковороду ровным кольцом и нагрейте, пока она не расплавится и не зашкворчит.', 'Разбейте яйца в центр и жарьте 3 минуты, пока белки не схватятся, а фета не станет золотистой и хрустящей.', 'Подогрейте тортилью на второй сковороде 30 секунд и намажьте размятым авокадо.', 'Переложите яйца с хрустящей фетой на тортилью, посыпьте хлопьями чили и сложите.'], ['Фетаны құрғақ, күйіп қалмайтын табаға тегіс шеңбер етіп үгітіп салып, ериіп шыжылдағанша қыздырыңыз.', 'Жұмыртқаларды ортасына жарып, ақуызы қатып, фета алтын түсті әрі қытырлақ болғанша 3 минут қуырыңыз.', 'Тортильяны екінші табада 30 секунд жылытып, үстіне езілген авокадо жағыңыз.', 'Қытырлақ фетасы бар жұмыртқаны тортильяға салып, чили үгіндісін себіп, бүктеңіз.']],
  'Fish Tacos': [['Приправьте рыбу солью, паприкой и цедрой лайма, жарьте по 3 минуты с каждой стороны.', 'Тонко нашинкуйте капусту и смешайте с соком лайма.', 'Разогрейте тортильи, добавьте рыбу, капусту, сметану и кинзу.'], ['Балыққа тұз, паприка және лайм қабығын себіп, әр жағынан 3 минуттан қуырыңыз.', 'Қырыққабатты жұқа турап, лайм шырынымен араластырыңыз.', 'Тортильяларды жылытып, балық, қырыққабат, қаймақ және кинза салыңыз.']],
  'Flank Steak Tacos with Zhoug': [['Посолите фланк-стейк и обжарьте на очень горячей сковороде по 4 минуты с каждой стороны.', 'Дайте стейку отдохнуть 5 минут, затем тонко нарежьте поперёк волокон.', 'Подогрейте тортильи, тонко нарежьте красный лук и сбрызните его соком лайма.', 'Наполните тортильи стейком, луком и ложкой схуга.'], ['Фланк-стейкті тұздап, өте ыстық табада әр жағын 4 минуттан қуырыңыз.', 'Стейкті 5 минут тынықтырып, талшықтарына көлденең жұқа тураңыз.', 'Тортильяларды жылытып, қызыл пиязды жұқа турап, үстіне лайм шырынын сығыңыз.', 'Тортильяларға стейк, пияз және бір қасық схуг салыңыз.']],
  'Fluffy Baursaks': [['Слегка подогрейте молоко, добавьте дрожжи и сахар, подождите 10 минут, пока не появится пена.', 'Добавьте яйцо, щепотку соли и муку, замесите мягкое тесто. Накройте и оставьте в тёплом месте на 1 час.', 'Раскатайте тесто толщиной 1 см и нарежьте квадратами или ромбами.', 'Обжарьте во фритюре в горячем масле по 1–2 минуты с каждой стороны до золотистого цвета и пышности. Выложите на бумажные полотенца.', 'Подавайте тёплыми с чаем, мёдом или вареньем.'], ['Сүтті сәл жылытып, ашытқы мен қантты қосыңыз, көбік пайда болғанша 10 минут күтіңіз.', 'Жұмыртқа, бір ұстам тұз және ұн қосып, жұмсақ қамыр илеңіз. Жауып, жылы жерде 1 сағат қалдырыңыз.', 'Қамырды 1 см қалыңдықта жайып, шаршылап немесе ромбылап кесіңіз.', 'Қызған майда әр жағынан 1–2 минуттан алтын түске боялып, ісінгенше қуырыңыз. Қағаз сүлгіге салып майын сүзіңіз.', 'Шай, бал немесе тосаппен жылы күйінде беріңіз.']],
  'Fluffy Pancakes': [['Смешайте муку, сахар, щепотку соли и разрыхлитель.', 'Вмешайте молоко, яйца и растопленное сливочное масло.', 'Жарьте небольшие панкейки на горячей сковороде по 2 минуты с каждой стороны.'], ['Ұн, қант, бір шымшым тұз және разрыхлительді араластырыңыз.', 'Сүт, жұмыртқа және ерітілген сары майды қосып, шайқаңыз.', 'Шағын панкейктерді қызған табада әр жағынан 2 минуттан пісіріңіз.']],
  'Fregola with Clams': [['Хорошо промойте моллюсков и выбросьте те, что остаются открытыми, если по ним постучать.', 'Обжарьте чеснок, нарезанные стебли петрушки и хлопья чили в оливковом масле, добавьте нарезанные помидоры и готовьте 5 минут.', 'Всыпьте фреголу, влейте 400 мл воды и варите 10 минут, иногда помешивая.', 'Добавьте вино и моллюсков, накройте и готовьте 4–5 минут, пока раковины не раскроются; посыпьте листьями петрушки.'], ['Моллюскаларды жақсылап жуып, қаққанда ашық күйінде қалғандарын тастаңыз.', 'Сарымсақты, туралған ақжелкек сабақтарын және чили үгіндісін зәйтүн майында қуырып, туралған қызанақты қосып, 5 минут пісіріңіз.', 'Фреголаны салып, 400 мл су құйыңыз да, анда-санда араластырып, 10 минут қайнатыңыз.', 'Шарап пен моллюскаларды қосып, қақпағын жауып, қабыршақтары ашылғанша 4–5 минут пісіріңіз; ақжелкек жапырақтарын себіңіз.']],
  'French Toast': [['Лучше всего подойдёт сухой хлеб вчерашней выпечки — он не разваливается.', 'Взбейте яйца с молоком, сахаром и щепоткой корицы.', 'Вымачивайте ломтики 20 секунд, жарьте на сливочном масле по 2–3 минуты с каждой стороны.'], ['Кеше пісірілген құрғақ нан ең жақсы жарайды — ол быт-шыт болмайды.', 'Жұмыртқаны сүт, қант және бір ұстам даршынмен шайқаңыз.', 'Тілімдерді 20 секунд малып, сары майда әр жағынан 2–3 минуттан қуырыңыз.']],
  'Fresh Spring Rolls': [['Отварите креветки 2 минуты и разрежьте вдоль пополам; залейте рисовую лапшу горячей водой, пока не станет мягкой.', 'Нарежьте морковь и огурец тонкой соломкой, порвите салат руками.', 'Окуните лист рисовой бумаги в тёплую воду на несколько секунд, положите на стол, выложите салат, лапшу, овощи, мяту и креветки и плотно сверните, подогнув края.', 'Смешайте арахисовую пасту с соусом хойсин и небольшим количеством тёплой воды — получится соус для макания.'], ['Асшаяндарды 2 минут пісіріп, ұзынынан екіге бөліңіз; күріш кеспесін жұмсарғанша ыстық суға салыңыз.', 'Сәбіз бен қиярды жіңішке таяқшалап турап, салат жапырағын қолмен жыртыңыз.', 'Күріш қағазын бірнеше секундқа жылы суға батырып, үстелге жайыңыз, үстіне салат, кеспе, көкөніс, жалбыз және асшаян салып, шеттерін бүктеп, тығыз ораңыз.', 'Жержаңғақ пастасын хойсин тұздығымен және аздап жылы сумен араластырып, батыратын тұздық жасаңыз.']],
  'Fresh Summer Salad': [['Вымойте овощи и нарежьте их небольшими кусочками.', 'Смешайте в миске, добавьте сметану, соль и перец.', 'Аккуратно перемешайте и сразу подавайте.'], ['Көкөністерді жуып, шағын кесектерге тураңыз.', 'Тостағанда араластырып, қаймақ, тұз және бұрыш қосыңыз.', 'Ақырын араластырып, бірден беріңіз.']],
  'Fridge-Clean-Out Gyoza': [['Мелко нарежьте капусту, посолите и отожмите воду через 10 мин. Натрите морковь и имбирь — сморщенные овощи с нижней полки подойдут.', 'Смешайте свинину, овощи, зелёный лук, 1 ст. л. соевого соуса и кунжутное масло.', 'Положите чайную ложку начинки на каждую обёртку, смочите край и защипните, сделав 4–5 складок.', 'Обжарьте плоской стороной вниз в масле 2 мин, влейте 80 мл воды, накройте и готовьте на пару 5 мин, затем снимите крышку и жарьте до хруста.', 'Макайте в соевый соус с небольшим количеством уксуса. Лишнее заморозьте сырым на подносе, затем в пакете — готовьте прямо из морозилки.'], ['Орамжапырақты майда турап, тұздап, 10 мин өткен соң суын сығып алыңыз. Сәбіз бен зімбірді үккіштен өткізіңіз — астыңғы жәшіктегі әжім түскен көкөністер де жарайды.', 'Шошқа еті, көкөністер, жасыл пияз, 1 ас қасық соя тұздығы және күнжіт майын араластырыңыз.', 'Әр жұқа қамырға бір шай қасық салма салып, жиегін ылғалдап, 4–5 қатпарлап түйіңіз.', 'Жалпақ жағымен майда 2 мин қуырыңыз, 80 мл су құйып, жауып 5 мин буда пісіріңіз, содан кейін қақпағын ашып, қытырлақ болғанша қуырыңыз.', 'Аздаған сірке суы бар соя тұздығына малыңыз. Артығын науада шикі күйінде қатырып, содан кейін пакетке салыңыз — мұздатқыштан тікелей пісіріңіз.']],
  'Fridge-Clearing Frittata': [['Отварите или обжарьте нарезанный кубиками картофель до мягкости. Подойдут любые остатки овощей!', 'Взбейте яйца с солью и тёртым сыром.', 'Обжарьте перец и шпинат 2 минуты, добавьте картофель, залейте яйцами.', 'Готовьте на слабом огне 5 минут, затем доведите до готовности под грилем духовки 3 минуты.'], ['Кубиктеп туралған картопты жұмсарғанша қайнатыңыз немесе қуырыңыз. Қалған кез келген көкөніс жарайды!', 'Жұмыртқаны тұз және үккіштен өткізілген ірімшікпен шайқаңыз.', 'Бұрыш пен саумалдықты 2 минут қуырып, картопты қосып, жұмыртқа қоспасын құйыңыз.', 'Баяу отта 5 минут пісіріп, содан кейін пештің грилінде 3 минут дайындаңыз.']],
  'Fried Eggs with Soft Tomatoes': [['Нарежьте мягкие помидоры ломтиками и обжарьте на сливочном масле 3 минуты.', 'Разбейте сверху яйца, накройте крышкой и готовьте до готовности белка.', 'Приправьте солью, перцем и травами.'], ['Жұмсақ қызанақтарды тілімдеп, сары майда 3 минут қуырыңыз.', 'Үстіне жұмыртқаларды жарып салыңыз, қақпақпен жауып, қатқанша пісіріңіз.', 'Тұз, бұрыш және шөптермен дәмдеңіз.']],
  'Frisée Salad with Bacon and Egg': [['Нарежьте чёрствый хлеб кубиками и обжарьте в оливковом масле до золотистого цвета — вот и гренки.', 'Обжарьте бекон полосками до хруста, затем 1 минуту потомите нарезанный шалот в беконном жире.', 'Вмешайте в тёплую сковороду горчицу и лимонный сок — получится заправка; перемешайте её с порванным фризе.', 'Сварите яйца пашот или всмятку и выложите сверху вместе с беконом и гренками.'], ['Қатқан нанды текшелеп туралап, зәйтүн майында алтын түске дейін қуырыңыз — дайын кептірілген нан.', 'Беконды жолақтап қытырлақ болғанша қуырыңыз, содан кейін туралған шалотты бекон майында 1 минут жұмсартыңыз.', 'Жылы табаға қыша мен лимон шырынын араластырып, тұздық жасаңыз да, жұлынған фриземен араластырыңыз.', 'Жұмыртқаны пашот немесе жартылай пісіріп, бекон мен кептірілген нанмен бірге үстіне салыңыз.']],
  'Fruit Yogurt Bowl': [['Вымойте яблоко и удалите сердцевину, очистите банан и апельсин.', 'Нарежьте все фрукты мелкими кусочками.', 'Разложите по двум мискам и залейте йогуртом.'], ['Алманы жуып, өзегін алыңыз, банан мен апельсинді аршыңыз.', 'Барлық жемістерді ұсақ кесектерге тураңыз.', 'Екі тостағанға бөліп, йогурт құйыңыз.']],
  'Garlic Butter Enoki': [['Срежьте корешок эноки и разберите грибы на небольшие пучки.', 'Растопите сливочное масло и обжарьте рубленый чеснок 30 секунд.', 'Добавьте эноки и обжаривайте по 2 минуты с каждой стороны до золотистого цвета.', 'Влейте соевый соус, смешанный с мёдом, перемешайте 1 минуту и посыпьте зелёным луком.'], ['Эноки тамырын кесіп тастап, саңырауқұлақтарды шағын шоқтарға бөліңіз.', 'Сары майды ерітіп, туралған сарымсақты 30 секунд қуырыңыз.', 'Энокиді қосып, әр жағын 2 минуттан алтын түске енгенше қуырыңыз.', 'Балмен араластырылған соя соусын құйып, 1 минут араластырыңыз да, көк пиязбен себіңіз.']],
  'Garlic Water Spinach Stir-Fry': [['Сварите рис. Нарежьте водяной шпинат кусками по 6 см, отдельно стебли и листья — стебли самые вкусные, ничего не выбрасывайте.', 'Разогрейте 1 ст. л. масла в воке до дымка, обжарьте нарезанный чеснок и чили 20 секунд.', 'Добавьте стебли и жарьте 1 минуту, затем добавьте листья и 2 ст. л. воды.', 'Вмешайте устричный соус и перемешивайте, пока листья не опадут, около 1 минуты; подавайте с рисом.'], ['Күрішті пісіріңіз. Су шпинатын 6 см-ден кесіңіз, сабақтары мен жапырақтарын бөлек ұстаңыз — сабақтары ең дәмді бөлігі, ештеңені тастамаңыз.', 'Вокта 1 ас қасық майды түтін шыққанша қыздырып, туралған сарымсақ пен чилиді 20 секунд қуырыңыз.', 'Сабақтарын қосып, 1 минут қуырыңыз, содан кейін жапырақтары мен 2 ас қасық су қосыңыз.', 'Устрица тұздығын қосып, жапырақтары солғанша шамамен 1 минут араластырыңыз; күрішпен бірге ұсыныңыз.']],
  'Gochujang Butter Noodles': [['Отварите спагетти в подсолённой воде, перед тем как слить, сохраните чашку воды от пасты.', 'Растопите сливочное масло в сковороде, вмешайте кочхуджан, соевый соус и мёд и готовьте 1 минуту.', 'Перемешайте лапшу с соусом, добавив немного воды от пасты, до глянцевого блеска.', 'Пожарьте яйца, выложите сверху и посыпьте нарезанным зелёным луком.'], ['Спагеттиді тұзды суда пісіріңіз, суын төкпес бұрын бір кесе макарон суын сақтап қойыңыз.', 'Табада сары майды ерітіп, кочхуджан, соя тұздығы мен балды қосып, 1 минут пісіріңіз.', 'Кеспені тұздықпен араластырып, жылтырағанша аздап макарон суын қосыңыз.', 'Жұмыртқаларды қуырып, үстіне салыңыз да, туралған жасыл пияз себіңіз.']],
  'Golubtsy (Cabbage Rolls)': [['Бланшируйте кочан капусты в кипящей воде и отделите мягкие листья.', 'Смешайте мясо с полуготовым рисом и жареным луком.', 'Заверните в каждый лист ложку начинки.', 'Уложите в кастрюлю, добавьте морковь, томатную пасту и воду. Тушите 50 минут.'], ['Қырыққабат кочанын қайнап тұрған суда бланшірлеп, жұмсарған жапырақтарын ажыратыңыз.', 'Етті жартылай піскен күріш және қуырылған пиязбен араластырыңыз.', 'Әр жапыраққа бір қасықтан бастама орап салыңыз.', 'Кастрюльге тізіп, сәбіз, томат пастасы және су қосыңыз. 50 минут бұқтырыңыз.']],
  'Greek Salad': [['Нарежьте помидоры, огурец и перец крупными кусками, лук нарежьте тонкими ломтиками.', 'Выложите всё в миску и добавьте маслины.', 'Сверху положите фету целым куском или крупными кубиками.', 'Полейте оливковым маслом, посыпьте орегано и подавайте.'], ['Қызанақ, қияр және бұрышты ірі кесектерге, пиязды жұқа тілімдеп тураңыз.', 'Бәрін тостағанға салып, зәйтүн қосыңыз.', 'Үстіне фета ірімшігін бүтін кесекпен немесе ірі кубиктермен салыңыз.', 'Зәйтүн майын құйып, орегано себіп беріңіз.']],
  'Green Goddess Salad': [['Очень мелко нарежьте капусту, огурец и зелёный лук — чем мельче, тем удобнее есть ложкой.', 'Взбейте в блендере шпинат, базилик, грецкие орехи, лимонный сок, оливковое масло и 3 столовые ложки воды в густую зелёную заправку.', 'Залейте нарезанные овощи заправкой и хорошо перемешайте.', 'Ешьте ложкой или зачерпывайте крекерами или чипсами из питы.'], ['Қырыққабатты, қиярды және көк пиязды өте ұсақ тураңыз — неғұрлым ұсақ болса, қасықпен жеу соғұрлым ыңғайлы.', 'Шпинатты, райханды, грек жаңғағын, лимон шырынын, зәйтүн майын және 3 ас қасық суды блендерде қою жасыл тұздыққа айналдырыңыз.', 'Туралған көкөністерге тұздықты құйып, жақсылап араластырыңыз.', 'Қасықпен жеңіз немесе крекермен не пита чипсымен алып жеңіз.']],
  'Grilled Cheese Sandwich': [['Намажьте сливочным маслом наружную сторону ломтиков хлеба.', 'Положите сыр между двумя ломтиками.', 'Жарьте на среднем огне по 3 минуты с каждой стороны до золотистого цвета и расплавленного сыра.'], ['Нан тілімдерінің сыртына сары май жағыңыз.', 'Ірімшікті екі тілімнің арасына салыңыз.', 'Орташа отта әр жағынан 3 минуттан алтын түсті болып, ірімшік еріп кеткенше қуырыңыз.']],
  'Herb Stem Pesto': [['Не выбрасывайте стебли зелени и увядшие листья — в них много вкуса.', 'Измельчите блендером зелень, чеснок, орехи и сыр, постепенно добавляя масло.', 'Храните в банке под слоем масла неделю или заморозьте порциями.'], ['Көк шөптің сабақтары мен солған жапырақтарын тастамаңыз — оларда дәм көп.', 'Көк шөп, сарымсақ, жаңғақ және ірімшікті блендермен езіп, май қосыңыз.', 'Банкада май қабатының астында бір апта сақтаңыз немесе порциямен қатырыңыз.']],
  'Home-Style Kuyrdak': [['Нарежьте баранину и печень мелкими кубиками, картофель — кусочками, лук — полукольцами.', 'Обжарьте баранину в глубокой сковороде с небольшим количеством масла на сильном огне 10 минут до румяной корочки.', 'Добавьте печень и жарьте ещё 5 минут, помешивая.', 'Добавьте картофель и лук, приправьте, влейте 100 мл воды, накройте крышкой и тушите 20 минут до мягкости картофеля.', 'Подавайте горячим с лепёшкой и чаем.'], ['Қой еті мен бауырды ұсақ текшелеп, картопты кесектеп, пиязды жарты шеңберлеп тураңыз.', 'Қой етін терең табада аздап майда қатты отта 10 минут қызарғанша қуырыңыз.', 'Бауырды қосып, араластыра отырып тағы 5 минут қуырыңыз.', 'Картоп пен пиязды қосып, дәмдеңіз, 100 мл су құйып, қақпақпен жауып, картоп жұмсарғанша 20 минут бұқтырыңыз.', 'Ыстық күйінде нан және шаймен беріңіз.']],
  'Homemade Beshbarmak': [['Положите мясо в большую кастрюлю с 3 литрами холодной воды, доведите до кипения, снимите пену и варите на слабом огне 2 часа. Посолите в конце.', 'Пока варится мясо, замесите крутое тесто из муки, яйца, щепотки соли и примерно 120 мл воды. Дайте ему отдохнуть 20 минут.', 'Раскатайте тесто очень тонко и нарежьте квадратами 7–8 см.', 'Выньте мясо. Налейте 300 мл бульона в небольшую кастрюлю, добавьте кольца лука и варите 5 минут.', 'Варите квадраты теста в оставшемся бульоне 3–4 минуты, выложите на большое блюдо.', 'Нарежьте мясо, положите на тесто, полейте луковым соусом. Подайте бульон (сорпа) в пиалах.'], ['Етті үлкен кастрюльге салып, 3 литр суық су құйыңыз, қайнатып, көбігін алыңыз да, баяу отта 2 сағат пісіріңіз. Соңында тұздаңыз.', 'Осы кезде ұн, жұмыртқа, бір ұстам тұз және шамамен 120 мл судан қатты қамыр илеңіз. Оны 20 минут демдеңіз.', 'Қамырды өте жұқа жайып, 7–8 см шаршылап кесіңіз.', 'Етті алыңыз. 300 мл сорпаны шағын кастрюльге құйып, пияз шеңберлерін қосып, 5 минут қайнатыңыз.', 'Қамыр шаршыларын қалған сорпада 3–4 минут пісіріп, үлкен табаққа салыңыз.', 'Етті тілімдеп, қамырдың үстіне салыңыз, пияз тұздығын құйыңыз. Сорпаны (сорпа) тостағандарға құйып беріңіз.']],
  'Homemade Hummus': [['Слейте воду с нута, оставьте немного жидкости.', 'Взбейте блендером нут, тахини, лимонный сок и чеснок до однородности.', 'Добавьте немного жидкости, чтобы разжижить, приправьте, сбрызните маслом.'], ['Ноқаттың суын сүзіп, аздап сұйықтығын қалдырыңыз.', 'Ноқат, тахини, лимон шырыны және сарымсақты біркелкі болғанша блендермен ұсақтаңыз.', 'Жұмсарту үшін аздап сұйықтық қосып, дәмдеп, май құйыңыз.']],
  'Homemade Korean Carrot Salad': [['Нарежьте морковь длинной тонкой соломкой (идеально подходит тёрка для корейской моркови), добавьте соль и сахар и помните руками.', 'Влейте уксус, добавьте раздавленный чеснок и хлопья чили.', 'Нагрейте масло с молотой кинзой пока не появится ореховый аромат и вылейте на морковь, хорошо перемешайте.', 'Оставьте в холодильнике минимум на 2 часа. Хранится неделю — любимое блюдо алматинских базаров.'], ['Сәбізді ұзын жұқа жолақтап тураңыз (джулиен үккіші өте қолайлы), тұз бен қант қосып, қолмен сығыңыз.', 'Сірке суын құйып, езілген сарымсақ пен чили ұлпаларын қосыңыз.', 'Майды ұнтақталған кинзамен жаңғақтың иісі шыққанша қыздырып, сәбізге құйыңыз, жақсылап араластырыңыз.', 'Тоңазытқышта кемінде 2 сағат қалдырыңыз. Бір апта сақталады — Алматы базарларының сүйікті тағамы.']],
  'Homemade Mac and Cheese': [['Отварите макароны и слейте воду.', 'Растопите сливочное масло, всыпьте муку и готовьте 1 минуту.', 'Медленно вмешайте молоко венчиком и готовьте до загустения.', 'Растопите в соусе тёртый сыр, перемешайте с макаронами и подавайте.'], ['Макаронды пісіріп, суын сүзіңіз.', 'Сары майды ерітіп, ұн қосып, 1 минут пісіріңіз.', 'Сүтті ақырын қосып, көрікпен араластырып, қоюланғанша пісіріңіз.', 'Үккіштен өткізілген ірімшікті ерітіп, макаронмен араластырып беріңіз.']],
  'Homemade Naryn': [['Залейте мясо холодной водой, доведите до кипения, снимите пену и варите 1 ч 30 мин, посолив.', 'Выньте мясо, сварите лапшу в небольшом количестве бульона до мягкости, 8–10 минут.', 'Нарежьте лук тонкими кольцами и залейте 2–3 половниками горячего бульона с чёрным перцем.', 'Нарежьте мясо тонкими полосками, смешайте с лапшой и луком. Остальной бульон (сорпа) подайте в пиалах.'], ['Етті суық сумен құйып, қайнатыңыз, көбігін алып, тұздап, 1 сағат 30 минут пісіріңіз.', 'Етті алып, кеспені аздаған сорпада жұмсарғанша, 8–10 минут пісіріңіз.', 'Пиязды жұқа шеңберлеп турап, үстіне қара бұрышпен 2–3 ожау ыстық сорпа құйыңыз.', 'Етті жұқа жолақтап кесіп, кеспе және пиязбен араластырыңыз. Қалған сорпаны (сорпа) тостағандарға құйып беріңіз.']],
  'Hot Honey Halloumi Toast': [['Нарежьте халуми толщиной 1 см и промокните салфеткой.', 'Обжарьте на сухой сковороде по 2 минуты с каждой стороны до золотистого цвета. Поджарьте хлеб — слегка чёрствый хлеб на закваске идеален.', 'Выложите на тост руколу, сверху халуми и полейте острым мёдом с каплей лимона.'], ['Халумиді 1 см қалыңдықта кесіп, сүлгімен құрғатыңыз.', 'Құрғақ табада әр жағынан 2 минуттан алтын түске боялғанша қуырыңыз. Нанды қуырыңыз — сәл ескі ашытқылы нан өте жақсы.', 'Тостың үстіне руккола үйіп, халуми салып, ащы бал және бір тамшы лимон шырынын құйыңыз.']],
  'Jerk Chicken Thighs': [['Натрите куриные бёдра приправой джерк, соком лайма, мёдом и маслом; оставьте на 10 минут (или на ночь в холодильнике).', 'Сварите рис в подсоленной воде.', 'Запекайте курицу при 220 °C 25 минут, пока кожа не станет хрустящей и подрумяненной по краям.', 'Дайте отдохнуть 5 минут, посыпьте нарезанным зелёным луком и подавайте с рисом.'], ['Тауық сандарын джерк дәмдеуішімен, лайм шырынымен, балмен және маймен ысқылаңыз; 10 минутқа (немесе түнге тоңазытқышқа) қалдырыңыз.', 'Күрішті тұздалған суда пісіріңіз.', 'Тауықты 220 °C-та 25 минут пісіріңіз, терісі қытырлақ болып, шеттері қызарсын.', '5 минут демалдырып, туралған көк пиязбен себіп, күрішпен бірге беріңіз.']],
  'Katyk Kozhe with Millet': [['Промойте пшено. Варите говядину в 1,2 л подсоленной воды 25 минут, затем выньте и нарежьте кубиками.', 'Добавьте пшено в бульон и варите 12–15 минут до мягкости. Дайте остыть до тёплого состояния.', 'Добавьте катык и раскрошенный курт (отличный способ использовать твёрдый старый курт).', 'Верните мясо, охладите и подавайте холодным в жаркий день. Хранится 2 дня в холодильнике.'], ['Тарыны шайыңыз. Сиыр етін 1,2 л тұздалған суда 25 минут пісіріп, алып, текшелеп тураңыз.', 'Тарыны сорпаға салып, жұмсарғанша 12–15 минут пісіріңіз. Жылы болғанша суытыңыз.', 'Қатық пен уатылған құртты (қатып қалған ескі құртты пайдаланудың тамаша тәсілі) қосып араластырыңыз.', 'Етті қайта салып, салқындатыңыз да, ыстық күні суық күйінде беріңіз. Тоңазытқышта 2 күн сақталады.']],
  'Kefir Pancakes (Oladyi)': [['Кислый или старый кефир — то, что нужно: оладьи будут пышнее.', 'Смешайте кефир, яйцо, сахар, щепотку соли и соду. Добавьте муку, чтобы получилось густое тесто.', 'Выкладывайте ложкой небольшие оладьи на горячую смазанную маслом сковороду.', 'Жарьте по 2 минуты с каждой стороны до золотистого цвета. Подавайте с вареньем или сметаной.'], ['Ашыған немесе ескі кефир өте жарайды — ол оладьиді үлпілдек етеді.', 'Кефир, жұмыртқа, қант, бір шымшым тұз және содамен араластырыңыз. Қою қамыр болуы үшін ұн қосыңыз.', 'Қызған, майланған табаға қасықпен шағын оладьи салыңыз.', 'Әр жағынан 2 минуттан алтын түсті болғанша қуырыңыз. Тосаппен немесе қаймақпен беріңіз.']],
  'Kystyby with Leftover Mash': [['Замесите мягкое тесто из тёплого молока, муки и щепотки соли; дайте ему отдохнуть 15 минут под полотенцем.', 'Используйте остатки картофельного пюре или сварите и разомните картофель; добавьте лук, обжаренный в небольшом количестве масла.', 'Раскатайте тесто в тонкие лепёшки и выпекайте каждую на сухой горячей сковороде примерно по 1 минуте с каждой стороны.', 'Намажьте пюре на половину каждой горячей лепёшки, сложите пополам и смажьте растопленным маслом.'], ['Жылы сүт, ұн және бір ұстам тұздан жұмсақ қамыр илеңіз; сүлгінің астында 15 минут демдеңіз.', 'Қалған картоп езбесін пайдаланыңыз немесе картопты пісіріп езіңіз; аздап майда қуырылған пиязды қосып араластырыңыз.', 'Қамырды жұқа дөңгелектеп жайып, әрқайсысын құрғақ қызған табада әр жағынан шамамен 1 минуттан пісіріңіз.', 'Әр ыстық нан жартысына езбені жағып, қайырып, еріген сары маймен жағыңыз.']],
  'Labneh Brunch Bowl': [['Выложите лабне в широкую миску ложкой, делая завитки.', 'Нарежьте помидоры и огурец, посолите и выложите горкой сверху.', 'Полейте оливковым маслом и щедро посыпьте затаром.', 'Подогрейте питу и зачерпывайте! Чёрствая пита? Обжарьте её кусочками с маслом до хрустящих чипсов для миски.'], ['Лабнені кең табаққа қасықпен жайып, бұрымдар жасаңыз.', 'Қызанақ пен қиярды турап, тұздап, үстіне үйіп салыңыз.', 'Зәйтүн майын тамызып, үстіне заатарды мол себіңіз.', 'Питаны жылытып, алып жеңіз! Питаңыз ескірді ме? Оны майда бөліктеп қуырып, табаққа арналған қытырлақ чипс жасаңыз.']],
  'Leftover Chicken Noodle Soup': [['Используйте варёную курицу со вчерашнего дня или сырое филе, которое нужно приготовить сегодня.', 'Варите курицу с лавровым листом в 1,5 л подсоленной воды 15 минут (5, если уже готовая), затем разберите на волокна.', 'Добавьте нарезанные кубиками морковь, лук и сельдерей — листья сельдерея и вялые стебли тоже подойдут. Варите 10 минут.', 'Добавьте лапшу и варите 5–7 минут. В конце добавьте нарезанный укроп, вместе со стеблями.'], ['Кешегі піскен тауық етін немесе бүгін пісіру керек шикі төс етін пайдаланыңыз.', 'Тауық етін лавр жапырағымен 1,5 л тұздалған суда 15 минут пісіріңіз (егер піскен болса, 5 минут), содан кейін талшықтап жыртыңыз.', 'Текшелеп туралған сәбіз, пияз және балдыркөк қосыңыз — балдыркөктің жапырақтары мен солған сабақтары да жарайды. 10 минут пісіріңіз.', 'Кеспені қосып, 5–7 минут пісіріңіз. Соңында туралған аскөкті, сабақтарымен бірге қосыңыз.']],
  'Leftover Fried Rice': [['Сварите рис (или возьмите вчерашний — холодный рис жарится лучше всего).', 'Обжарьте нарезанную кубиками морковь и горошек на горячем масле 3 минуты.', 'Отодвиньте овощи в сторону, пожарьте яйца-болтунью на той же сковороде.', 'Добавьте рис и соевый соус, обжаривайте на сильном огне 3–4 минуты, постоянно помешивая.'], ['Күріш пісіріңіз (немесе кешегісін алыңыз — салқын күріш жақсы қуырылады).', 'Кубиктеп туралған сәбіз бен асбұршақты қызған майда 3 минут қуырыңыз.', 'Көкөністерді шетке ысырып, сол табада жұмыртқаны бұзып қуырыңыз.', 'Күріш пен соя тұздығын қосып, қатты отта 3–4 минут үнемі араластырып қуырыңыз.']],
  'Leftover Fruit Kompot': [['Нарежьте мягкие или ушибленные яблоки и груши кусочками — кожуру и сердцевину тоже можно добавить.', 'Положите фрукты и курагу в 2 л воды, добавьте сахар и доведите до кипения.', 'Варите 10 минут, выключите огонь и оставьте под крышкой до остывания.', 'Процедите в кувшин и храните в холодильнике до 3 дней. Мягкие фрукты можно съесть с йогуртом.'], ['Жұмсақ немесе соғылған алма мен алмұртты кесектеп тураңыз — қабығы мен өзегін де салуға болады.', 'Жеміс пен курагаларды 2 л суға салып, қант қосып, қайнатыңыз.', '10 минут қайнатып, отты өшіріңіз де, суығанша қақпақтың астында қалдырыңыз.', 'Құманға сүзіп құйып, тоңазытқышта 3 күнге дейін сақтаңыз. Жұмсақ жемістерді йогуртпен жеуге болады.']],
  'Leftover Pasta Frittata': [['Остались варёные макароны? Отлично.', 'Взбейте яйца с молоком и тёртым сыром, добавьте макароны.', 'Готовьте на смазанной маслом сковороде на слабом огне 8 минут, переверните или подрумяньте верх под грилем.'], ['Піскен макарон қалды ма? Тамаша.', 'Жұмыртқаны сүт және үгілген ірімшікпен көпіршіте шайқап, макарон қосыңыз.', 'Майланған табада баяу отта 8 минут пісіріңіз, аударыңыз немесе үстін грильде қызартыңыз.']],
  'Leftover Plov Fried Rice': [['Возьмите вчерашний плов прямо из холодильника: холодный рис лучше всего жарится и не слипается.', 'Натрите морковь и обжарьте на ложке масла на сильном огне 2 минуты.', 'Добавьте плов, разбейте комки и жарьте 4–5 минут, пока рис не затрещит.', 'Сдвиньте рис в сторону, приготовьте в освободившемся месте яичницу-болтунью, затем перемешайте всё с соевым соусом. Подавайте горячим.'], ['Кешегі палауды тоңазытқыштан тікелей алыңыз: суық күріш жақсы қуырылады және жабыспайды.', 'Сәбізді үккіштен өткізіп, бір қасық майда қатты отта 2 минут қуырыңыз.', 'Палауды қосып, кесектерін майдалап, күріш сытырлағанша 4–5 минут қуырыңыз.', 'Күрішті шетке ысырып, босаған жерде жұмыртқаны шайқап қуырыңыз да, соя тұздығымен бәрін араластырыңыз. Ыстық күйінде беріңіз.']],
  'Leftover Rice Tuna Bowl': [['Возьмите вчерашний варёный рис — холодный рис здесь идеален. Прогрейте его 1 минуту в накрытой миске с ложкой воды.', 'Смешайте тунец без жидкости с майонезом, шрирачей и половиной соевого соуса.', 'Выложите на рис тунец, ломтики авокадо и зелёный лук, полейте остатком соевого соуса.', 'Нарежьте нори квадратиками и заворачивайте каждую порцию в маленький листик нори.'], ['Кешегі пісірілген күрішті алыңыз — салқын қалған күріш мұнда тамаша. Оны бір қасық су қосып, жабулы тостағанда 1 минут жылытыңыз.', 'Сұйықтығын төгілген тунецті майонезбен, шрирачамен және соя тұздығының жартысымен араластырыңыз.', 'Күріштің үстіне тунецті, авокадо тілімдерін және жасыл пиязды салып, қалған соя тұздығын құйыңыз.', 'Нориді шаршылап кесіп, әр асамды кішкентай нори парағына орап жеңіз.']],
  'Leftover Veggie Stir-Fry': [['Нарежьте и стебли брокколи — они сладкие и хрустящие!', 'Обжаривайте все овощи на сильном огне 5 минут, постоянно помешивая.', 'Добавьте чеснок и соевый соус, перемешивайте 1 минуту.', 'Подавайте с рисом (вчерашний рис подойдёт идеально).'], ['Брокколидің сабақтарын да тілімдеңіз — олар тәтті әрі қытырлақ!', 'Барлық көкөністі қатты отта 5 минут үнемі араластыра қуырыңыз.', 'Сарымсақ пен соя тұздығын қосып, 1 минут араластырыңыз.', 'Күрішпен беріңіз (кешегі күріш өте жақсы жарайды).']],
  'Leftover Zharkoe Pot Roast': [['Отлично подходит для мягкого проросшего картофеля и последней моркови из ящика: очистите, нарежьте крупными кусками.', 'Нарежьте говядину кубиками по 3 см и обжарьте в горячем масле в казане 5–7 минут.', 'Добавьте нарезанные лук и морковь, жарьте 5 минут, добавьте томатную пасту.', 'Добавьте картофель, лавровый лист, перец, соль и воду так, чтобы она наполовину покрывала продукты. Тушите под крышкой 40 минут до мягкости.', 'Остатки на следующий день ещё вкуснее — разогрейте с небольшим количеством воды.'], ['Жұмсақ, өскін жіберген картоп пен жәшіктегі соңғы сәбізге тамаша: аршып, ірі кесектеп тураңыз.', 'Сиыр етін 3 см текшелеп кесіп, қазанда қызған майда 5–7 минут қуырыңыз.', 'Тілімдеген пияз бен сәбізді қосып, 5 минут қуырыңыз, томат пастасын қосыңыз.', 'Картоп, лавр жапырағы, бұрыш, тұз және жарты көлемін жабатындай су қосыңыз. Қақпағын жауып, жұмсарғанша 40 минут бұқтырыңыз.', 'Қалдығы келесі күні одан да дәмді — аздап су қосып жылытыңыз.']],
  'Leftover-Veg Masoor Khichdi': [['Промойте дал и рис вместе, пока вода не станет прозрачной.', 'Разогрейте гхи в кастрюле, обжарьте кумин 30 секунд, затем добавьте куркуму и нарезанную кубиками морковь — или любые залежавшиеся овощи из холодильника.', 'Добавьте дал и рис, 900 мл воды и щепотку соли. Варите 18–20 минут, иногда помешивая, до мягкой консистенции каши.', 'За 2 минуты до конца вмешайте шпинат (подвядшие листья подойдут идеально). Если стало слишком густо — добавьте немного воды.'], ['Дал мен күрішті су мөлдірленгенше бірге жуыңыз.', 'Кастрөлде гхиді қыздырып, зираны 30 секунд қуырыңыз, содан кейін куркума мен текшеленген сәбізді — немесе тоңазытқыштағы кез келген көкөніс қалдығын қосыңыз.', 'Дал мен күрішті, 900 мл су мен бір шымшым тұзды қосыңыз. Анда-санда араластырып, ботқадай жұмсарғанша 18–20 минут қайнатыңыз.', 'Соңғы 2 минутта шпинатты қосыңыз (солған жапырақтар өте жарайды). Тым қоюланып кетсе, аздап су қосыңыз.']],
  'Lentil Bolognese': [['Обжарьте лук, морковь и чеснок до мягкости.', 'Добавьте чечевицу, помидоры и 400 мл воды, тушите 25 минут.', 'Отварите спагетти и подавайте с соусом.'], ['Пияз, сәбіз және сарымсақты жұмсарғанша қуырыңыз.', 'Жасымық, қызанақ және 400 мл су қосып, 25 минут бұқтырыңыз.', 'Спагетти пісіріп, тұздықпен беріңіз.']],
  'Little Gem Caesar with Stale-Bread Croutons': [['Порвите чёрствый хлеб на кусочки, перемешайте с оливковым маслом и запекайте при 200 °C 8–10 минут до золотистого цвета.', 'Разомните анчоусы с тёртым чесноком, затем вмешайте майонез, лимонный сок и половину тёртого пармезана.', 'Разрежьте салат Литл Джем вдоль на четвертинки и полейте листья заправкой.', 'Посыпьте сухариками и оставшимся пармезаном.'], ['Ескі нанды бөліктерге бөліп, зәйтүн майымен араластырып, 200 °C-та 8–10 минут алтын түске дейін пісіріңіз.', 'Анчоусты үгітілген сарымсақпен езіп, майонез, лимон шырыны және үгітілген пармезанның жартысын қосып, араластырыңыз.', 'Литл Джем салатын ұзынынан төрт бөлікке бөліп, жапырақтарға тұздықты құйыңыз.', 'Үстіне кептірме нан мен қалған пармезанды себіңіз.']],
  'Mapo Tofu': [['Сварите рис. Нарежьте тофу кубиками по 2 см и замочите на 5 минут в горячей подсоленной воде.', 'Обжарьте сычуаньский перец на сухой сковороде и измельчите.', 'Обжарьте фарш на небольшом количестве масла до хруста, добавьте чеснок, имбирь и доубаньцзян, жарьте 1 минуту.', 'Влейте 200 мл воды, аккуратно выложите обсушенный тофу и тушите 4 минуты.', 'Загустите крахмалом, разведённым в 2 ст. л. воды, посыпьте перцем и зелёным луком, подавайте с рисом.'], ['Күрішті пісіріңіз. Тофуды 2 см текшелеп туралап, ыстық тұзды суға 5 минутқа салып қойыңыз.', 'Сычуань бұрышын құрғақ табада қуырып, ұнтақтаңыз.', 'Тартылған етті аз майда қытырлақ болғанша қуырыңыз, сарымсақ, зімбір және доубаньцзян қосып, 1 минут қуырыңыз.', '200 мл су құйып, суы сарқылған тофуды ақырын салыңыз да, 4 минут бұқтырыңыз.', '2 ас қасық суға араластырылған крахмалмен қоюлатыңыз, бұрыш пен көк пияз себіп, күрішпен ұсыныңыз.']],
  'Marry Me Chicken': [['Приправьте курицу солью и перцем, обжарьте в оливковом масле по 5 минут с каждой стороны, выньте.', 'На той же сковороде обжарьте чеснок и нарезанные вяленые помидоры 1 минуту.', 'Влейте сливки и добавьте тёртый пармезан, варите 3 минуты до небольшого загустения.', 'Добавьте шпинат, верните курицу и тушите 8–10 минут до готовности. Отлично с рисом или пастой.'], ['Тауық етін тұз және бұрышпен дәмдеп, зәйтүн майында әр жағынан 5 минуттан қуырып, алып қойыңыз.', 'Сол табада сарымсақ пен туралған кептірілген қызанақты 1 минут қуырыңыз.', 'Кілегей құйып, үгілген пармезан қосып, сәл қоюланғанша 3 минут пісіріңіз.', 'Шпинатты қосып, тауық етін қайта салыңыз да, піскенше 8–10 минут бұқтырыңыз. Күріш немесе пастамен өте жақсы.']],
  'Mashed Potatoes with Chicken': [['Очистите и нарежьте картофель, варите в подсоленной воде 15–20 минут до мягкости.', 'Нарежьте курицу, посолите, поперчите и обжаривайте на сковороде 6–8 минут до золотистого цвета.', 'Слейте воду с картофеля, разомните его с тёплым молоком и маслом до кремообразной консистенции.', 'Выложите курицу поверх пюре.'], ['Картопты аршып, турап, тұздалған суда 15–20 минут жұмсарғанша қайнатыңыз.', 'Тауық етін тілімдеп, дәмдеуіш қосып, табада 6–8 минут қызарғанша қуырыңыз.', 'Картоптың суын сүзіп, жылы сүт пен майды қосып, кремге ұқсас болғанша езіңіз.', 'Тауық етін езбенің үстіне салып беріңіз.']],
  'Mentaiko Spaghetti': [['Отварите спагетти в подсоленной воде до аль денте и оставьте чашку воды от пасты.', 'Надрежьте оболочку ментайко и выскребите икру в большую миску; смешайте с мягким сливочным маслом, сливками и соевым соусом.', 'Перемешайте горячие спагетти в миске с небольшим количеством воды от пасты, пока соус не станет глянцевым и розовым — тепло мягко прогреет икру.', 'Посыпьте тонкими полосками нори и сразу ешьте.'], ['Спагеттиді тұзды суда аль денте күйіне дейін қайнатып, бір кесе судын қалдырыңыз.', 'Ментайко қабығын тіліп, уылдырықты үлкен ыдысқа сыпырып алыңыз; жұмсақ сары май, кілегей және соя тұздығымен араластырыңыз.', 'Ыстық спагеттиді ыдыста аздаған макарон суымен жылтыр әрі қызғылт болғанша араластырыңыз — жылу уылдырықты ақырын жылытады.', 'Үстіне жұқа нори жолақтарын себіп, бірден жеңіз.']],
  'Muhammara': [['Подсушите грецкие орехи на сухой сковороде 3–4 минуты до аромата.', 'Порвите чёрствый хлеб на кусочки — для этой пасты сухой хлеб как раз то, что нужно.', 'Пробейте перец, орехи, хлеб, гранатовую патоку, лимонный сок, кумин и урфа бибер в густую, слегка зернистую пасту.', 'Посолите, полейте оливковым маслом и подавайте с хлебом или овощами; в холодильнике хранится 5 дней.'], ['Грек жаңғағын құрғақ табада 3–4 минут хош иісі шыққанша қуырыңыз.', 'Қатып қалған нанды бөліктерге бөліңіз — бұл тағамға құрғақ нан дәл керек.', 'Бұрышты, жаңғақты, нанды, анар сірнесін, лимон шырынын, зиреді және урфа биберді қою, сәл түйіршікті пастаға айналдырыңыз.', 'Тұздап, зәйтүн майын құйып, нанмен немесе көкөністермен беріңіз; тоңазытқышта 5 күн сақталады.']],
  'Mushroom Risotto': [['Обжарьте нарезанные грибы в половине сливочного масла и отложите.', 'Размягчите лук, добавьте рис и подсушите 2 минуты. Влейте вино.', 'Добавляйте горячую воду или бульон по одному половнику, помешивая, 18–20 минут.', 'Вмешайте грибы, оставшееся сливочное масло и пармезан.'], ['Тілімделген саңырауқұлақты сары майдың жартысында қуырып, бөлек қойыңыз.', 'Пиязды жұмсартып, күріш қосып, 2 минут қуырыңыз. Шарап құйыңыз.', 'Ыстық су немесе сорпаны бір ожаудан қосып, араластырып, 18–20 минут пісіріңіз.', 'Саңырауқұлақ, қалған сары май және пармезанды қосып араластырыңыз.']],
  'Nduja Burrata Rigatoni': [['Отварите ригатони в хорошо подсоленной кипящей воде на 1 минуту меньше, чем указано на упаковке; оставьте 100 мл воды от пасты.', 'Разогрейте оливковое масло в широкой сковороде, добавьте нарезанный чеснок и ндую и помешивайте, пока она не растопится в красное масло.', 'Добавьте разрезанные пополам черри и готовьте 5 минут, раздавливая часть помидоров, чтобы получился соус.', 'Переложите пасту в сковороду, добавьте немного воды от пасты и перемешайте, пока соус не станет глянцевым и не обволочёт её.', 'Разложите по тарелкам, сверху порвите буррату руками и украсьте свежим базиликом.'], ['Ригатониді жақсылап тұздалған қайнаған суда қаптамада көрсетілгеннен 1 минут аз пісіріңіз; паста суынан 100 мл қалдырыңыз.', 'Кең табада зәйтүн майын қыздырып, туралған сарымсақ пен ндуяны қосыңыз да, ол қызыл майға айналып ерігенше араластырыңыз.', 'Екіге бөлінген черри қызанақтарын қосып, 5 минут пісіріңіз, тұздық шығуы үшін бір бөлігін езіңіз.', 'Пастаны табаға салып, аздап паста суын қосыңыз да, тұздық жылтырап, пастаны толық қаптағанша араластырыңыз.', 'Тарелкаларға салып, үстіне бурратаны қолмен бөліп қойыңыз және жаңа райханмен безендіріңіз.']],
  'Okroshka': [['Отварите и остудите картофель и яйца.', 'Нарежьте кубиками картофель, яйца, огурец, редис и колбасу.', 'Порубите укроп, смешайте всё и залейте холодным кефиром.', 'Приправьте и подавайте охлаждённой — идеально для жарких дней.'], ['Картоп пен жұмыртқаны қайнатып, салқындатыңыз.', 'Картоп, жұмыртқа, қияр, шалғам және шұжықты кубиктеп тураңыз.', 'Аскөкті ұсақтап турап, бәрін араластырып, суық кефир құйыңыз.', 'Дәмдеп, салқындатып беріңіз — ыстық күндерге тамаша.']],
  'Olivier Salad': [['Отварите картофель и морковь в кожуре 25 минут, яйца сварите вкрутую 10 минут.', 'Остудите всё, затем очистите и нарежьте одинаковыми мелкими кубиками.', 'Нарежьте кубиками колбасу и маринованные огурцы, добавьте горошек.', 'Заправьте майонезом, приправьте и охладите 30 минут перед подачей.'], ['Картоп пен сәбізді қабығымен 25 минут, жұмыртқаны 10 минут қатты етіп қайнатыңыз.', 'Бәрін салқындатып, содан кейін аршып, бірдей ұсақ кубиктерге тураңыз.', 'Шұжық пен тұздалған қиярды кубиктеп турап, асбұршақ қосыңыз.', 'Майонезбен араластырып, дәмдеп, берер алдында 30 минут салқындатыңыз.']],
  'One-Pot Dimlama': [['Нарежьте баранину кусками и обжарьте в толстостенной кастрюле с небольшим количеством масла, приправьте солью и зирой.', 'Сверху, не перемешивая, выложите слоями: кольца лука, морковь, картофель, перец, помидор, чеснок, солите каждый слой.', 'Накройте всё большими капустными листьями, плотно закройте крышку — овощи готовятся на пару в собственном соку.', 'Готовьте на самом слабом огне 1 час 15 минут. Отлично подходит, чтобы использовать залежавшиеся овощи.'], ['Қой етін кесектеп, қалың қабырғалы қазанда аздап майда қызартып, тұз және зирамен дәмдеңіз.', 'Үстіне араластырмай қабаттап салыңыз: пияз шеңберлері, сәбіз, картоп, бұрыш, қызанақ, сарымсақ, әр қабатты тұздаңыз.', 'Барлығын ірі орамжапырақ жапырақтарымен жауып, қақпағын тығыз жабыңыз — көкөністер өз шырынында будың күшімен піседі.', 'Ең баяу отта 1 сағат 15 минут пісіріңіз. Солып қалған көкөністерді пайдалануға тамаша.']],
  'Orecchiette with Broccoli Rabe': [['Обрежьте у рапини только сухие концы, остальное нарежьте — стебли, листья и соцветия идут в дело.', 'Отварите орекьетте в подсоленной воде; за 4 минуты до готовности добавьте рапини, затем слейте, оставив немного воды.', 'Прогрейте оливковое масло с нарезанным чесноком, анчоусами и хлопьями чили, пока анчоусы не растают.', 'Добавьте пасту и зелень с небольшим количеством воды от варки и посыпьте тёртым пармезаном.'], ['Рапинидің тек құрғақ ұштарын кесіп, қалғанын туралаңыз — сабағы, жапырағы мен гүлшоғыры түгел пайдаланылады.', 'Орекьеттені тұзды суда қайнатыңыз; дайын болуына 4 минут қалғанда рапиниді қосыңыз, сосын аздап су қалдырып, сүзіңіз.', 'Зәйтүн майын туралған сарымсақ, анчоус және чили үгінділерімен анчоус еріп кеткенше қыздырыңыз.', 'Макарон мен көкті аздаған қайнатқан сумен қосып, үгітілген пармезан себіңіз.']],
  'Overnight Oats': [['Смешайте овсяные хлопья, молоко, йогурт и мёд в банке.', 'Закройте и оставьте в холодильнике на ночь.', 'Утром украсьте нарезанным бананом.'], ['Құмырада сұлы жармасын, сүтті, йогурт пен балды араластырыңыз.', 'Жауып, түнге тоңазытқышқа қойыңыз.', 'Таңертең тілімделген бананмен безендіріңіз.']],
  'Overripe Banana Baked Oats': [['Разогрейте духовку до 190 °C. Разомните бананы — чем больше коричневых пятнышек, тем слаще.', 'Вмешайте молоко и яйцо, затем овсяные хлопья, разрыхлитель и корицу.', 'Вылейте в небольшую форму, сверху разложите чернику (подойдёт мягкая или замороженная).', 'Запекайте 22–25 минут, пока не схватится и не зарумянится. Полейте кленовым сиропом — вкусно и тёплым, и холодным на следующий день.'], ['Пешті 190 °C-қа дейін қыздырыңыз. Бананды езіңіз — қоңыр дақтары көп болған сайын тәттірек.', 'Сүт пен жұмыртқаны қосып араластырыңыз, содан кейін сұлы жармасын, қопсытқыш пен даршынды қосыңыз.', 'Шағын пісіру ыдысына құйып, үстіне қаражидек салыңыз (жұмсарған не мұздатылғаны да жарайды).', 'Қатайып, қызарғанша 22–25 минут пісіріңіз. Үстіне үйеңкі шәрбатын құйыңыз — жылы күйінде де, ертесіне салқын күйінде де дәмді.']],
  'Overripe Banana Bread': [['Разогрейте духовку до 180 °C. Чем темнее бананы, тем слаще хлеб!', 'Разомните бананы вилкой, добавьте растопленное сливочное масло, сахар и яйца.', 'Добавьте муку со щепоткой соли и разрыхлителем (содой), перемешайте только до однородности.', 'Вылейте в форму для хлеба, выстеленную бумагой, и выпекайте 55–60 минут, пока зубочистка не будет выходить сухой.'], ['Пешті 180 °C-қа дейін қыздырыңыз. Бананның түсі қаралаған сайын, нан тәттірек болады!', 'Бананды шанышқымен езіп, ерітілген сары май, қант және жұмыртқа қосып араластырыңыз.', 'Бір шымшым тұз және сода қосылған ұнды қосып, тек біркелкі болғанша ғана араластырыңыз.', 'Қағаз төселген пішінге құйып, тіс шұқығыш таза шыққанша 55–60 минут пісіріңіз.']],
  'Panzanella (Stale Bread Salad)': [['Порвите чёрствый хлеб на куски — он впитывает сок, как губка.', 'Нарежьте помидоры, огурец и лук, смешайте с хлебом.', 'Заправьте маслом, солью и уксусом. Дайте постоять 10 минут, добавьте базилик.'], ['Ескі нанды үзіп бөліктеңіз — ол шырынды губка сияқты сіңіреді.', 'Қызанақ, қияр және пиязды турап, нанмен араластырыңыз.', 'Май, тұз және сірке суымен дәмдеңіз. 10 минут қойып, базилик қосыңыз.']],
  'Pasta Carbonara': [['Отварите спагетти в подсоленной воде. Оставьте стакан воды от пасты.', 'Обжарьте нарезанный кубиками бекон до хруста.', 'Взбейте яйца с тёртым пармезаном и большим количеством чёрного перца.', 'Снимите с огня, перемешайте горячую пасту с беконом и яичной смесью, добавляя воду от пасты до кремовой консистенции.'], ['Спагеттиді тұздалған суда пісіріңіз. Макарон пісірілген судың бір стақанын қалдырыңыз.', 'Кубиктеп туралған беконды қытырлақ болғанша қуырыңыз.', 'Жұмыртқаны үккіштен өткізілген пармезан және көп қара бұрышпен шайқаңыз.', 'Оттан алып, ыстық макаронды бекон және жұмыртқа қоспасымен араластырып, кремдей болғанша макарон суын қосыңыз.']],
  'Pearl Couscous Leftover-Veg Salad': [['Обжарьте птитим в небольшом количестве масла 2 минуты, затем варите 8–10 минут в подсоленной воде и откиньте.', 'Нарежьте кубиками овощи, которые ждут в холодильнике, — цукини, перец и лук подходят отлично — и обжарьте до мягкости и лёгкой корочки.', 'Смешайте тёплый птитим с овощами, раскрошенной фетой и рубленой петрушкой вместе со стеблями.', 'Заправьте оливковым маслом и лимонным соком; салат отлично хранится до обеда следующего дня.'], ['Птитимді аздап майда 2 минут қуырып, кейін тұзды суда 8–10 минут пісіріп, суын төгіңіз.', 'Тоңазытқышта жатқан көкөністерді текшелеп туралыңыз — цукини, бұрыш пен пияз өте жақсы — және жұмсарып, сәл қызарғанша қуырыңыз.', 'Жылы птитимді көкөністермен, үгітілген фетамен және сабағымен бірге туралған ақжелкенмен араластырыңыз.', 'Зәйтүн майы мен лимон шырынын қосыңыз; салат келесі күнгі түскі асқа дейін жақсы сақталады.']],
  'Pelmeni with Sour Cream': [['Вскипятите 2 литра подсоленной воды с лавровым листом.', 'Добавьте замороженные пельмени и помешайте. Варите 8–10 минут после того, как они всплывут.', 'Слейте воду, добавьте сливочное масло и подавайте со сметаной.'], ['2 литр тұздалған суды лавр жапырағымен қайнатыңыз.', 'Мұздатылған пельмендерді салып, араластырыңыз. Олар жоғары қалқып шыққаннан кейін 8–10 минут пісіріңіз.', 'Суын сүзіп, сары май қосып, қаймақпен беріңіз.']],
  'Pesto Eggs on Sourdough': [['Выложите песто на холодную антипригарную сковороду и нагрейте, пока не зашкворчит.', 'Разбейте яйца прямо в песто и жарьте 3 минуты, пока белки не схватятся, а края не станут хрустящими.', 'Поджарьте хлеб на закваске и выложите сверху ломтики авокадо.', 'Переложите яйца в песто на хлеб и посыпьте хлопьями чили.'], ['Песто-ны суық, күйіп қалмайтын табаға жағып, шыжылдағанша қыздырыңыз.', 'Жұмыртқаларды тікелей песто-ға жарып, ақуызы қатып, шеттері қытырлақ болғанша 3 минут қуырыңыз.', 'Ашытқы нанын қуырып, үстіне туралған авокадо салыңыз.', 'Песто қосылған жұмыртқаны нанның үстіне салып, чили үлпектерін себіңіз.']],
  'Pesto Pasta': [['Отварите пенне в подсоленной воде.', 'Разрежьте черри пополам.', 'Слейте воду с пасты и перемешайте с песто и помидорами.', 'Подавайте, посыпав тёртым пармезаном.'], ['Пеннені тұздалған суда пісіріңіз.', 'Черри қызанағын екіге кесіңіз.', 'Макаронның суын сүзіп, песто және қызанақпен араластырыңыз.', 'Үстіне үккіштен өткізілген пармезан себіп беріңіз.']],
  'Potato Peel Crisps': [['Чистили картофель для пюре? Оставьте чистую кожуру!', 'Перемешайте кожуру с маслом, солью и паприкой.', 'Выпекайте при 200 °C 12–15 минут до хруста. Бесплатная закуска!'], ['Езбе үшін картопты аршыдыңыз ба? Таза қабығын сақтап қойыңыз!', 'Қабығын май, тұз және паприкамен араластырыңыз.', '200 °C температурада 12–15 минут қытырлақ болғанша пісіріңіз. Тегін тіскебасар!']],
  'Pumpkin Soup': [['Обжарьте лук, морковь и имбирь 5 минут.', 'Добавьте нарезанную кубиками тыкву и воду, чтобы покрыть, варите 20 минут.', 'Взбейте блендером до однородности и вмешайте сливки.', 'Посыпьте обжаренными тыквенными семечками — не выбрасывайте их!'], ['Пияз, сәбіз және зімбірді 5 минут қуырыңыз.', 'Кубиктеп туралған асқабақ қосып, жабатындай су құйып, 20 минут пісіріңіз.', 'Біркелкі болғанша блендермен ұсақтап, сүт қаймағын қосыңыз.', 'Қуырылған асқабақ тұқымдарын себіңіз — оларды тастамаңыз!']],
  'Quesabirria Tacos': [['Удалите семена из сушёных перцев чили, замочите их в горячей воде на 15 мин, затем взбейте блендером с чипотле, помидорами, половиной лука и чесноком.', 'Обжарьте говядину крупными кусками, залейте соусом и 1 литром воды, добавьте соль, зиру и лавровый лист. Тушите под крышкой 2,5 ч, пока мясо не начнёт распадаться.', 'Разберите мясо на волокна. Снимите красный жир с бульона (консоме) в миску.', 'Обмакните каждую тортилью в красный жир, обжарьте на горячей сковороде, добавьте сыр и мясо, сложите и жарьте до хруста с обеих сторон.', 'Подавайте с горячим консоме для макания, нарезанным луком, кинзой и лаймом. Остатки бульона = лапша на следующий день!'], ['Кептірілген чили бұрыштарының дәндерін алып, ыстық суда 15 мин жібітіңіз, содан кейін чипотле, қызанақ, пиязның жартысы және сарымсақпен блендермен езіңіз.', 'Сиыр етін ірі кесектеп қызартып, тұздықпен және 1 литр сумен құйыңыз, тұз, зира және лавр жапырағын қосыңыз. Ет быт-шыт болғанша қақпағын жауып 2,5 сағат бұқтырыңыз.', 'Етті талшықтап жыртыңыз. Сорпаның (консоме) қызыл майын табаққа жинап алыңыз.', 'Әр тортильяны қызыл майға малып, қызған табада қуырыңыз, үстіне ірімшік пен ет салып, бүктеп, екі жағы қытырлақ болғанша қуырыңыз.', 'Малуға арналған ыстық консоме, туралған пияз, кинза және лаймен беріңіз. Қалған сорпа = келесі күнгі кеспе сорпа!']],
  'Rainbow Chard Frittata': [['Нарежьте стебли мангольда мелкими кусочками, а листья порубите крупно — цветные стебли здесь самое вкусное.', 'Обжарьте лук и стебли мангольда на оливковом масле 5 минут, добавьте листья и готовьте 2 минуты, пока не опадут.', 'Взбейте яйца с солью и перцем, залейте овощи и раскрошите сверху фету.', 'Готовьте на слабом огне под крышкой 10 минут, пока не схватится, затем нарежьте на кусочки.'], ['Мангольд сабақтарын ұсақ турап, жапырақтарын ірі тураңыз — түрлі түсті сабақтары ең дәмді бөлігі.', 'Пияз бен мангольд сабақтарын зәйтүн майында 5 минут қуырып, жапырақтарын қосып, солғанша 2 минут пісіріңіз.', 'Жұмыртқаны тұз бен бұрышпен шайқап, көкөністердің үстіне құйыңыз да, фетаны үгітіп салыңыз.', 'Қақпағын жауып, баяу отта қатқанша 10 минут пісіріңіз, содан кейін бөліктерге кесіңіз.']],
  'Ratatouille': [['Мягкие овощи здесь как раз кстати! Нарежьте всё кубиками примерно одного размера.', 'Обжарьте лук и чеснок, добавьте баклажан и перец, готовьте 10 минут.', 'Добавьте цукини и помидоры, тушите 25 минут.', 'Приправьте травами. На следующий день ещё вкуснее.'], ['Жұмсақ көкөністер мұнда өте қолайлы! Барлығын шамамен бірдей текшелеп тураңыз.', 'Пияз бен сарымсақты қуырып, баклажан мен бұрышты қосыңыз, 10 минут пісіріңіз.', 'Кабачок пен қызанақты қосып, 25 минут бұқтырыңыз.', 'Дәмдеуіш шөптермен дәмдеңіз. Келесі күні одан да дәмді болады.']],
  'Red Lentil Soup': [['Обжарьте лук и морковь на масле 5 минут, добавьте томатную пасту.', 'Добавьте промытую чечевицу, нарезанный кубиками картофель и 1,5 литра воды.', 'Варите 25 минут, пока всё не станет мягким.', 'Взбейте блендером до однородности и приправьте. Добавьте немного лимонного сока.'], ['Пияз бен сәбізді майда 5 минут қуырып, томат пастасын қосыңыз.', 'Жуылған жасымық, кубиктеп туралған картоп және 1,5 литр су қосыңыз.', 'Бәрі жұмсарғанша 25 минут пісіріңіз.', 'Біркелкі болғанша блендермен ұсақтап, дәмдеңіз. Аздап лимон шырынын сығыңыз.']],
  'Rescue Smoothie': [['Заморозьте бананы и ягоды, пока они не испортились, — смузи получится особенно густым.', 'Положите всё в блендер.', 'Взбивайте 1 минуту до однородности и пейте сразу.'], ['Банан мен жидектерді бүлінбей тұрып мұздатыңыз — смузи өте қою болады.', 'Бәрін блендерге салыңыз.', 'Біркелкі болғанша 1 минут араластырып, бірден ішіңіз.']],
  'Roasted Carrots with Pomegranate Molasses': [['Морковь не чистите, а хорошо помойте щёткой; толстые разрежьте вдоль пополам. Ботву, если есть, оставьте.', 'Перемешайте с оливковым маслом и солью и запекайте при 220 °C 25 минут; за 5 минут до конца полейте гранатовой патокой.', 'Распределите греческий йогурт по тарелке и выложите сверху горячую морковь.', 'Посыпьте заатаром и рубленой петрушкой (и рубленой морковной ботвой).'], ['Сәбізді аршымай, щеткамен жақсылап жуыңыз; жуандарын ұзынынан екіге бөліңіз. Жапырағы болса, қалдырыңыз.', 'Зәйтүн майы мен тұзбен араластырып, 220 °C-та 25 минут пісіріңіз; соңғы 5 минутта анар шәрбатын құйыңыз.', 'Грек йогуртын тәрелкеге жайып, үстіне ыстық сәбізді салыңыз.', 'Заатар мен туралған ақжелкен (және туралған сәбіз жапырағы) себіңіз.']],
  'Roasted Chicken Thighs with Veggies': [['Разогрейте духовку до 200 °C.', 'Нарежьте овощи кусками, перемешайте с маслом, чесноком и специями.', 'Сверху выложите курицу, хорошо приправьте.', 'Запекайте 45 минут до золотистой хрустящей корочки.'], ['Пешті 200 °C-қа дейін қыздырыңыз.', 'Көкөністерді кесектерге турап, май, сарымсақ және дәмдеуіштермен араластырыңыз.', 'Үстіне тауық етін салып, жақсылап дәмдеңіз.', 'Алтын түсті, қытырлақ болғанша 45 минут пісіріңіз.']],
  'Roasted Kabocha Squash Soup': [['Разогрейте духовку до 200 °C. Нарежьте тыкву дольками — чистить не нужно, кожура тыквы кабоча мягкая и съедобная.', 'Выньте семена и сохраните их! Запекайте дольки с маслом 30 минут до мягкости.', 'Обжарьте лук и чеснок в кастрюле, добавьте тыкву и 600 мл воды, варите 5 минут.', 'Взбейте блендером с кокосовым молоком до однородности, посолите.', 'Посыпьте обжаренными семечками. Хорошо замораживается на 3 месяца.'], ['Духовканы 200 °C-қа дейін қыздырыңыз. Асқабақты тілімдеп кесіңіз — аршудың қажеті жоқ, кабоча қабығы жұмсақ әрі жеуге жарамды.', 'Дәндерін алып, сақтап қойыңыз! Тілімдерді маймен 30 минут жұмсарғанша қуырыңыз.', 'Пияз бен сарымсақты кастрюльде қуырып, асқабақ пен 600 мл су қосып, 5 минут қайнатыңыз.', 'Кокос сүтімен біртекті болғанша блендермен езіп, тұздаңыз.', 'Үстіне қуырылған дәндерді себіңіз. 3 айға дейін жақсы қатады.']],
  'Roasted Red Pepper Pasta': [['Сварите пасту в подсоленной воде до аль денте и оставьте чашку воды от пасты.', 'Обжарьте нарезанный чеснок в оливковом масле 1 минуту, добавьте обсушенный запечённый перец и прогрейте.', 'Пробейте перец с чесноком, сливочным сыром, пармезаном и небольшим количеством воды от пасты в гладкий розовый соус.', 'Перемешайте пасту с соусом, при необходимости разбавьте водой от пасты и посыпьте рваным базиликом.'], ['Макаронды тұзды суда al dente күйіне дейін қайнатып, бір кесе суын қалдырыңыз.', 'Туралған сарымсақты зәйтүн майында 1 минут қуырып, суы сорғытылған пісірілген бұрышты қосып, жылытыңыз.', 'Бұрыш пен сарымсақты кілегейлі ірімшікпен, пармезанмен және аздап макарон суымен біртекті қызғылт тұздыққа айналдырыңыз.', 'Макаронды тұздықпен араластырыңыз, қажет болса макарон суын қосып, үстіне жұлынған райхан себіңіз.']],
  'Russian Blini': [['Взбейте яйца с сахаром и солью, добавьте половину молока.', 'Добавьте муку, взбейте до однородности, затем влейте остальное молоко и масло.', 'Вылейте тонкий слой на горячую сковороду, жарьте по 1 минуте с каждой стороны.', 'Подавайте со сметаной, вареньем или остатками начинок.'], ['Жұмыртқаны қант және тұзбен шайқап, сүттің жартысын қосыңыз.', 'Ұн қосып, біркелкі болғанша шайқаңыз, содан кейін қалған сүт пен майды қосыңыз.', 'Қызған табаға жұқа қабат құйып, әр жағынан 1 минуттан пісіріңіз.', 'Қаймақпен, тосаппен немесе қалған бастамалармен беріңіз.']],
  'Savory Bread Strata': [['Нарежьте чёрствый хлеб кубиками и выложите в смазанную форму для запекания вместе с нарезанным шпинатом.', 'Взбейте яйца с молоком, солью и перцем, залейте хлеб и прижмите. Оставьте на 10 минут пропитаться.', 'Посыпьте тёртым сыром.', 'Выпекайте при 180 °C 30 минут до пышной золотистой корочки.'], ['Ескі нанды текшелеп тураңыз да, майланған пісіру қалыбына туралған шпинатпен бірге салыңыз.', 'Жұмыртқаны сүт, тұз және бұрышпен шайқап, нанның үстіне құйып, басыңыз. 10 минут сіңуге қалдырыңыз.', 'Үгілген ірімшікпен себіңіз.', '180 °C температурада 30 минут ісіп, алтын түске боялғанша пісіріңіз.']],
  'Scrap Vegetable Broth': [['В течение недели собирайте в пакет в морозилке кожуру, кончики и стебли.', 'Залейте 2,5 литрами воды, добавьте лавровый лист и горошины перца.', 'Варите 45 минут, процедите. Используйте как основу для супов и ризотто.'], ['Апта бойы қабықтарды, ұштарын және сабақтарын мұздатқышта пакетке жинап отырыңыз.', '2,5 литр сумен құйып, лавр жапырағы мен бұрыш дәнін қосыңыз.', '45 минут қайнатып, сүзіңіз. Сорпалар мен ризотто үшін негіз ретінде пайдаланыңыз.']],
  'Shakshuka': [['Мягкие помидоры идеальны — нарежьте их вместе с перцем и луком.', 'Обжаривайте лук и перец 5 минут, добавьте помидоры и тушите 10 минут до состояния соуса.', 'Сделайте 4 небольших углубления и разбейте в каждое по яйцу.', 'Накройте крышкой и готовьте 5–6 минут, пока белки не схватятся.'], ['Жұмсақ қызанақтар өте жақсы — оларды бұрыш және пиязбен бірге турап алыңыз.', 'Пияз бен бұрышты 5 минут қуырып, қызанақ қосып, тұздық болғанша 10 минут бұқтырыңыз.', '4 кішкентай ойық жасап, әрқайсысына бір жұмыртқадан шартылдатып салыңыз.', 'Қақпақпен жауып, ақуызы қатқанша 5–6 минут пісіріңіз.']],
  'Shalgam Turnip Salad': [['Нарежьте репу, морковь и перец тонкой соломкой, лук — полукольцами.', 'Добавьте соль и сахар, помните руками, пока овощи не пустят сок.', 'Добавьте уксус и раздавленный чеснок. Нагрейте масло до горячего состояния и вылейте на салат.', 'Перемешайте и охладите минимум 1 час. Хранится 4 дня — классический гарнир алматинских базаров.'], ['Шалғам, сәбіз және бұрышты жұқа жолақтап, пиязды жарты шеңберлеп тураңыз.', 'Тұз бен қант қосып, көкөністер шырын бергенше қолмен сығыңыз.', 'Сірке суы мен езілген сарымсақ қосыңыз. Майды қыздырып, салаттың үстіне құйыңыз.', 'Араластырып, кемінде 1 сағат салқындатыңыз. 4 күн сақталады — Алматы базарларының классикалық гарнир.']],
  'Shchi (Cabbage Soup)': [['Варите говядину в 2,5 литрах воды на слабом огне 1 час.', 'Добавьте нашинкованную капусту и нарезанный кубиками картофель, варите 15 минут.', 'Обжарьте лук и морковь с томатной пастой, добавьте в суп.', 'Варите ещё 10 минут, приправьте и подавайте со сметаной.'], ['Сиыр етін 2,5 литр суда баяу отта 1 сағат пісіріңіз.', 'Туралған қырыққабат пен кубиктеп туралған картопты қосып, 15 минут пісіріңіз.', 'Пияз бен сәбізді томат пастасымен қуырып, сорпаға қосыңыз.', 'Тағы 10 минут пісіріп, дәмдеп, қаймақпен беріңіз.']],
  'Sheet-Pan Andouille Shrimp Bake': [['Разогрейте духовку до 220 °C. Нарежьте картофель небольшими кусочками, кукурузу — кружками; запекайте на противне с половиной сливочного масла 15 минут.', 'Нарежьте колбасу андуй. Растопите оставшееся масло с тёртым чесноком и копчёной паприкой.', 'Добавьте на противень колбасу и креветки, полейте чесночным маслом, перемешайте и запекайте ещё 8–10 минут, пока креветки не порозовеют.', 'Сбрызните лимонным соком и подавайте прямо на противне.'], ['Пешті 220 °C-қа дейін қыздырыңыз. Картопты кішкене бөліктерге, жүгеріні дөңгелектеп тураңыз; табада сары майдың жартысымен 15 минут пісіріңіз.', 'Андуй шұжығын тураңыз. Қалған майды үгітілген сарымсақ және ысталған паприкамен ерітіңіз.', 'Табаға шұжық пен асшаянды қосып, сарымсақ майын құйыңыз да, араластырып, асшаян қызғылт түске енгенше тағы 8–10 минут пісіріңіз.', 'Үстіне лимон шырынын сығып, табадан тікелей ұсыныңыз.']],
  'Sheet-Pan Chickpea Shawarma Bowl': [['Разогрейте духовку до 220 °C. Слейте и обсушите нут, разберите цветную капусту на мелкие соцветия — кочерыжку и листья тоже нарежьте, они отлично запекаются.', 'Перемешайте всё с оливковым маслом, зирой, копчёной паприкой и солью, разложите на противне и запекайте 25 минут до хрустящих краёв.', 'Вмешайте в йогурт тёртый чеснок и сок лимона; нарежьте огурец кубиками.', 'Прогрейте питу, выложите нут и капусту, добавьте огурец и полейте чесночным йогуртом.'], ['Пешті 220 °C-қа дейін қыздырыңыз. Ноқаттың суын төгіп, кептіріңіз, түрлі түсті қырыққабатты ұсақ гүлшоғырларға бөліңіз — сабағы мен жапырақтарын да тураңыз, олар да тамаша піседі.', 'Барлығын зәйтүн майымен, зирамен, ысталған паприкамен және тұзбен араластырып, табаға жайып, жиектері қытырлақ болғанша 25 минут пісіріңіз.', 'Йогуртқа үгілген сарымсақ пен лимон шырынын қосыңыз; қиярды текшелеп тураңыз.', 'Питаны жылытып, үстіне ноқат пен қырыққабатты салыңыз, қияр қосып, сарымсақты йогурт құйыңыз.']],
  'Sheet-Pan Crispy Gnocchi': [['Разогрейте духовку до 220 °C. Нарежьте помидоры, перец и лук кусочками на один укус — мягкие помидоры и сморщенный перец здесь идеальны.', 'Перемешайте ньокки прямо из упаковки с овощами, оливковым маслом и солью на противне.', 'Запекайте 20 минут, один раз перемешав, пока ньокки не станут золотистыми и хрустящими.', 'Порвите моцареллу сверху и запекайте ещё 3 минуты, пока она не расплавится.'], ['Пешті 220 °C-қа дейін қыздырыңыз. Қызанақты, бұрышты және пиязды бір тістеуге болатын бөліктерге тураңыз — жұмсарған қызанақ пен бүріскен бұрыш мұнда өте жақсы.', 'Ньоккиді қаптамадан бірден көкөністермен, зәйтүн майымен және тұзбен бірге табаға салып араластырыңыз.', 'Бір рет араластырып, ньокки алтын түсті әрі қытырлақ болғанша 20 минут пісіріңіз.', 'Үстіне моцарелланы жыртып салып, ерігенше тағы 3 минут пісіріңіз.']],
  'Shirataki Leftover-Veg Stir-Fry': [['Хорошо промойте лапшу ширатаки и обжарьте её на сухой горячей сковороде 3 минуты, чтобы ушла вода.', 'Тонко нарежьте перец, морковь и капусту — подойдут и любые подвядшие овощи из холодильника.', 'Обжаривайте чеснок и овощи на кунжутном масле 4 минуты, сдвиньте их в сторону и пожарьте яйца-болтунью.', 'Добавьте лапшу и соевый соус, перемешивайте 2 минуты и посыпьте зелёным луком.'], ['Ширатаки кеспесін жақсылап жуып, суы кетуі үшін ыстық құрғақ табада 3 минут қуырыңыз.', 'Бұрышты, сәбізді және қырыққабатты жұқа тураңыз — тоңазытқыштағы солған кез келген көкөніс те жарайды.', 'Сарымсақ пен көкөністерді күнжіт майында 4 минут қуырып, шетке ысырып, жұмыртқаны араластыра қуырыңыз.', 'Кеспе мен соя соусын қосып, 2 минут араластырыңыз да, көк пиязбен себіңіз.']],
  'Smashed Cucumber Salad': [['Положите огурцы на доску и раздавите их плоской стороной ножа — мягкие, слегка гнущиеся огурцы отлично подойдут.', 'Разорвите на кусочки размером с укус, посолите и оставьте на 5 минут, затем слейте воду.', 'Смешайте тёртый чеснок, соевый соус, рисовый уксус и кунжутное масло, перемешайте с огурцами.', 'Посыпьте чили-крисп и ешьте сразу.'], ['Қиярларды тақтайға қойып, пышақтың жалпақ жағымен езіп жіберіңіз — жұмсақ, сәл майысатын қиярлар өте жақсы жарайды.', 'Бір тістем бөліктерге жыртып, тұздап, 5 минут қалдырыңыз, содан кейін суын төгіп тастаңыз.', 'Үккіштен өткізілген сарымсақ, соя тұздығы, күріш сірке суы және күнжіт майын араластырып, қиярлармен былаңыз.', 'Үстіне чили крисп салып, бірден жеңіз.']],
  'Smashed Potatoes with Aioli': [['Отварите молодой картофель целиком в подсоленной воде 15–18 минут, пока нож не будет входить легко; слейте воду и дайте ему подсохнуть 5 минут.', 'Разогрейте духовку до 230 °C. Выложите картофель на смазанный маслом противень и прижмите каждую картофелину дном стакана, чтобы она треснула и расплющилась.', 'Смажьте оливковым маслом с давленым чесноком, посолите и запекайте 25 минут, пока края не станут золотистыми и хрустящими.', 'За 3 минуты до готовности натрите сверху пармезан, затем посыпьте рубленой петрушкой.', 'Подавайте горячим с айоли для макания.'], ['Жас картопты тұздалған суда тұтасымен 15–18 минут пісіріңіз, пышақ оңай кіретін болсын; суын төгіп, 5 минут кептіріңіз.', 'Пешті 230 °C-қа дейін қыздырыңыз. Картопты май жағылған табаққа салып, әрқайсысын стақанның түбімен жарылғанша басып жалпайтыңыз.', 'Езілген сарымсақ қосылған зәйтүн майымен жағып, тұздап, жиектері алтын түсті әрі қытырлақ болғанша 25 минут пісіріңіз.', 'Дайын болуына 3 минут қалғанда үстіне пармезан үгітіп, кейін туралған ақжелкен себіңіз.', 'Айолиге малып жеу үшін ыстықтай ұсыныңыз.']],
  'Soft Fruit Compote': [['Ушибленные или мягкие фрукты? Отрежьте испорченные места, остальное нарежьте.', 'Залейте 2 литрами воды, добавьте сахар и доведите до кипения.', 'Варите 10 минут, остудите и пейте холодным. Фрукты тоже съешьте!'], ['Соғылған немесе жұмсақ жеміс бар ма? Бүлінген жерлерін кесіп тастап, қалғанын тураңыз.', '2 литр сумен құйып, қант қосыңыз да, қайнатыңыз.', '10 минут қайнатыңыз, суытып, салқын күйінде ішіңіз. Жемістерін де жеңіз!']],
  'Soft Tomato Soup': [['Перезрелые мягкие помидоры дают лучший вкус!', 'Обжарьте лук и чеснок, добавьте нарезанные помидоры и тушите 20 минут.', 'Взбейте блендером с базиликом, добавьте сливки и приправьте.'], ['Тым піскен жұмсақ қызанақтар ең жақсы дәм береді!', 'Пияз бен сарымсақты қуырып, туралған қызанақ қосып, 20 минут бұқтырыңыз.', 'Базиликпен блендермен езіп, кілегей қосыңыз да дәмдеңіз.']],
  'Sour Kefir Khvorost': [['Кефир, ставший слишком кислым для питья, здесь идеален — он делает тесто хрустящим.', 'Смешайте кефир, яйцо, сахар, соду и щепотку соли; вмесите муку до крутого теста. Дайте отдохнуть 15 минут.', 'Раскатайте очень тонко, нарежьте полосками 3×10 см, сделайте посередине надрез и протяните через него один конец.', 'Жарьте в горячем масле по 30–40 секунд с каждой стороны до золотистого цвета. Выложите на бумагу, посыпьте сахарной пудрой.', 'Процедите масло и сохраните для следующей жарки.'], ['Ішуге болмайтындай ащы болған айран мұнда өте жақсы — ол қамырды қытырлақ етеді.', 'Айран, жұмыртқа, қант, сода және бір ұстам тұзды араластырыңыз; қатты қамыр болғанша ұн қосып илеңіз. 15 минут демдеңіз.', 'Өте жұқа жайып, 3×10 см жолақтап кесіңіз, ортасынан тілік жасап, бір ұшын соның арасынан өткізіңіз.', 'Қызған майда әр жағынан 30–40 секундтан алтын түске боялғанша қуырыңыз. Қағазға салып, қант ұнтағын себіңіз.', 'Майды сүзіп, келесі қуыру үшін сақтап қойыңыз.']],
  'Spaghetti Bolognese': [['Обжарьте мелко нарезанные лук, морковь и чеснок на масле 6 минут.', 'Добавьте говядину и обжарьте, разбивая ложкой.', 'Влейте помидоры и тушите на слабом огне 30 минут.', 'Отварите спагетти, слейте воду и перемешайте с соусом.'], ['Майда туралған пияз, сәбіз және сарымсақты майда 6 минут қуырыңыз.', 'Сиыр етін қосып, қасықпен ұсақтап қуырыңыз.', 'Қызанақ құйып, баяу отта 30 минут бұқтырыңыз.', 'Спагеттиді пісіріп, суын сүзіп, тұздықпен араластырыңыз.']],
  'Spam Musubi': [['Промойте рис для суши до прозрачной воды и сварите его в 360 мл воды; держите под крышкой, чтобы не остыл.', 'Нарежьте спам вдоль на 8 ломтиков толщиной около 1 см.', 'Обжарьте ломтики на сухой сковороде по 2 минуты с каждой стороны до хруста, затем добавьте соевый соус, сахар и мирин и переворачивайте, пока не покроются глазурью.', 'Разрежьте листы нори пополам. Застелите пустую банку из-под спама плёнкой и выложите слой риса, ломтик спама и ещё слой риса, плотно прижимая.', 'Выложите брусок на полоску нори, плотно заверните и закрепите край рисинкой. Повторите с остальными.'], ['Суши күрішін су мөлдір болғанша жуып, 360 мл суда пісіріңіз; суып қалмас үшін қақпағын жабулы ұстаңыз.', 'Спамды бойлай қалыңдығы шамамен 1 см болатын 8 тілімге кесіңіз.', 'Тілімдерді құрғақ табада әр жағын 2 минуттан қытырлақ болғанша қуырыңыз, содан кейін соя соусын, қант пен миринді қосып, глазурьмен қапталғанша аударыңыз.', 'Нори парақтарын екіге бөліңіз. Бос спам банкасына үлдір төсеп, бір қабат күріш, бір тілім спам және тағы бір қабат күріш салып, мықтап басыңыз.', 'Кесекті нори жолағына шығарып, тығыз ораңыз да, шетін бір түйір күрішпен жапсырыңыз. Қалғандарымен де солай қайталаңыз.']],
  'Spanakopita Quesadilla': [['Прогрейте шпинат на сухой сковороде 2 минуты — уставшие, чуть подвядшие листья идеальны. Отожмите воду и порубите.', 'Смешайте с раскрошенной фетой, тёртой моцареллой, нарезанным зелёным луком, рубленым укропом (со стеблями) и соком лимона.', 'Распределите начинку на половине каждой тортильи и сложите пополам.', 'Подрумяньте на сухой сковороде по 2–3 минуты с каждой стороны, пока не станет хрустящей и сыр не расплавится. Нарежьте треугольниками.'], ['Саумалдықты құрғақ табада 2 минут қыздырыңыз — шаршаған, сәл солған жапырақтар өте қолайлы. Суын сығып, тураңыз.', 'Ұнтақталған фета, үгілген моцарелла, туралған жасыл пияз, ұсақталған аскөк (сабақтарымен) және лимон шырынымен араластырыңыз.', 'Салманы әр тортильяның жартысына жайып, екіге бүктеңіз.', 'Құрғақ табада әр жағын 2–3 минуттан қытырлақ болып, ірімшік ерігенше қыздырыңыз. Үшбұрыштап кесіңіз.']],
  'Stale Baursak Bread Pudding': [['Разломайте вчерашние твёрдые баурсаки на кусочки и выложите в смазанную форму для запекания.', 'Взбейте молоко, яйца и сахар, залейте баурсаки и оставьте на 10 минут пропитаться.', 'Разложите сверху изюм и слегка вдавите его.', 'Выпекайте при 180 °C 25–30 минут до золотистого цвета и плотной консистенции. Подавайте тёплым с чаем.'], ['Кешегі қатып қалған бауырсақтарды бөліктеп, майланған пісіру қалыбына салыңыз.', 'Сүт, жұмыртқа және қантты шайқап, бауырсақтардың үстіне құйыңыз да, 10 минут сіңуге қалдырыңыз.', 'Үстіне мейізді шашып, сәл басыңыз.', '180 °C температурада 25–30 минут алтын түске боялып, қатқанша пісіріңіз. Шаймен жылы күйінде беріңіз.']],
  'Stale Bread Croutons': [['Нарежьте чёрствый хлеб маленькими кубиками — зачерствевший хлеб подходит даже лучше.', 'Перемешайте с маслом, раздавленным чесноком и щепоткой соли.', 'Запекайте при 190 °C 10–12 минут, один раз перемешав, до золотистого цвета.', 'Храните в банке до недели. Отлично подходят для супов и салатов!'], ['Кеуіп қалған нанды шағын текшелерге тураңыз — қатқан нан одан да жақсы.', 'Май, ұсақталған сарымсақ және бір шымшым тұзбен араластырыңыз.', '190 °C-та 10–12 минут, бір рет араластырып, алтын түсті болғанша пісіріңіз.', 'Құмырада бір аптаға дейін сақтаңыз. Сорпа мен салатқа тамаша!']],
  'Stale Bread French Toast': [['Сухой хлеб или хлеб двух-трёхдневной давности здесь идеален: он пропитывается и не разваливается.', 'Взбейте яйца, молоко, сахар, корицу и щепотку соли на широкой тарелке.', 'Вымачивайте каждый ломтик по 10 секунд с каждой стороны.', 'Жарьте на сливочном масле на среднем огне до золотистого цвета, по 2–3 минуты с каждой стороны. Подавайте с вареньем или фруктами, которые нужно съесть.'], ['Құрғақ немесе 2–3 күндік нан мұнда өте жақсы: ол сіңеді және быт-шыт болмайды.', 'Жұмыртқа, сүт, қант, даршын және бір ұстам тұзды кең табақта шайқаңыз.', 'Әр тілімді әр жағынан 10 секундтан малыңыз.', 'Сары майда орташа отта алтын түске боялғанша, әр жағынан 2–3 минуттан қуырыңыз. Тосап немесе жеуге тиіс жемістермен беріңіз.']],
  'Steak with Herb-Stem Chimichurri': [['Достаньте стейк из холодильника за 20 минут до готовки и хорошо посолите.', 'Мелко порубите петрушку и кинзу — вместе со стеблями: в них больше всего вкуса, так что ничего не уходит в мусор.', 'Смешайте зелень с тёртым чесноком, орегано, хлопьями чили, уксусом и оливковым маслом; посолите и дайте постоять 10 минут.', 'Обжарьте стейк на очень горячей сухой сковороде по 3–4 минуты с каждой стороны, затем дайте ему отдохнуть 5 минут на доске.', 'Нарежьте поперёк волокон и полейте чимичурри. Оставшийся соус хранится 5 дней в банке в холодильнике.'], ['Стейкті пісіруден 20 минут бұрын тоңазытқыштан шығарып, жақсылап тұздаңыз.', 'Ақжелкен мен кинзаны сабақтарымен бірге ұсақ тураңыз — дәмі көбіне сабағында, сондықтан ештеңе қоқысқа кетпейді.', 'Көкөністі үгітілген сарымсақ, орегано, чили үлпектері, сірке суы және зәйтүн майымен араластырыңыз; тұздап, 10 минут қоя тұрыңыз.', 'Стейкті өте ыстық құрғақ табада әр жағын 3–4 минуттан қуырып, сосын тақтайда 5 минут демалдырыңыз.', 'Талшықтарына көлденең турап, үстіне чимичурри құйыңыз. Қалған тұздық тоңазытқышта банкіде 5 күн сақталады.']],
  'Stracciatella Tomato Toast': [['Поджарьте слегка чёрствый хлеб на закваске на сухой сковороде или в тостере до хруста — хлеб вчерашней выпечки подходит лучше всего.', 'Разрежьте помидоры черри пополам (мягкие идеальны), посолите и оставьте на 5 минут, чтобы они дали сок.', 'Выложите страчателлу ложкой на тост, сверху положите помидоры с их соком.', 'Закончите рваным базиликом, оливковым маслом и чёрным перцем.'], ['Сәл ескі ашытқылы нанды құрғақ табада немесе тостерде қытырлақ болғанша қуырыңыз — кешегі нан ең жақсы жарайды.', 'Шие қызанақты екіге кесіңіз (жұмсақтары өте жақсы), тұздап, шырын шығарсын деп 5 минут қалдырыңыз.', 'Страччателланы қасықпен тостың үстіне салып, үстіне қызанақты шырынымен бірге қойыңыз.', 'Жыртылған базилик, зәйтүн майы және қара бұрышпен аяқтаңыз.']],
  'Strawberry Daifuku Mochi': [['Оберните каждую клубнику (удалите зелёную верхушку) тонким слоем пасты из красной фасоли. Мягкая клубника, которую нужно съесть сегодня, идеальна.', 'Взбейте рисовую муку, сахар и 170 мл воды до гладкого теста. Готовьте в микроволновке под крышкой 1 мин, перемешайте, затем ещё 1 мин и 30 с — оно станет липким и глянцевым.', 'Посыпьте стол обжаренным кукурузным крахмалом. Разделите горячее тесто на 6 частей и расплющите каждую руками в крахмале.', 'Положите в центр клубнику в пасте, защипните тесто и скатайте в шарик.', 'Съешьте в тот же день — моти твердеет в холодильнике. Разрежьте пополам для знаменитого кадра в Instagram! 📸'], ['Әр құлпынайды (жасыл жапырағын алып тастап) қызыл үрмебұршақ пастасының жұқа қабатымен орап шығыңыз. Бүгін жеуге тиіс жұмсақ құлпынай өте жарайды.', 'Күріш ұны, қант және 170 мл суды біртекті қамыр болғанша шайқаңыз. Микротолқынды пеште жауып 1 мин пісіріңіз, араластырыңыз, содан кейін тағы 1 мин және 30 с — ол жабысқақ әрі жылтыр болады.', 'Үстелге қуырылған жүгері крахмалын себіңіз. Ыстық қамырды 6 бөлікке бөліп, әрқайсысын крахмалды қолмен жайыңыз.', 'Ортасына оралған құлпынайды салып, қамырды түйіп, шарик етіп домалатыңыз.', 'Сол күні жеңіз — моти тоңазытқышта қатады. Әйгілі Instagram суреті үшін екіге кесіңіз! 📸']],
  'Student Lagman Stir-Fry': [['Варите лапшу 4–5 минут, слейте воду и промойте холодной водой.', 'Нарежьте говядину тонкими полосками и обжарьте на горячей сковороде с маслом 4 минуты.', 'Добавьте нарезанные лук и перец, жарьте 3 минуты, затем добавьте помидор кубиками и чеснок ещё на 3 минуты.', 'Перемешайте лапшу на сковороде с солью, перцем и небольшим количеством соевого соуса до горячего состояния.'], ['Кеспені 4–5 минут пісіріп, суын сүзіп, суық сумен шайыңыз.', 'Сиыр етін жұқа жолақтап кесіп, қызған табада майда 4 минут қуырыңыз.', 'Тілімдеген пияз бен бұрышты қосып, 3 минут қуырыңыз, содан кейін текшелеп туралған қызанақ пен сарымсақты тағы 3 минутқа қосыңыз.', 'Кеспені табада тұз, бұрыш және аздап соя тұздығымен ысығанша араластырыңыз.']],
  'Stuffed Peppers': [['Варите рис до полуготовности 8 минут. Обжарьте лук и морковь.', 'Смешайте говядину, рис и половину овощей, приправьте.', 'Срежьте верхушки перцев, удалите семена и нафаршируйте их.', 'Поставьте в кастрюлю, залейте водой с томатной пастой и добавьте остальные овощи. Тушите 40 минут. Подавайте со сметаной.'], ['Күріштің жартылай дайын болуы үшін 8 минут қайнатыңыз. Пияз бен сәбізді қуырыңыз.', 'Сиыр еті, күріш және көкөністердің жартысын араластырып, дәмдеңіз.', 'Бұрыштардың үстін кесіп, тұқымын алып, толтырыңыз.', 'Кастрюльге салып, томат пастасы қосылған суды құйып, қалған көкөністерді қосыңыз. 40 минут бұқтырыңыз. Қаймақпен беріңіз.']],
  'Syrniki (Cottage Cheese Pancakes)': [['Разомните творог, смешайте с яйцом, сахаром и щепоткой соли.', 'Добавьте муку и замесите мягкое тесто.', 'Сформируйте небольшие лепёшки и обваляйте в небольшом количестве муки.', 'Жарьте на масле по 3 минуты с каждой стороны на среднем огне. Подавайте со сметаной или вареньем.'], ['Сүзбені езіп, жұмыртқа, қант және бір шымшым тұзбен араластырыңыз.', 'Ұн қосып, жұмсақ қамыр илеңіз.', 'Шағын тоқаштар жасап, аздап ұнға аунатыңыз.', 'Орташа отта майда әр жағынан 3 минуттан қуырыңыз. Қаймақпен немесе тосаппен беріңіз.']],
  'Tary with Milk & Butter': [['Подогрейте молоко в небольшой кастрюле до горячего, но не до кипения.', 'Положите тары (обжаренное пшено) в миску и залейте горячим молоком.', 'Добавьте сливочное масло и сахар, перемешайте и подождите 3 минуты, чтобы зёрна немного размякли.', 'Ешьте тёплым с чашкой чая — это классический казахский завтрак, который хранится месяцами в кладовой.'], ['Сүтті шағын кастрюльде ыстық болғанша, бірақ қайнатпай жылытыңыз.', 'Тарыны (қуырылған тары) табаққа салып, үстіне ыстық сүт құйыңыз.', 'Сары май мен қантты қосып, араластырыңыз да, дәндер сәл жұмсарсын деп 3 минут күтіңіз.', 'Бір кесе шаймен жылы күйінде жеңіз — бұл қоймада айлап сақталатын классикалық қазақ таңғы асы.']],
  'Teriyaki Salmon Bowl': [['Сварите рис и приготовьте брокколи на пару.', 'Обжаривайте лосось кожей вниз 4 минуты, переверните и готовьте ещё 2.', 'Влейте в сковороду соус терияки и глазируйте рыбу 1 минуту.', 'Подавайте на рисе с брокколи и кунжутом.'], ['Күріш пісіріп, брокколиді бумен дайындаңыз.', 'Лососьті терісімен төмен қаратып 4 минут қуырыңыз, аударып, тағы 2 минут пісіріңіз.', 'Табаға терияки тұздығын құйып, балықты 1 минут жылтыратып қуырыңыз.', 'Күріштің үстіне брокколи және күнжітпен салып беріңіз.']],
  'Teriyaki Tofu Bowl': [['Отожмите тофу полотенцем и нарежьте кубиками.', 'Обжарьте до хруста со всех сторон, добавьте терияки и глазируйте.', 'Подавайте на рисе с эдамаме и тёртой морковью.'], ['Тофуды сүлгімен сығып, кубиктерге тураңыз.', 'Барлық жағынан қытырлақ болғанша қуырып, терияки қосып, жылтыратыңыз.', 'Күріштің үстіне эдамаме және үйкелген сәбізбен салып беріңіз.']],
  'Tomato Bruschetta': [['Нарежьте вчерашний багет ломтиками и подсушите их на сухой сковороде.', 'Натрите каждый ломтик разрезанным зубчиком чеснока.', 'Сверху выложите нарезанные кубиками помидоры, рваный базилик, соль и немного масла.'], ['Кешегі багетті тілімдеп, құрғақ табада қуырыңыз.', 'Әр тілімді жарып кесілген сарымсақ тісімен сүртіңіз.', 'Үстіне кубиктеп туралған қызанақ, жыртылған райхан, тұз және аздап май себіңіз.']],
  'Tteokbokki': [['Если тток твёрдые, замочите их на 10 минут в тёплой воде; сварите яйца вкрутую и очистите.', 'Доведите 400 мл воды до кипения и размешайте в ней кочхуджан, кочхукару, сахар, соевый соус и раздавленный чеснок.', 'Положите рисовые клёцки и варите 10–12 минут, часто помешивая, пока они не станут мягкими, а соус — густым и глянцевым.', 'В последнюю минуту добавьте яйца и зелёный лук, подавайте горячим.'], ['Ттоктар қатты болса, оларды жылы суға 10 минутқа салып қойыңыз; жұмыртқаларды қатты пісіріп, аршыңыз.', '400 мл суды қайнатып, оған кочхуджан, кочхукару, қант, соя тұздығы мен езілген сарымсақты араластырыңыз.', 'Күріш тоқаштарын салып, жиі араластыра отырып, олар жұмсарып, тұздық қоюланып жылтырағанша 10–12 минут қайнатыңыз.', 'Соңғы минутта жұмыртқа мен жасыл пиязды қосып, ыстықтай ұсыныңыз.']],
  'Tuna Pasta Salad': [['Отварите пасту, промойте холодной водой.', 'Нарежьте огурец кубиками, слейте жидкость с тунца и кукурузы.', 'Смешайте всё с майонезом и приправьте.'], ['Макаронды пісіріп, салқын сумен шайыңыз.', 'Қиярды кубиктеп тураңыз, тунец пен жүгерінің суын төгіңіз.', 'Бәрін майонезбен араластырып, дәмдеңіз.']],
  'Tushpara Soup': [['Замесите крутое тесто из муки, яйца, щепотки соли и 100 мл воды. Дайте ему отдохнуть 15 минут.', 'Смешайте говяжий фарш с половиной лука (очень мелко нарезанного), солью и перцем.', 'Раскатайте тесто тонко, нарежьте квадратами 4 см, на каждый положите немного начинки и защипните в крошечные пельмени.', 'Варите 10 минут в 1,5 л воды картофель кубиками, морковь и оставшийся лук.', 'Добавьте пельмени и варите 7–8 минут после всплытия. Подавайте с зеленью или ложкой сметаны.'], ['Ұн, жұмыртқа, бір ұстам тұз және 100 мл судан қатты қамыр илеңіз. Оны 15 минут демдеңіз.', 'Ұсақтап туралған сиыр етін пияздың жартысымен (өте майдалап туралған), тұз және бұрышпен араластырыңыз.', 'Қамырды жұқа жайып, 4 см шаршылап кесіңіз, әрқайсысына аздап салма салып, кішкентай тұшпара етіп түйіңіз.', '1,5 л суда текшелеп туралған картоп, сәбіз және қалған пиязды 10 минут қайнатыңыз.', 'Тұшпараны қосып, жоғары қалқығаннан кейін 7–8 минут пісіріңіз. Көк шөппен немесе бір қасық қаймақпен беріңіз.']],
  'Tvorog Casserole (Zapekanka)': [['Смешайте творог, яйца, сахар и манку, оставьте на 15 минут.', 'Выложите в смазанную форму и разровняйте верх сметаной.', 'Выпекайте при 180 °C 35–40 минут до золотистого цвета.'], ['Сүзбе, жұмыртқа, қант және манканы араластырып, 15 минут қойыңыз.', 'Майланған қалыпқа салып, бетін қаймақпен тегістеңіз.', '180 °C-та 35–40 минут алтын түсті болғанша пісіріңіз.']],
  'Veggie Curry from Odds and Ends': [['Подойдут любые залежавшиеся овощи — отрежьте испорченные места, остальное нарежьте.', 'Обжарьте лук с порошком карри 2 минуты.', 'Добавьте картофель, цветную капусту и кокосовое молоко со стаканом воды. Варите на слабом огне 20 минут.', 'Добавьте горошек, готовьте 3 минуты и подавайте с рисом или хлебом.'], ['Мұнда кез келген солып қалған көкөністер жарайды — бүлінген жерлерін кесіп тастап, қалғанын тураңыз.', 'Пиязды карри ұнтағымен 2 минут қуырыңыз.', 'Картоп, түсті орамжапырақ және кокос сүтін бір стакан сумен қосыңыз. Баяу отта 20 минут қайнатыңыз.', 'Бұршақты қосып, 3 минут пісіріңіз де, күріш немесе нанмен беріңіз.']],
  'Vinegret Salad': [['Отварите свёклу, картофель и морковь до мягкости, затем остудите.', 'Нарежьте всё мелкими кубиками вместе с солёными огурцами.', 'Добавьте квашеную капусту и масло, перемешайте и приправьте.'], ['Қызылша, картоп және сәбізді жұмсарғанша қайнатып, содан кейін салқындатыңыз.', 'Бәрін тұздалған қиярмен бірге ұсақ кубиктерге тураңыз.', 'Ашытылған қырыққабат пен май қосып, араластырып, дәмдеңіз.']],
  'Viral Baked Feta Pasta': [['Разогрейте духовку до 200 °C. Выложите помидоры черри в форму для запекания — мягкие, сморщенные здесь идеальны.', 'Поместите кусок феты в центр, полейте всё оливковым маслом, добавьте соль, перец и хлопья чили.', 'Запекайте 30 минут, пока помидоры не лопнут. Тем временем сварите пасту; оставьте чашку воды от варки.', 'Добавьте раздавленный чеснок, разомните фету и помидоры в кремовый соус, перемешайте с пастой и небольшим количеством воды от варки.', 'Закончите рваным базиликом. Оставшийся соус хранится 3 дня в холодильнике.'], ['Духовканы 200 °C-қа дейін қыздырыңыз. Шие қызанақты пісіру қалыбына салыңыз — жұмсақ, әжім түскендері мұнда өте жақсы.', 'Ортасына фета бөлігін қойып, бәрінің үстіне зәйтүн майын құйыңыз, тұз, бұрыш және чили ұлпаларын қосыңыз.', 'Қызанақ жарылғанша 30 минут пісіріңіз. Осы кезде пастаны қайнатыңыз; бір кесе паста қайнатқан суын қалдырыңыз.', 'Езілген сарымсақты қосып, фета мен қызанақты кремдей тұздыққа айналдыра езіңіз, пастамен және аздап паста қайнатқан сумен араластырыңыз.', 'Жыртылған базиликпен аяқтаңыз. Қалған тұздық тоңазытқышта 3 күн сақталады.']],
  'Viral Cottage Cheese Flatbread': [['Разогрейте духовку до 180 °C и застелите противень бумагой для выпечки.', 'Взбейте творог и яйца блендером до полной однородности — творог с истекающим сроком годности здесь идеален.', 'Намажьте тонким слоем (около 5 мм) на противень, приправьте перцем и выпекайте 30–35 минут до золотистого цвета и плотности.', 'Остудите 5 минут, снимите бумагу и заверните в лепёшку шпинат и половинки помидоров черри, как в тортилью.'], ['Духовканы 180 °C-қа дейін қыздырып, науаға пісіру қағазын төсеңіз.', 'Сүзбе мен жұмыртқаны мүлдем біртекті болғанша блендермен езіңіз — жарамдылық мерзімі таусылуға жақын сүзбе мұнда өте жақсы.', 'Науаға жұқалап (шамамен 5 мм) жайып, бұрыш себіп, алтын түске боялып, қатқанша 30–35 минут пісіріңіз.', '5 минут суытып, қағазын сыпырып алыңыз да, тортилья сияқты шпинат пен екіге кесілген шие қызанақты орап салыңыз.']],
  'Viral Cucumber Kewpie Salad': [['Тонко нарежьте огурец целиком — вместе с кожурой и кончиками.', 'Сложите в контейнер с крышкой, добавьте майонез Кьюпи, соевый соус, рисовый уксус и кунжутное масло.', 'Закройте крышку и энергично встряхивайте 20 секунд.', 'Посыпьте раскрошенными нори и ешьте прямо из контейнера.'], ['Қиярды түгел — қабығымен және ұштарымен бірге жұқа тураңыз.', 'Қақпағы бар ыдысқа салып, Кьюпи майонезін, соя соусын, күріш сірке суын және күнжіт майын қосыңыз.', 'Қақпағын жауып, 20 секунд қатты сілкіңіз.', 'Үгітілген нориді себіп, тікелей ыдыстан жеңіз.']],
  'Viral Pasta alla Vodka': [['Сварите пенне в подсоленной воде; перед тем как слить, оставьте чашку воды от варки.', 'Растопите сливочное масло, обжарьте нарезанный лук-шалот и чеснок 3 минуты до мягкости.', 'Добавьте томатную пасту и хлопья чили, помешивайте 3–4 минуты, пока цвет не станет кирпично-красным.', 'Влейте водку и дайте покипеть 1 минуту (алкоголь выпаривается), затем добавьте сливки.', 'Перемешайте пасту с небольшим количеством воды от варки и тёртым пармезаном до шелковистой консистенции.'], ['Пеннені тұздалған суда пісіріңіз; сүзбес бұрын бір кесе паста қайнатқан суын қалдырыңыз.', 'Сары майды ерітіп, туралған шалот пен сарымсақты жұмсарғанша 3 минут қуырыңыз.', 'Томат пастасы мен чили ұлпаларын қосып, түсі кірпіш қызыл болғанша 3–4 минут араластырыңыз.', 'Арақты құйып, 1 минут бұрқылдатыңыз (алкоголь буланып кетеді), содан кейін кілегей қосыңыз.', 'Пастаны аздап паста қайнатқан сумен және үгілген пармезанмен жібектей болғанша араластырыңыз.']],
  'Whole Roasted Branzino with Herb Stems': [['Разогрейте духовку до 220 °C. Тонко нарежьте фенхель (зелень оставьте) и разложите на противне с половиной оливкового масла и щепоткой соли.', 'Сделайте на рыбе по 3 надреза с каждой стороны. Начините брюшко ломтиками лимона, раздавленным чесноком, черешками петрушки и зеленью фенхеля — то, что обычно выбрасывают, даёт больше всего аромата.', 'Положите рыбу на фенхель, натрите остатками масла и солью и запекайте 20–25 минут, пока мясо не будет легко отходить от кости.', 'Порубите листья петрушки, посыпьте рыбу и подавайте с мягким фенхелем и соком лимона.'], ['Пешті 220 °C-қа дейін қыздырыңыз. Фенхельді жұқа тураңыз (жапырағын қалдырыңыз) да, табаға зәйтүн майының жартысымен және бір шымшым тұзбен жайыңыз.', 'Балықтың әр жағына 3 тілік жасаңыз. Ішіне лимон тілімдерін, езілген сарымсақты, ақжелкен сабақтары мен фенхель жапырақтарын салыңыз — әдетте лақтырылатын бөліктер ең көп хош иіс береді.', 'Балықты фенхельдің үстіне қойып, қалған май мен тұзбен ысқылаңыз да, еті сүйектен оңай ажырағанша 20–25 минут пісіріңіз.', 'Ақжелкен жапырақтарын турап, үстіне себіңіз де, жұмсақ фенхельмен және лимон шырынымен ұсыныңыз.']],
  'XO Sauce Egg Noodles': [['Отварите яичную лапшу по инструкции на упаковке, быстро промойте и хорошо слейте воду.', 'Взбейте яйца и мягко обжарьте их болтуньей на горячей сковороде с маслом; выложите.', 'Положите в сковороду соус XO и белые части зелёного лука и жарьте 30 секунд.', 'Добавьте лапшу и соевый соус и жарьте на сильном огне 2 минуты, верните яйца и посыпьте зелёными частями лука.'], ['Жұмыртқалы кеспені қаптамадағы нұсқаулық бойынша пісіріп, тез шайып, суын жақсылап төгіңіз.', 'Жұмыртқаны шайқап, майлы ыстық табада жұмсақ қуырыңыз; алып қойыңыз.', 'Табаға XO тұздығы мен жасыл пияздың ақ бөліктерін салып, 30 секунд қуырыңыз.', 'Кеспе мен соя тұздығын қосып, қатты отта 2 минут қуырыңыз, жұмыртқаны қайта салып, жасыл пияздың жасыл бөліктерін себіңіз.']],
  'Za\'atar Labneh Flatbread': [['Смешайте заатар с оливковым маслом, смажьте питы и подрумяньте их на горячей сковороде по 2 минуты с каждой стороны.', 'Нарежьте кубиками огурец и помидор.', 'Намажьте тёплые лепёшки толстым слоем лабне.', 'Выложите сверху овощи, полейте остатками масла с заатаром и разрежьте на треугольники.'], ['Заатарды зәйтүн майымен араластырып, питаларға жағыңыз да, ыстық табада әр жағын 2 минуттан қызартыңыз.', 'Қияр мен қызанақты текшелеп тураңыз.', 'Жылы жалпақ нандарға лабнені қалың етіп жағыңыз.', 'Үстіне көкөністерді салып, қалған заатар майын құйыңыз да, үшбұрыштап кесіңіз.']],
  'Zucchini Fritters': [['Отличный способ использовать большие или мягкие цукини. Натрите и отожмите.', 'Смешайте с яйцом, мукой, укропом и солью.', 'Жарьте ложками по 3 минуты с каждой стороны. Подавайте со сметаной.'], ['Ірі немесе жұмсақ кабачокты пайдаланудың тамаша тәсілі. Үккіштен өткізіп, сығып алыңыз.', 'Жұмыртқа, ұн, аскөк және тұзбен араластырыңыз.', 'Қасықпен салып, әр жағынан 3 минуттан қуырыңыз. Қаймақпен беріңіз.']],
};
